insert into guides (id, content) values ('e46-bbk', '{"id": "e46-bbk", "title": "Big brake upgrade", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Kits are specific to standard vs ZCP hubs; check wheel clearance", "category": "Brakes", "kind": "upgrade", "heroId": "e46-brake-hero", "heroCap": "Standard M3: 325×28 mm front, 328×20 mm rear. ZCP: 345×28 mm front, same rear.", "glance": {"timeFirst": "3–5 hr", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$700–4,000", "risk": "Wheel clearance · upsetting front/rear bias", "why": "Bigger rotors and calipers add thermal capacity for track use. The cheapest step is ZCP/CSL rotors and carriers on a standard car.", "note": "Changing the front without the rear shifts bias forward: the Buildjournal bias chart shows CSL fronts at 64.8% vs stock 66.9%."}, "lifespan": {"headline": ["Upgrade when fade appears on track"], "factors": ["Track use"], "confidence": {"level": "community", "n": 1, "note": ""}}, "variants": {"question": "Which route?", "options": [{"id": "csl", "label": "CSL/ZCP rotors + carriers", "when": "345 mm, keeps stock calipers, needs 18\" wheels", "brand": true}, {"id": "brembo", "label": "Brembo retrofit (E31 front / 996 rear)", "when": "Bolt-on to standard 325×28 rotors", "brand": true}, {"id": "kit", "label": "Complete kit", "when": "StopTech ST-40/60, Brembo GT, AP"}]}, "should": {"yesIf": ["Fade on track with good pads and fluid", "More power added"], "codes": [], "notes": ["Fresh fluid and track pads fix most fade before a BBK is needed."], "confidence": {"level": "community", "n": 1, "note": ""}}, "parts": [{"name": "Turner CSL/ZCP rotor + carrier package", "price": "$700–1,200", "tier": "aftermarket", "only": ["csl"]}, {"name": "Brembo E31 front calipers + 996 rear calipers + carriers", "price": "$800–1,500 used", "tier": "aftermarket", "only": ["brembo"]}, {"name": "Complete big brake kit", "price": "$2,000–4,000", "tier": "aftermarket", "only": ["kit"]}, {"name": "Track pads to suit", "price": "$200–400", "tier": "aftermarket"}, {"name": "DOT 4 fluid", "price": "1 L", "tier": "oe"}], "aftermarket": [{"name": "Turner CSL brake package", "note": "OE CSL carriers + 345 mm floating rotors, any E46 M3 pad, about an hour", "price": "$700+"}, {"name": "StopTech ST-40", "note": "Front kit; Buildjournal ran them before going to Brembo", "price": "$2,000+"}], "tools": [{"name": "Torque wrench to 120 Nm"}, {"name": "Pressure bleeder"}], "before": ["Check your wheels clear the kit: CSL rotors need 18\" wheels per Turner."], "steps": [{"title": "Fit the front", "blocks": [{"t": "text", "b": "Remove the stock caliper and carrier. Fit the new carrier/caliper and rotor."}, {"t": "torque", "label": "Front caliper/carrier to knuckle", "nm": 110, "c": {"level": "varies", "n": 3, "note": "81 ft-lb per Buildjournal and most E46 M3 sheets."}, "alt": [80]}]}, {"title": "Fit the rear", "blocks": [{"t": "text", "b": "Fit the rear carrier and rotor (with rotor screws), then caliper."}, {"t": "torque", "label": "Rear carrier to spindle", "nm": 65, "c": {"level": "medium", "n": 2, "note": "48 ft-lb per Buildjournal."}}], "only": ["brembo", "kit"]}, {"title": "Bleed and bed", "blocks": [{"t": "text", "b": "Bleed fully and bed the pads. Check bias on a quiet road before the track."}], "caution": true}], "alsoReplace": [{"name": "Stainless lines", "why": "Many kits include them."}], "check": {"tab": "Check it", "title": "After fitting", "illId": "e46-brake-hero", "illCap": "Rotor sizes.", "rows": [{"see": "Caliper touches wheel", "means": "Clearance.", "do": "Spacers or different wheels."}, {"see": "Fronts lock early", "means": "Bias too far forward.", "do": "Stronger rear pad."}, {"see": "Firm pedal, no fade", "means": "Done.", "do": ""}], "c": {"level": "community", "n": 2, "note": ""}}, "aftercare": ["Re-torque after the first track session."], "disagreements": [{"topic": "CSL rotors or a full kit", "pos": "Turner calls the CSL package an inexpensive alternative; full kits add more thermal capacity.", "call": "CSL rotors for most track-day drivers."}], "sources": ["Turner Motorsport CSL/ZCP rotor package", "Buildjournal E46 M3 Brembo retrofit and brake bias chart", "e46fanatics comprehensive E46 brake upgrade guide", "GiroDisc E46 M3 rotors"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-brake-flush', '{"id": "e46-brake-flush", "title": "Brake fluid flush & bleed", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "6MT cars share the reservoir with the clutch", "category": "Brakes", "kind": "repair", "heroId": "e46-brake-hero", "heroCap": "Flush order per BMW: rear right, rear left, front right, front left.", "glance": {"timeFirst": "1 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$30–60", "risk": "Running the reservoir dry · air in the DSC unit", "why": "Brake fluid absorbs water and its boiling point drops. Fresh fluid every two years keeps the pedal firm, especially on track.", "note": "A routine flush doesn''t need a scan tool; BMW''s DSC routine is for master cylinder or hydraulic-unit work."}, "lifespan": {"headline": ["Every 2 years or 30,000 miles"], "factors": ["Track days: before each event"], "confidence": {"level": "medium", "n": 1, "note": "Turner."}}, "variants": {"question": "Transmission?", "options": [{"id": "mt", "label": "6-speed manual", "when": "Flush the clutch slave too"}, {"id": "smg", "label": "SMG", "when": "Brakes only; SMG uses its own fluid"}]}, "should": {"yesIf": ["Two years since the last flush", "Spongy pedal", "Track day coming"], "codes": [], "notes": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "parts": [{"name": "DOT 4 low-viscosity brake fluid", "price": "1 L", "tier": "oe", "note": "BMW calls for DOT 4 LV on DSC3 cars"}], "aftermarket": [{"name": "Motul RBF 660 / ATE Typ 200", "note": "Higher boiling point for track use", "price": "$20–30"}], "tools": [{"name": "Pressure bleeder", "note": "BMW uses a brake fluid changer on the reservoir"}, {"name": "Clear hose and catch bottle"}, {"name": "11 mm bleeder wrench"}], "before": ["Fill the bleeder with fresh fluid; never let the reservoir run low."], "steps": [{"title": "Pressurise", "blocks": [{"t": "text", "b": "Fit the pressure bleeder to the reservoir and pressurise."}]}, {"title": "Bleed each corner", "blocks": [{"t": "text", "b": "Rear right, rear left, front right, front left. Open each bleeder until clear, bubble-free fluid runs, then close."}, {"t": "note", "b": "BMW''s procedure: open the bleeder until clear fluid emerges, in this order."}]}, {"title": "Bleed the clutch", "blocks": [{"t": "text", "b": "Bleed the slave cylinder on the transmission until clear fluid runs."}], "only": ["mt"]}, {"title": "Finish", "blocks": [{"t": "text", "b": "Remove the bleeder, set the level to MAX, and pump the pedal before driving."}]}], "alsoReplace": [{"name": "Stainless lines", "why": "If you''re bleeding anyway."}], "check": {"tab": "Check it", "title": "After the flush", "illId": "e46-brake-hero", "illCap": "Bleed order.", "rows": [{"see": "Firm pedal", "means": "Done.", "do": ""}, {"see": "Spongy pedal", "means": "Air in a line.", "do": "Bleed again."}, {"see": "ABS/DSC light", "means": "Air in the hydraulic unit or low fluid.", "do": "Check level; a scan-tool bleed may be needed."}], "c": {"level": "medium", "n": 1, "note": ""}}, "aftercare": ["Check for leaks at the bleeders."], "disagreements": [], "sources": ["BMW TIS 34 00 050 Bleeding brake system with DSC3", "Turner Motorsport brake fluid kits"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-brake-lines-ss', '{"id": "e46-brake-lines-ss", "title": "Stainless brake lines", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Front, rear and clutch lines sold separately", "category": "Brakes", "kind": "upgrade", "heroId": "e46-brake-hero", "heroCap": "Flexible hoses run from the hard lines to each caliper.", "glance": {"timeFirst": "2–3 hr", "timeRepeat": "1.5 hr", "difficulty": 2, "cost": "$100–200", "risk": "Rounding a hard-line fitting", "why": "Braided lines expand less than old rubber hoses, giving a firmer, more consistent pedal on track.", "note": "Bleed fully afterwards."}, "lifespan": {"headline": ["Rubber hoses age out by ~10–15 years"], "factors": ["Age"], "confidence": {"level": "community", "n": 1, "note": ""}}, "should": {"yesIf": ["Original rubber hoses", "Track use", "Cracked hoses"], "codes": [], "notes": [], "confidence": {"level": "community", "n": 1, "note": ""}}, "parts": [{"name": "Stainless line kit (4 lines)", "price": "$100–180", "tier": "aftermarket"}, {"name": "Clutch line (6MT)", "price": "$40", "tier": "aftermarket"}, {"name": "DOT 4 fluid", "price": "1 L", "tier": "oe"}], "aftermarket": [], "tools": [{"name": "Flare-nut wrenches"}, {"name": "Pressure bleeder"}], "before": ["Clamp or plug lines to limit fluid loss."], "steps": [{"title": "Remove the old hose", "blocks": [{"t": "text", "b": "Undo the hard-line fitting with a flare-nut wrench, then the caliper end."}]}, {"title": "Fit the new line", "blocks": [{"t": "text", "b": "Fit with new washers, route it so it doesn''t twist through full steering lock and suspension travel, and tighten per the kit''s instructions."}], "caution": true}, {"title": "Bleed", "blocks": [{"t": "text", "b": "Bleed every corner, as in the flush guide."}]}], "alsoReplace": [{"name": "Brake fluid", "why": "You''re bleeding anyway."}], "check": {"tab": "Check it", "title": "After fitting", "illId": "e46-brake-hero", "illCap": "Hose locations.", "rows": [{"see": "Line touches tyre at lock", "means": "Routing.", "do": "Re-route."}, {"see": "Weep at a fitting", "means": "Not sealed.", "do": "New washer."}, {"see": "Firm pedal", "means": "Done.", "do": ""}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": ["Recheck fittings after first drive."], "disagreements": [], "sources": ["General BMW practice"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-brake-pads', '{"id": "e46-brake-pads", "title": "Brake pads", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Standard and ZCP M3 calipers take the same pads, per Turner''s CSL rotor package", "category": "Brakes", "kind": "repair", "heroId": "e46-brake-hero", "heroCap": "Single-piston sliding calipers front and rear. Standard M3: 325×28 mm front, 328×20 mm rear. ZCP: 345×28 mm front, same rear.", "glance": {"timeFirst": "1–1.5 hr per axle", "timeRepeat": "45 min", "difficulty": 2, "cost": "$80–350", "risk": "Forgetting the wear sensor · not bedding the pads", "why": "Pads are the cheapest performance change on the car: a track pad transforms fade resistance, a street pad keeps dust and noise down.", "note": "Replace the wear sensor whenever its light came on; it''s single-use once worn through."}, "lifespan": {"headline": ["~25,000–40,000 miles street"], "factors": ["Track days", "Aggressive pads"], "inspect": ["Look through the wheel at every oil change"], "confidence": {"level": "community", "n": 1, "note": ""}}, "variants": {"question": "Which axle?", "options": [{"id": "f", "label": "Front"}, {"id": "r", "label": "Rear"}, {"id": "fr", "label": "Both"}]}, "should": {"yesIf": ["Pad wear light", "Less than 3 mm of pad", "Going on track with street pads"], "codes": [], "notes": [], "confidence": {"level": "community", "n": 1, "note": ""}}, "parts": [{"name": "Front pad set", "price": "$70–250", "tier": "oem", "only": ["f", "fr"]}, {"name": "Rear pad set", "price": "$60–200", "tier": "oem", "only": ["r", "fr"]}, {"name": "Pad wear sensor", "price": "$15", "tier": "oe", "note": "Replace if the warning came on"}, {"name": "Brake grease for slide pins", "price": "$8"}], "aftermarket": [{"name": "Street performance and track pads", "note": "Hawk, Pagid, Ferodo, PFC and others: match compound to use, and balance front/rear", "price": "$100–350"}], "tools": [{"name": "7 mm hex", "note": "Guide pins"}, {"name": "Piston spreader or large C-clamp"}, {"name": "Torque wrench"}], "before": ["Car on stands, wheels off.", "Siphon a little fluid from the reservoir if it''s full."], "steps": [{"title": "Remove the caliper", "blocks": [{"t": "text", "b": "Pop off the anti-rattle clip, remove the two guide-pin caps and guide pins, and lift the caliper off. Hang it; don''t let it hang on the hose."}]}, {"title": "Swap pads", "blocks": [{"t": "text", "b": "Remove old pads and the sensor. Push the piston back. Fit new pads and a new sensor if needed. Clean and lightly grease the pins."}]}, {"title": "Refit", "blocks": [{"t": "text", "b": "Caliper back on, guide pins in, clip on."}, {"t": "torque", "label": "Caliper guide pin bolts", "nm": 30, "c": {"level": "medium", "n": 2, "note": "Bimmerfest and an E46 torque table: 30–30.5 Nm."}}]}, {"title": "Bed the pads", "blocks": [{"t": "text", "b": "Several firm stops from about 40 mph down to 5 mph without stopping fully, then drive to cool them. Follow your pad maker''s bedding procedure if it differs."}], "caution": true}], "alsoReplace": [{"name": "Rotors", "why": "If they''re below minimum or lipped."}, {"name": "Brake fluid", "why": "Every two years."}], "check": {"tab": "Read the pads", "title": "What the old pads tell you", "illId": "e46-brake-hero", "illCap": "Caliper and rotor.", "rows": [{"see": "Even wear", "means": "Healthy.", "do": "Nothing."}, {"see": "Inner pad much thinner", "means": "Sticky slide pins.", "do": "Clean and grease the pins."}, {"see": "Tapered pads", "means": "Caliper not sliding square.", "do": "Check pins and bushings."}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": ["Pump the pedal before driving.", "Check fluid level."], "disagreements": [], "sources": ["Turner Motorsport CSL rotor package", "Buildjournal E46 M3 brake bias chart", "Bimmerfest E46 caliper torque thread", "Treedy Labs E46 torque reference"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-brake-rotors', '{"id": "e46-brake-rotors", "title": "Brake rotors (and pads)", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Standard M3: 325×28 mm front, 328×20 mm rear. ZCP: 345×28 mm front, same rear.", "category": "Brakes", "kind": "repair", "heroId": "e46-brake-hero", "heroCap": "Standard M3: 325×28 mm front, 328×20 mm rear. ZCP: 345×28 mm front, same rear. Rotors are held by a small set screw and the caliper carrier.", "glance": {"timeFirst": "1.5–2 hr per axle", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$200–900", "risk": "Ordering the wrong front size · seized rear rotor over the parking brake", "why": "Warped or worn rotors cause vibration and longer stops. Do pads at the same time.", "note": "Check your car: ZCP cars have 345 mm two-piece front rotors."}, "lifespan": {"headline": ["Every second pad change, or below minimum thickness"], "factors": ["Track use"], "confidence": {"level": "community", "n": 1, "note": ""}}, "variants": {"questions": [{"question": "Which front setup?", "options": [{"id": "std", "label": "Standard 325×28"}, {"id": "zcp", "label": "ZCP 345×28 two-piece"}]}, {"question": "Which axle?", "options": [{"id": "f", "label": "Front"}, {"id": "r", "label": "Rear"}, {"id": "fr", "label": "Both"}]}]}, "should": {"yesIf": ["Pulsing pedal", "Lip at the rotor edge", "Below the minimum stamped on the rotor"], "codes": [], "notes": [], "confidence": {"level": "community", "n": 1, "note": ""}}, "parts": [{"name": "Front rotors 325×28", "pn": "34112229529", "price": "$150–300", "tier": "oem", "only": ["std+f", "std+fr"]}, {"name": "Front rotors 345×28 (ZCP/CSL)", "pn": "34112282446", "price": "$400–800", "tier": "oem", "only": ["zcp+f", "zcp+fr"]}, {"name": "Rear rotors 328×20", "pn": "34212229379", "price": "$120–250", "tier": "oem", "only": ["r", "fr"]}, {"name": "Pads", "price": "$70–250", "tier": "oem"}, {"name": "Rotor set screws", "price": "$4", "tier": "oe"}], "aftermarket": [{"name": "GiroDisc 2-piece 345 mm", "note": "Fully floating ZCP-size rotors, reusable hats", "price": "$900+", "only": ["zcp"]}, {"name": "ECS 2-piece 345 mm", "note": "Lightweight semi-floating", "price": "$600"}, {"name": "Turner V5 rotors", "note": "Coated one-piece 325/328", "price": "$200–400"}], "tools": [{"name": "Hex for the rotor set screw"}, {"name": "Impact or breaker bar for carrier bolts"}, {"name": "Torque wrench to 120 Nm"}, {"name": "Mallet"}], "before": ["Back off the parking brake adjusters if the rear rotor won''t come off."], "steps": [{"title": "Remove caliper and carrier", "blocks": [{"t": "text", "b": "Caliper off as for pads. Remove the two carrier bolts and the carrier."}]}, {"title": "Remove the rotor", "blocks": [{"t": "text", "b": "Remove the set screw and tap the rotor off. Rear rotors may catch on the parking brake shoes: back the adjuster off through the lug hole."}]}, {"title": "Fit the new rotor", "blocks": [{"t": "text", "b": "Clean the hub face of rust, fit the rotor and set screw, then the carrier."}, {"t": "torque", "label": "Front caliper carrier bolts", "nm": 110, "c": {"level": "varies", "n": 4, "note": "Most E46 M3 references say 81 ft-lb (110 Nm); NAM3 posters also cite 70 and 80–85 Nm in other torque sheets."}, "alt": [80]}, {"t": "torque", "label": "Rear caliper carrier bolts", "nm": 65, "c": {"level": "medium", "n": 3, "note": "48 ft-lb in the NAM3 E46 M3 torque sheet, Buildjournal and an E46 reference."}}, {"t": "torque", "label": "Caliper guide pin bolts", "nm": 30, "c": {"level": "medium", "n": 2, "note": "Bimmerfest and an E46 torque table: 30–30.5 Nm."}}], "caution": true}, {"title": "Bed in", "blocks": [{"t": "text", "b": "Bed the new pads and rotors together, as in the pad guide."}]}], "alsoReplace": [{"name": "Parking brake shoes", "why": "The rear rotor is off and the shoes are right there."}], "check": {"tab": "Read the rotor", "title": "Old rotor check", "illId": "e46-brake-hero", "illCap": "Rotor and caliper.", "rows": [{"see": "Below minimum thickness", "means": "Worn out.", "do": "Replace."}, {"see": "Blue patches", "means": "Overheated.", "do": "Track pads, cooling."}, {"see": "Cracks between drilled holes", "means": "Heat cracks.", "do": "Replace."}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": ["Re-torque wheels after 50 miles."], "disagreements": [{"topic": "Front carrier torque", "pos": "Torque sheets vary between 70 and 110 Nm.", "call": "110 Nm, the most-cited E46 M3 value."}], "sources": ["ECS Tuning E46 M3 rotor listings", "Turner Motorsport E46 M3 rotor listings", "e46fanatics rotor size thread", "NAM3Forum E46 M3 torque spec thread", "GiroDisc E46 M3 rotors"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-parking-brake', '{"id": "e46-parking-brake", "title": "Parking brake shoes & adjustment", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Drum-in-hat parking brake shared with other BMWs", "category": "Brakes", "kind": "repair", "heroId": "e46-brake-hero", "heroCap": "Small drum shoes sit inside each rear rotor; a star-wheel adjuster is reached through a wheel-bolt hole.", "glance": {"timeFirst": "1.5–3 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$30–80", "risk": "Adjusting cables before the shoes", "why": "A handbrake that pulls too far or won''t hold usually needs shoe adjustment, not just cable tightening.", "note": "BMW says readjust when the lever travels more than about 10 clicks."}, "lifespan": {"headline": ["Shoes last for years; adjust with every rear rotor change"], "factors": ["Driving off with it on"], "confidence": {"level": "medium", "n": 1, "note": ""}}, "variants": {"question": "What are you doing?", "options": [{"id": "adj", "label": "Adjust only"}, {"id": "shoes", "label": "New shoes + adjust"}]}, "should": {"yesIf": ["Lever travels over ~10 clicks", "Car rolls on a hill", "New rear rotors fitted"], "codes": [], "notes": [], "confidence": {"level": "medium", "n": 2, "note": "BimmerWorld adjusting-screw listing; BMW TIS 34 10 014 adjusting handbrake."}}, "parts": [{"name": "Parking brake shoe set", "price": "$30–60", "tier": "oem", "only": ["shoes"]}, {"name": "Hardware kit (springs)", "price": "$15", "tier": "oem", "only": ["shoes"]}, {"name": "Adjusting screw (if seized)", "pn": "34416851437", "price": "$12", "tier": "oe"}], "aftermarket": [], "tools": [{"name": "Flat screwdriver", "note": "For the star wheel through the bolt hole"}, {"name": "Flashlight"}], "before": ["Release the parking brake and loosen the cable nuts at the lever (lift the boot or rear console)."], "steps": [{"title": "Fit new shoes", "blocks": [{"t": "text", "b": "Remove caliper, carrier and rotor, swap the shoes and springs, and refit."}], "only": ["shoes"]}, {"title": "Adjust the shoes", "blocks": [{"t": "text", "b": "Remove one wheel bolt, rotate the wheel until the adjuster shows through the hole, and turn it until the wheel locks. BimmerWorld: left side turn UP, right side turn DOWN. Then back off 10 clicks."}, {"t": "note", "b": "Do the shoes first, both sides, before touching the cable."}], "caution": true}, {"title": "Adjust the cables", "blocks": [{"t": "text", "b": "Take up the slack evenly at the lever nuts, then check both wheels turn freely with the lever down and hold with it up."}]}], "alsoReplace": [], "check": {"tab": "Check it", "title": "After adjusting", "illId": "e46-brake-hero", "illCap": "Adjuster inside the rear rotor.", "rows": [{"see": "One wheel drags", "means": "That side too tight.", "do": "Back off a few clicks."}, {"see": "Still long lever", "means": "Cable slack or worn shoes.", "do": "New shoes."}, {"see": "Holds on a hill", "means": "Done.", "do": ""}], "c": {"level": "medium", "n": 2, "note": "BimmerWorld adjusting-screw listing; BMW TIS 34 10 014 adjusting handbrake."}}, "aftercare": ["Use the parking brake regularly so it doesn''t seize."], "disagreements": [{"topic": "How far to back off", "pos": "BimmerWorld says 10 clicks; other BMW procedures quote 8–12.", "call": "10."}], "sources": ["BimmerWorld parking brake adjusting screw listing", "BMW TIS 34 10 014 Adjusting handbrake", "bimmersport NZ handbrake adjustment"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-diff-subframe-bushings', '{"id": "e46-diff-subframe-bushings", "title": "Differential & rear subframe bushings", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "E46 M3 and Z4 M diff bushings", "category": "Bushings & mounts", "kind": "repair", "heroId": "e46-sub-hero", "heroCap": "The diff hangs from the rear subframe on two front bolts and one rear bolt; the subframe itself mounts to the body on four bushings.", "glance": {"timeFirst": "4–8 hr", "timeRepeat": "3 hr", "difficulty": 4, "cost": "$45–400", "risk": "Missing retaining washer on poly diff bushings · torque order on the diff bolts", "why": "Worn diff bushings clunk on and off the throttle. Subframe bushings add wheel hop and vague rear response.", "note": "Often combined with subframe reinforcement, since the subframe comes down for both."}, "lifespan": {"headline": ["~80,000–120,000 miles"], "factors": ["Hard launches", "More power"], "confidence": {"level": "community", "n": 1, "note": ""}}, "variants": {"question": "Which bushings?", "options": [{"id": "oe", "label": "OE rubber"}, {"id": "pf", "label": "Powerflex urethane", "when": "Diff front bushing PFR5-4621B"}, {"id": "alu", "label": "Solid aluminium", "when": "Millway, Turner solid diff mounts"}]}, "should": {"yesIf": ["Clunk on throttle transitions", "Diff moves visibly when rocked", "Doing subframe reinforcement"], "codes": [], "notes": [], "confidence": {"level": "community", "n": 1, "note": ""}}, "parts": [{"name": "OE diff and subframe bushings", "price": "$80–200", "tier": "oem", "only": ["oe"]}, {"name": "Powerflex rear diff front bushing", "pn": "PFR5-4621B", "price": "$43", "tier": "aftermarket", "only": ["pf"]}, {"name": "Millway / Turner solid aluminium diff mounts", "price": "$150–300", "tier": "aftermarket", "only": ["alu"]}], "aftermarket": [], "tools": [{"name": "Transmission jack or two floor jacks"}, {"name": "Bushing press kit"}, {"name": "Torque wrench to 180 Nm"}], "before": ["Exhaust, driveshaft at the diff and axles off the diff, or drop the subframe complete."], "steps": [{"title": "Support and drop", "blocks": [{"t": "text", "b": "Support the diff, remove the two front bolts and the rear bolt, and lower it, or drop the subframe for subframe bushings."}]}, {"title": "Press the bushings", "blocks": [{"t": "text", "b": "Press out the old bushings and in the new ones."}, {"t": "warn", "b": "A Flo-Flex buyer found the poly diff bushing pulled through without a retaining washer and kept knocking until he added one. Check your kit includes it.", "only": ["pf"]}], "timeSink": true}, {"title": "Refit in order", "blocks": [{"t": "text", "b": "Start all three diff bolts by hand. Tighten the two front bolts first, then the rear."}, {"t": "torque", "label": "Diff front mount bolts (18 mm)", "nm": 95, "c": {"level": "medium", "n": 2, "note": "e46fanatics ''Yet Another Torque Guide'' (Bentley values), matched by a second Bentley transcription."}}, {"t": "torque", "label": "Diff rear mount bolt (21 mm)", "nm": 174, "c": {"level": "medium", "n": 2, "note": "e46fanatics ''Yet Another Torque Guide'' (Bentley values), matched by a second Bentley transcription."}}], "caution": true}], "alsoReplace": [{"name": "Subframe reinforcement", "why": "Same teardown."}, {"name": "Diff fluid", "why": "Easy while it''s down."}], "check": {"tab": "Check it", "title": "Old bushing check", "illId": "e46-sub-hero", "illCap": "Diff and subframe mounts.", "rows": [{"see": "Rubber torn", "means": "Worn.", "do": "Replace."}, {"see": "Sheet metal cracked at a mount", "means": "Chassis damage.", "do": "See the reinforcement guide."}, {"see": "Firm", "means": "Fine.", "do": ""}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": ["Recheck diff bolt torque after 100 miles."], "disagreements": [], "sources": ["e46fanatics ''Yet Another Torque Guide''", "BimmerWorld Powerflex diff bushing", "Hack Engineering Millway diff bushings", "Turner solid aluminium diff mounts", "Flo-Flex buyer review (eBay)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-engine-trans-mounts', '{"id": "e46-engine-trans-mounts", "title": "Engine & transmission mounts", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Manual and SMG cars use different transmission mounts: order by VIN", "category": "Bushings & mounts", "kind": "repair", "heroId": "e46-mount-hero", "heroCap": "Two engine mounts on the front subframe and two transmission mounts on the rear crossmember.", "glance": {"timeFirst": "2–3 hr", "timeRepeat": "1.5 hr", "difficulty": 2, "cost": "$100–600", "risk": "Stiff transmission mounts with tired engine mounts", "why": "Worn mounts let the engine rock, blur shifts, and stress the shifter. Easiest done with the rod bearing job, when the mount nuts are already off.", "note": "Change engine and transmission mounts together, especially with stiffer mounts."}, "lifespan": {"headline": ["~80,000–100,000 miles"], "factors": ["Hard launches", "Oil leaks"], "confidence": {"level": "community", "n": 1, "note": ""}}, "variants": {"question": "Which mounts?", "options": [{"id": "oe", "label": "OE rubber"}, {"id": "poly", "label": "Polyurethane", "when": "Turner engine mounts, Rogue transmission mounts"}, {"id": "solid", "label": "Solid aluminium (track)", "when": "Turner kit: engine sits 5 mm lower"}]}, "should": {"yesIf": ["Clunk on throttle on/off", "Engine rocks visibly on a blip", "Doing rod bearings"], "codes": [], "notes": ["A Rogue product note lists its transmission mounts as unnecessary for SMG and automatic cars."], "confidence": {"level": "community", "n": 2, "note": ""}}, "parts": [{"name": "Engine mounts (pair)", "price": "$100–200", "tier": "oem", "only": ["oe"]}, {"name": "E46 M3 transmission mounts (manual), pair", "price": "$60–100", "tier": "oe", "only": ["oe"]}, {"name": "Turner polyurethane engine mounts", "price": "$200–300", "tier": "aftermarket", "only": ["poly"]}, {"name": "Rogue Engineering transmission mounts", "pn": "RE.TM", "price": "$69", "tier": "aftermarket", "note": "Manual cars", "only": ["poly"]}, {"name": "Turner solid aluminium engine + transmission kit", "price": "$400–600", "tier": "aftermarket", "only": ["solid"]}, {"name": "Self-locking nuts", "price": "$10", "tier": "oe"}], "aftermarket": [], "tools": [{"name": "Engine support bar or jack under the oil pan with a block of wood"}, {"name": "Torque wrench"}], "before": ["Car level on stands."], "steps": [{"title": "Support the engine", "blocks": [{"t": "text", "b": "Support the engine from above, or with a jack and a wide wooden block under the pan."}]}, {"title": "Swap the engine mounts", "blocks": [{"t": "text", "b": "Remove the mount nuts from above and below, raise the engine slightly, and swap each mount."}, {"t": "torque", "label": "Engine mount nuts", "nm": 49, "c": {"level": "single", "n": 1, "note": "TIS list posted on z4-forum for S54 cars."}}]}, {"title": "Swap the transmission mounts", "blocks": [{"t": "text", "b": "Support the transmission, unbolt the crossmember, swap the mounts on the bench and refit."}, {"t": "torque", "label": "Transmission mounts", "nm": 21, "c": {"level": "medium", "n": 2, "note": "e46fanatics ''Yet Another Torque Guide'' (Bentley values), matched by a second Bentley transcription."}}]}, {"title": "Settle and check", "blocks": [{"t": "text", "b": "Lower the engine onto the mounts, check the shifter and exhaust clearance, and road-test."}]}], "alsoReplace": [{"name": "Rod bearings", "why": "The subframe drop gives the best access."}], "check": {"tab": "Check it", "title": "Old mount check", "illId": "e46-mount-hero", "illCap": "Mount locations.", "rows": [{"see": "Rubber split or collapsed", "means": "Worn.", "do": "Replace."}, {"see": "Oil-soaked", "means": "Leak degraded it.", "do": "Fix the leak."}, {"see": "Firm", "means": "Fine.", "do": ""}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": [], "disagreements": [{"topic": "Stiff transmission mounts alone", "pos": "Owners warn that very stiff transmission mounts with stock engine mounts cause problems.", "call": "Match engine and transmission mount stiffness."}], "sources": ["Turner Motorsport E46 M3 drivetrain mount listings", "Rogue Engineering transmission mount listing", "1addicts mount threads", "z4-forum TIS torque list"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-fcab', '{"id": "e46-fcab", "title": "Front control arm bushings (FCAB)", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "E46 M3 uses 66 mm brackets (31122229623 / 624); early non-M E46s used 60 mm", "category": "Bushings & mounts", "kind": "repair", "heroId": "e46-arm-hero", "heroCap": "The FCAB sits in a bracket bolted to the frame rail at the back of each control arm.", "glance": {"timeFirst": "2–3 hr", "timeRepeat": "1.5 hr", "difficulty": 2, "cost": "$120–250", "risk": "Tightening at full droop · offset bushings rotating in the bracket", "why": "Soft or torn FCABs make the front end wander under braking. Replacing them with new rubber, or stiffer urethane or Delrin, tightens steering response.", "note": "Torque the brackets at ride height."}, "lifespan": {"headline": ["~60,000–80,000 miles"], "factors": ["Track use", "Oil leaks"], "confidence": {"level": "community", "n": 1, "note": ""}}, "variants": {"question": "Which bushings?", "options": [{"id": "oe", "label": "OE rubber with brackets", "when": "Lemförder, pre-pressed"}, {"id": "pf", "label": "Powerflex hybrid", "when": "Aluminium housing; street or track; standard or offset (+0.5° caster)", "brand": true}, {"id": "delrin", "label": "Delrin", "when": "BimmerWorld''s track preference"}]}, "should": {"yesIf": ["Wander or shimmy under braking", "Cracked or split rubber", "Doing control arms"], "codes": [], "notes": [], "confidence": {"level": "community", "n": 1, "note": ""}}, "parts": [{"name": "FCAB with bracket, left / right", "pn": "31122229623 / 31122229624", "price": "$60–90 ea", "tier": "oem", "only": ["oe"]}, {"name": "Powerflex hybrid FCAB (street/track, standard/offset)", "price": "$229–245", "tier": "aftermarket", "only": ["pf"]}, {"name": "Delrin FCAB set", "price": "$150–250", "tier": "aftermarket", "only": ["delrin"]}], "aftermarket": [], "tools": [{"name": "Bushing puller or press (non-OE routes)"}, {"name": "Torque wrench"}, {"name": "Jack"}], "before": ["Car on stands."], "steps": [{"title": "Unbolt the bracket", "blocks": [{"t": "text", "b": "Remove the two bolts holding the bracket to the frame rail and pull the bracket and bushing off the arm end."}]}, {"title": "Fit the new bushing", "blocks": [{"t": "text", "b": "OE: slide the new pre-pressed bracket on. Powerflex/Delrin: press the bushing into your bracket with its grease."}, {"t": "note", "b": "Offset urethane and Delrin bushings can rotate in the bracket. FCP Euro''s install drills a small locating hole to stop that.", "only": ["pf", "delrin"]}]}, {"title": "Tighten at ride height", "blocks": [{"t": "text", "b": "Raise the suspension to ride height, then torque the bracket bolts."}, {"t": "torque", "label": "FCAB bracket to frame rail", "nm": 60, "c": {"level": "medium", "n": 2, "note": "e46fanatics ''Yet Another Torque Guide'' (Bentley values), matched by a second Bentley transcription."}}], "caution": true}], "alsoReplace": [{"name": "Control arms", "why": "If the ball joints are worn, same job."}], "check": {"tab": "Check it", "title": "Old bushing check", "illId": "e46-arm-hero", "illCap": "Bushing location.", "rows": [{"see": "Cracks or voids", "means": "Worn.", "do": "Replace."}, {"see": "Oil-soaked", "means": "Rubber degraded by a leak.", "do": "Fix the leak too."}, {"see": "Firm", "means": "Fine.", "do": ""}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": ["Alignment."], "disagreements": [{"topic": "Urethane on the street", "pos": "Some owners find urethane harsh; BimmerWorld sells street-grade urethane.", "call": "OE or street urethane on the road."}], "sources": ["BimmerWorld Powerflex E46 M3 FCAB listings", "Turner Lemförder E46 M3 FCAB listings", "FCP Euro offset FCAB install"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-rtab', '{"id": "e46-rtab", "title": "Rear trailing arm bushings (RTAB)", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Same RTAB (33326770817) as E36/E46/Z4", "category": "Bushings & mounts", "kind": "repair", "heroId": "e46-rtab-hero", "heroCap": "The RTAB sits in the front of each rear trailing arm, held by a bracket bolted to the body.", "glance": {"timeFirst": "3–6 hr", "timeRepeat": "2–3 hr", "difficulty": 3, "cost": "$30–400", "risk": "Pressing the bushing in at the wrong angle · torquing at full droop", "why": "Worn RTABs let the rear steer itself under load and cause wheel hop. Cheap parts, but a press tool is needed.", "note": "Lowering the trailing arm makes it far easier: remove the lower shock bolt and the three bracket bolts."}, "lifespan": {"headline": ["~60,000–80,000 miles"], "factors": ["Track use", "More power"], "confidence": {"level": "community", "n": 1, "note": ""}}, "variants": {"question": "Which bushings?", "options": [{"id": "oe", "label": "OE Lemförder rubber", "when": "Updated part, needs special tools"}, {"id": "pf", "label": "Powerflex", "when": "Street or adjustable race version"}, {"id": "mono", "label": "Spherical / monoball", "when": "Turner, Syncro Design Works, SPL", "brand": true}]}, "should": {"yesIf": ["Loose rear in corners", "Wheel hop", "Cracked rubber"], "codes": [], "notes": [], "confidence": {"level": "medium", "n": 1, "note": "Turner."}}, "parts": [{"name": "RTAB, Lemförder (pair)", "pn": "33326770817", "price": "$30", "tier": "oem", "only": ["oe"]}, {"name": "Powerflex RTAB (PFR5-306 / -306G adjustable)", "price": "$110–200", "tier": "aftermarket", "only": ["pf"]}, {"name": "Monoball RTAB kit", "price": "$250–400", "tier": "aftermarket", "only": ["mono"]}], "aftermarket": [], "tools": [{"name": "RTAB press tool (e.g. CTA 7642)", "note": "Pulls the bushing through with the arm on the car"}, {"name": "BMW alignment tool 83300493688 (OE rubber)", "note": "Sets the bushing''s angle", "only": ["oe"]}, {"name": "Torque wrench"}, {"name": "Wire wheel"}], "before": ["Mark the trailing arm bracket''s position on the body: it sets rear toe."], "steps": [{"title": "Lower the trailing arm", "blocks": [{"t": "text", "b": "Remove the lower shock bolt and the three bolts holding the trailing arm bracket to the body. The arm drops enough to work on."}]}, {"title": "Press out the old bushing", "blocks": [{"t": "text", "b": "Remove the bracket from the bushing and pull the old bushing out with the press tool."}, {"t": "text", "b": "Clean the bore with a wire wheel."}], "timeSink": true}, {"title": "Press in the new bushing", "blocks": [{"t": "text", "b": "Press the new bushing in."}, {"t": "note", "b": "OE rubber must be clocked at the correct angle with BMW''s tool 83300493688.", "only": ["oe"]}], "caution": true}, {"title": "Refit and torque at ride height", "blocks": [{"t": "text", "b": "Bolt the bracket back to your marks. Raise to ride height before final torque."}, {"t": "torque", "label": "RTAB through-bolt", "nm": 110, "c": {"level": "medium", "n": 2, "note": "e46fanatics ''Yet Another Torque Guide'' (Bentley values), matched by a second Bentley transcription."}}, {"t": "torque", "label": "Trailing arm bracket to body", "nm": 77, "c": {"level": "medium", "n": 2, "note": "e46fanatics ''Yet Another Torque Guide'' (Bentley values), matched by a second Bentley transcription."}}, {"t": "torque", "label": "Rear shock to trailing arm", "nm": 100, "c": {"level": "varies", "n": 3, "note": "Most Bentley transcriptions: 100 Nm; one says 44 ft-lb."}, "alt": [60]}], "caution": true}], "alsoReplace": [{"name": "Rear subframe and diff bushings", "why": "If you''re tracking the car, the rear bushings age together."}], "check": {"tab": "Check it", "title": "Old bushing check", "illId": "e46-rtab-hero", "illCap": "RTAB location.", "rows": [{"see": "Torn or voided rubber", "means": "Worn.", "do": "Replace both."}, {"see": "Corroded bore", "means": "Hard removal.", "do": "Clean before pressing."}, {"see": "Firm", "means": "Fine.", "do": ""}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": ["Alignment."], "disagreements": [{"topic": "Monoball on the street", "pos": "Turner calls monoballs the best RTAB; some race classes ban them, and they transmit more noise.", "call": "OE or Powerflex street on a road car."}], "sources": ["Turner Motorsport RTAB listings (OE and monoball)", "FCP Euro Syncro Design Works RTAB install", "e46fanatics torque threads"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-subframe-reinforcement', '{"id": "e46-subframe-reinforcement", "title": "Rear subframe / RACP reinforcement", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Turner''s weld-in kit fits all E46s; the top-side brace has coupe and sedan versions", "category": "Bushings & mounts", "kind": "repair", "heroId": "e46-sub-hero", "heroCap": "Cracks usually start at the top of the rearmost subframe mount, most often the left rear.", "glance": {"timeFirst": "2 hr inspect · 20+ hr weld-in", "timeRepeat": "—", "difficulty": 5, "cost": "$150–2,500", "risk": "Missing a crack hidden under the mount · epoxying where welding is needed", "why": "The E46''s rear subframe mounts can tear out of the floor. BMW''s crossmember on the front mounts moved load onto the left rear, where Turner sees failures even on low-mileage cars.", "note": "Most of this is welding. The guide covers inspection, the bolt-in brace, and what to ask a fabricator for."}, "lifespan": {"headline": ["Inspect any E46 M3; reinforce preventively for track use"], "factors": ["Track use", "Sticky tyres", "More power"], "confidence": {"level": "high", "n": 3, "note": "Turner, BimmerWorld, buyer guides."}}, "variants": {"question": "How far are you going?", "options": [{"id": "inspect", "label": "Inspect only"}, {"id": "brace", "label": "Bolt-in top-side brace", "when": "Turner brace from the strut towers to the rear mounts"}, {"id": "weld", "label": "Weld-in plates (fabricator)", "when": "Turner kit or BimmerWorld kit"}]}, "should": {"yesIf": ["Buying or owning an E46 M3 with no record", "Tracking it", "Clunks from the rear with good bushings"], "codes": [], "notes": ["ECS warns cracks can hide under the subframe mounts even after a pre-purchase inspection."], "confidence": {"level": "high", "n": 2, "note": ""}}, "parts": [{"name": "Turner top-side subframe brace", "price": "$300–450", "tier": "aftermarket", "only": ["brace"]}, {"name": "Turner weld-in subframe reinforcement kit", "pn": "TDR4675412", "price": "$142", "tier": "aftermarket", "only": ["weld"]}, {"name": "New subframe bolts and nuts", "price": "$40", "tier": "oe", "only": ["weld"]}], "aftermarket": [], "tools": [{"name": "Flashlight, mirror, wire brush"}, {"name": "Torque wrench", "only": ["brace"]}], "chapters": [{"id": "ins", "title": "Inspect"}, {"id": "brace", "title": "Bolt-in brace"}, {"id": "fab", "title": "What to ask a fabricator for"}], "before": ["Car level and safely supported."], "steps": [{"title": "Look underneath", "blocks": [{"t": "text", "b": "Clean around all four subframe mounts. Look for cracks, rust lines and dented sheet metal, especially the top of the rear mounts and the left rear."}], "chapter": "ins"}, {"title": "Look in the trunk", "blocks": [{"t": "text", "b": "Lift the trunk floor covering and inspect above the rear mounts for cracks or bulging."}], "chapter": "ins"}, {"title": "Fit the top-side brace", "blocks": [{"t": "text", "b": "Fit Turner''s four-point brace linking the rear subframe mounts to both rear strut towers, per its instructions."}], "chapter": "brace", "only": ["brace"]}, {"title": "Agree the job", "blocks": [{"t": "text", "b": "BimmerWorld''s install removes the exhaust, rear suspension, subframe and diff, rosette-welds the plates, and seam-welds the original spot welds. They say partial reinforcement that skips the trunk portion isn''t advised."}, {"t": "warn", "b": "BimmerWorld calls epoxy-only installs pointless because the top mounts must be welded anyway. Some owners have epoxied plates over small cracks."}], "chapter": "fab", "only": ["weld"], "caution": true}, {"title": "While it''s apart", "blocks": [{"t": "text", "b": "Ask for new subframe and diff bushings, RTABs and diff fluid while everything is out."}], "chapter": "fab", "only": ["weld"]}], "alsoReplace": [{"name": "Diff and subframe bushings", "why": "The subframe is out."}, {"name": "RTABs", "why": "The trailing arms come off."}], "check": {"tab": "Read the floor", "title": "What you''re looking for", "illId": "e46-sub-hero", "illCap": "Subframe mount points.", "rows": [{"see": "Clean metal, no cracks", "means": "Fine for now.", "do": "Reinforce if tracking."}, {"see": "Hairline crack at a rear mount", "means": "Failure starting.", "do": "Stop tracking; weld repair + plates."}, {"see": "Mount pulling out of the floor", "means": "Serious.", "do": "Don''t drive it hard: fabricator."}], "c": {"level": "high", "n": 3, "note": "Turner, BimmerWorld, ECS."}}, "aftercare": ["Alignment after any subframe work.", "Re-inspect yearly."], "disagreements": [{"topic": "Weld or epoxy", "pos": "BimmerWorld: weld, epoxy is pointless. Some owners epoxy small cracks.", "call": "Weld."}], "sources": ["Turner Motorsport E46 subframe reinforcement kit and top-side brace", "BimmerWorld E46 rear subframe & floor reinforcement install", "StanceWorks E46 M3 subframe DIY", "bimmersport NZ semi-DIY", "ECS Tuning common E46 M3 problems"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-clutch', '{"id": "e46-clutch", "title": "Clutch & flywheel (6MT)", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "This guide covers the 6-speed manual; SMG cars share the gearbox oil but not the clutch or shifter.", "category": "Drivetrain", "kind": "repair", "heroId": "e46-drive-hero", "heroCap": "Gearbox out from below; the factory LuK dual-mass flywheel and Sachs clutch sit behind it.", "glance": {"timeFirst": "8–12 hr", "timeRepeat": "6 hr", "difficulty": 4, "cost": "$500–2,000", "risk": "Reusing flywheel bolts · disc in backwards", "why": "A slipping or chattering clutch, or a rattling dual-mass flywheel, means the gearbox comes out. Do everything behind it at once.", "note": "Flywheel bolts are single-use M12×1.5×50."}, "lifespan": {"headline": ["~80,000–120,000 miles"], "factors": ["Launches", "Track use"], "confidence": {"level": "community", "n": 1, "note": ""}}, "variants": {"question": "Which kit?", "options": [{"id": "oe", "label": "OE Sachs + LuK dual-mass"}, {"id": "sachs", "label": "Sachs Performance / HD + JB Racing flywheel", "when": "Sachs HD rated ~350 lb-ft", "brand": true}, {"id": "cm", "label": "Clutch Masters", "when": "FX100–FX350, FX725 twin-disc", "brand": true}]}, "should": {"yesIf": ["Slipping in higher gears", "Chatter on take-off", "Rattle from the flywheel at idle"], "codes": [], "notes": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "parts": [{"name": "Sachs clutch kit (disc, pressure plate, release bearing)", "price": "$350–500", "tier": "oem", "only": ["oe"]}, {"name": "LuK dual-mass flywheel", "pn": "21212229900", "price": "$600–900", "tier": "oem", "only": ["oe"]}, {"name": "Sachs Performance/HD clutch + JB Racing aluminium flywheel", "price": "$1,300–1,800", "tier": "aftermarket", "only": ["sachs"]}, {"name": "Clutch Masters kit + flywheel", "price": "$1,100–2,000", "tier": "aftermarket", "only": ["cm"]}, {"name": "Flywheel bolts M12×1.5×50 ×8", "price": "$30", "tier": "oe", "note": "Single-use"}, {"name": "Pressure plate bolts ×6", "pn": "21207548052", "price": "$12", "tier": "oe"}, {"name": "Pilot bearing, rear main seal", "price": "$30", "tier": "oe"}, {"name": "Loctite 271", "price": "$10"}], "aftermarket": [], "tools": [{"name": "Transmission jack"}, {"name": "E-Torx sockets"}, {"name": "Flywheel lock"}, {"name": "Clutch alignment tool"}, {"name": "Torque wrench to 120 Nm"}], "before": ["Exhaust, driveshaft and shifter linkage off; support the gearbox."], "steps": [{"title": "Remove the gearbox", "blocks": [{"t": "text", "b": "Unbolt the slave cylinder (don''t open the line), shifter linkage, sensors, and bellhousing bolts. Lower the gearbox on the jack."}], "timeSink": true}, {"title": "Remove the clutch and flywheel", "blocks": [{"t": "text", "b": "Loosen the pressure plate bolts evenly, remove plate and disc, then the flywheel."}]}, {"title": "Rear main seal and pilot bearing", "blocks": [{"t": "text", "b": "Replace both while you''re here."}]}, {"title": "Fit the flywheel", "blocks": [{"t": "text", "b": "New bolts with Loctite 271."}, {"t": "torque", "label": "Flywheel bolts", "nm": 115, "c": {"level": "single", "n": 1, "note": "MotoIQ Project E46 M3 (85 ft-lb, aftermarket flywheel). Use your kit''s figure if given."}}], "caution": true}, {"title": "Fit disc and pressure plate", "blocks": [{"t": "text", "b": "Disc with its bulkier side toward the gearbox (MotoIQ). Centre it with the tool, then tighten the plate bolts evenly in a star."}, {"t": "torque", "label": "Pressure plate bolts, grade 8.8", "nm": 24, "c": {"level": "medium", "n": 1, "note": "Bentley bolt-grade rule; use your kit''s value if given."}}]}, {"title": "Refit the gearbox", "blocks": [{"t": "text", "b": "New release bearing, grease the input splines lightly, refit the gearbox and everything behind it."}, {"t": "torque", "label": "Clutch slave to gearbox", "nm": 20, "c": {"level": "medium", "n": 2, "note": "Bentley via e46fanatics."}}]}], "alsoReplace": [{"name": "Guibo and CSB", "why": "Driveshaft is out."}, {"name": "Clutch slave", "why": "Cheap and accessible."}], "check": {"tab": "Read the parts", "title": "Old clutch check", "illId": "e46-drive-hero", "illCap": "Clutch and flywheel.", "rows": [{"see": "Disc worn to rivets", "means": "Due.", "do": ""}, {"see": "Blue hot spots on the flywheel", "means": "Overheating.", "do": "Replace or resurface (not DMF)."}, {"see": "Oil on the disc", "means": "Rear main seal leak.", "do": "Replace the seal."}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": ["Gentle 500-mile break-in."], "disagreements": [{"topic": "Dual-mass vs lightweight", "pos": "Lightweight flywheels sharpen response; some owners find more gear rattle.", "call": "Dual-mass for a daily; aluminium for track."}], "sources": ["Turner Motorsport E46 M3 clutch & flywheel listings", "MotoIQ Project E46 M3 part 13", "e46fanatics torque guide"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-diff', '{"id": "e46-diff", "title": "Differential fluid, rebuild & ''M clunk''", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "M Variable limited-slip diff, 3.62 final drive", "category": "Drivetrain", "kind": "repair", "heroId": "e46-drive-hero", "heroCap": "The diff is exposed at the back: fill and drain plugs are reachable without removing covers.", "glance": {"timeFirst": "45 min fluid · 4–6 hr swap", "timeRepeat": "30 min", "difficulty": 2, "cost": "$40 fluid · $1,000+ rebuild", "risk": "Wrong fluid for the M Variable diff", "why": "The M Variable diff uses a viscous-type limited slip. Fresh fluid keeps it working; worn units clunk on and off throttle (the ''M clunk''), which rebuilt units fix with a free-play delete shim.", "note": "Capacity is about 1.2 quarts."}, "lifespan": {"headline": ["Fluid every 50,000 miles or after track use"], "factors": ["Track days"], "confidence": {"level": "community", "n": 2, "note": ""}}, "variants": {"question": "What are you doing?", "options": [{"id": "fluid", "label": "Fluid change"}, {"id": "rebuilt", "label": "Fit a rebuilt diff", "when": "Diffsonline or RacingDiffs exchange units", "brand": true}]}, "should": {"yesIf": ["Clunk on throttle transitions", "Whine from the rear", "No fluid record"], "codes": [], "notes": [], "confidence": {"level": "medium", "n": 2, "note": ""}}, "parts": [{"name": "Diff fluid (Castrol SAF-XJ recommended by Diffsonline)", "price": "~1.2 qt", "tier": "oe"}, {"name": "Rebuilt M Variable diff (exchange)", "price": "$1,000–2,500 + core", "tier": "aftermarket", "only": ["rebuilt"]}], "aftermarket": [{"name": "Diffsonline rebuilt diff", "note": "Stock 3.62 ratio, improved M Variable unit, core exchange", "price": "varies"}, {"name": "RacingDiffs rebuilt LSD", "note": "Clunk fix with free-play delete shim; performance clutch pack", "price": "$1,100+"}], "tools": [{"name": "Hex socket for the plugs"}, {"name": "Fluid pump"}, {"name": "Torque wrench"}], "before": ["Open the fill plug first."], "steps": [{"title": "Fill plug first, then drain", "blocks": [{"t": "text", "b": "Crack the fill plug, then remove the drain plug and drain."}], "only": ["fluid"], "caution": true}, {"title": "Refill", "blocks": [{"t": "text", "b": "Pump fluid in until it runs out of the fill hole, about 1.2 quarts."}, {"t": "torque", "label": "Diff plugs", "nm": 60, "c": {"level": "varies", "n": 2, "note": "Buildjournal: 44 ft-lb with O-ring, 48 ft-lb with washer; another Bentley list says 70 Nm."}, "alt": [65, 70]}], "only": ["fluid"]}, {"title": "Swap the diff", "blocks": [{"t": "text", "b": "Drain, disconnect the axles and driveshaft at the diff, support it, remove the two front and one rear mount bolts, and lower it."}, {"t": "note", "b": "Diffsonline tip: stand the new diff on its nose and pour the fluid in before fitting the cover, so it reaches the internals."}, {"t": "torque", "label": "Diff front mount bolts", "nm": 95, "c": {"level": "medium", "n": 2, "note": "Bentley via e46fanatics."}}, {"t": "torque", "label": "Diff rear mount bolt", "nm": 174, "c": {"level": "medium", "n": 2, "note": "Bentley via e46fanatics."}}, {"t": "torque", "label": "Driveshaft to diff (E12 Torx)", "nm": 83, "c": {"level": "medium", "n": 1, "note": "Bentley via e46fanatics: 61 ft-lb."}}], "only": ["rebuilt"], "timeSink": true}], "alsoReplace": [{"name": "Diff bushings", "why": "If it''s coming out anyway."}], "check": {"tab": "Read the fluid", "title": "Old fluid check", "illId": "e46-drive-hero", "illCap": "Diff plugs.", "rows": [{"see": "Fine grey paste", "means": "Normal.", "do": ""}, {"see": "Metal flakes", "means": "Bearing or gear wear.", "do": "Plan a rebuild."}, {"see": "Clunk persists after fluid", "means": "Diff free play.", "do": "Rebuilt unit."}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": ["Recheck for leaks."], "disagreements": [{"topic": "Fluid", "pos": "Diffsonline recommends Castrol SAF-XJ; Buildjournal used Red Line 75W-140.", "call": "SAF-XJ for the M Variable unit."}], "sources": ["BimmerWorld Diffsonline E46 M3 diff", "RacingDiffs E46 M3 LSD", "Buildjournal Inspection I DIY", "e46fanatics torque threads"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-guibo-csb', '{"id": "e46-guibo-csb", "title": "Guibo & centre support bearing", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "M3 guibo 26112226527 and CSB assembly 26122282495", "category": "Drivetrain", "kind": "repair", "heroId": "e46-drive-hero", "heroCap": "The guibo (rubber flex disc) joins the gearbox to the driveshaft; the centre support bearing holds the shaft in the middle.", "glance": {"timeFirst": "3–5 hr", "timeRepeat": "2–3 hr", "difficulty": 3, "cost": "$150–300", "risk": "Fitting the guibo backwards · not supporting the gearbox", "why": "A cracked guibo thunks on throttle and shifts; a worn CSB vibrates or whines. Both come off together.", "note": "The guibo is directional: the arrows point toward the flange arms."}, "lifespan": {"headline": ["~80,000–100,000 miles or on cracks"], "factors": ["Hard launches", "Heat"], "confidence": {"level": "community", "n": 1, "note": ""}}, "should": {"yesIf": ["Thunk on throttle or shifts", "Cracks around the guibo bolt holes", "Vibration at speed"], "codes": [], "notes": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "parts": [{"name": "Guibo (E46 M3)", "pn": "26112226527", "price": "$95–140", "tier": "oem", "note": "Meyle HD is a popular upgrade"}, {"name": "Centre support bearing assembly (M3)", "pn": "26122282495", "price": "$80–150", "tier": "oe"}, {"name": "Self-locking nuts ×6", "price": "$10", "tier": "oe"}, {"name": "Centering sleeve (optional)", "pn": "26117526611", "price": "$15", "tier": "oe"}], "aftermarket": [], "tools": [{"name": "18 mm low-profile wrenches"}, {"name": "Transmission support"}, {"name": "Torque wrench to 120 Nm"}], "before": ["Exhaust and heat shields off.", "Mark the driveshaft halves so they go back in the same position."], "steps": [{"title": "Support and disconnect", "blocks": [{"t": "text", "b": "Support the gearbox, remove the transmission brace, and undo the guibo nuts and the CSB bolts."}]}, {"title": "Separate the shaft", "blocks": [{"t": "text", "b": "Slide the driveshaft back and drop the front; split it at the slip joint, keeping your marks."}], "timeSink": true}, {"title": "Fit the new parts", "blocks": [{"t": "text", "b": "Fit the new CSB and guibo, arrows pointing toward the flanges. Grease the centering sleeve."}, {"t": "torque", "label": "Guibo bolts M12, grade 8.8", "nm": 81, "c": {"level": "medium", "n": 1, "note": "Bentley E46 manual: where BMW gives no unique torque, use the general value for the bolt grade marked on the head."}}, {"t": "torque", "label": "Guibo bolts M12, grade 10.9", "nm": 100, "c": {"level": "medium", "n": 1, "note": "Bentley E46 manual: where BMW gives no unique torque, use the general value for the bolt grade marked on the head."}}, {"t": "note", "b": "Torque from the metal-flange side while holding the rubber side."}], "caution": true}, {"title": "Refit", "blocks": [{"t": "text", "b": "Refit the CSB with the shaft straight, then the brace, heat shields and exhaust."}]}], "alsoReplace": [{"name": "Clutch or short shifter", "why": "Both need the driveshaft out."}], "check": {"tab": "Read the parts", "title": "Old part check", "illId": "e46-drive-hero", "illCap": "Guibo and CSB.", "rows": [{"see": "Cracks at the bolt holes", "means": "Guibo failing.", "do": "Replace."}, {"see": "CSB rubber torn", "means": "Bearing support failed.", "do": "Replace."}, {"see": "Both fine", "means": "Look at mounts.", "do": ""}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": [], "disagreements": [{"topic": "Guibo torque", "pos": "One DIY uses 75 ft-lb; Bentley''s general table depends on bolt grade.", "call": "Go by the grade on the bolt."}], "sources": ["ZHP Mafia E46 guibo/CSB DIY (part numbers)", "BimmerWorld E46 M3 guibo listing", "Bimmerforums flex disc DIY"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-short-shifter', '{"id": "e46-short-shifter", "title": "Short shifter & shifter rebuild (6MT)", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Manual cars only", "category": "Drivetrain", "kind": "upgrade", "heroId": "e46-drive-hero", "heroCap": "The shift lever sits in a carrier above the gearbox, with a selector rod running back from the gearbox.", "glance": {"timeFirst": "3–5 hr", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$150–450", "risk": "Breaking the carrier clips", "why": "Shorter throws and new bushings remove the vague, floppy feel of a high-mileage E46 shifter.", "note": "Access is from below with the exhaust and heat shield off; many owners do it with the guibo."}, "lifespan": {"headline": ["Bushings wear by ~80,000 miles"], "factors": ["Age"], "confidence": {"level": "community", "n": 1, "note": ""}}, "variants": {"question": "Which route?", "options": [{"id": "rebuild", "label": "Rebuild with OE bushings"}, {"id": "short", "label": "Short shifter", "when": "UUC, Turner and others", "brand": true}]}, "should": {"yesIf": ["Sloppy shifter", "Long throws", "Doing the guibo"], "codes": [], "notes": [], "confidence": {"level": "community", "n": 1, "note": ""}}, "parts": [{"name": "Shifter carrier bushings + selector rod bushing", "price": "$40–80", "tier": "oe"}, {"name": "Short shift kit", "price": "$150–400", "tier": "aftermarket", "only": ["short"]}], "aftermarket": [{"name": "UUC short shifter", "note": "Installed in MotoIQ''s Project E46 M3", "price": "$250+"}], "tools": [{"name": "Circlip pliers"}, {"name": "Trim tools"}], "before": ["Exhaust and heat shield off."], "steps": [{"title": "Remove from inside", "blocks": [{"t": "text", "b": "Pull the shift knob straight up and remove the boot and sound insulation."}]}, {"title": "Remove from below", "blocks": [{"t": "text", "b": "Disconnect the selector rod clip, release the carrier and lower the shifter out."}], "timeSink": true}, {"title": "Fit and test", "blocks": [{"t": "text", "b": "Fit new bushings and the shifter, reconnect, and check every gear before refitting the exhaust."}]}], "alsoReplace": [{"name": "Guibo", "why": "Same access."}], "check": {"tab": "Check it", "title": "After fitting", "illId": "e46-drive-hero", "illCap": "Shifter area.", "rows": [{"see": "Reverse hard to find", "means": "Linkage misaligned.", "do": "Recheck the selector rod."}, {"see": "Buzz", "means": "Bushing missing.", "do": "Check every bushing."}, {"see": "Crisp gates", "means": "Done.", "do": ""}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": [], "disagreements": [], "sources": ["MotoIQ Project E46 M3 parts 13–14"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-smg-conversion', '{"id": "e46-smg-conversion", "title": "SMG to manual conversion (SMG)", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "SMG and manual share the Getrag 420G gearbox", "category": "Drivetrain", "kind": "upgrade", "heroId": "e46-smg-hero", "heroCap": "The SMG pump, actuator and slave come off; a manual pedal box, clutch master/slave and shifter go in. The gearbox stays.", "glance": {"timeFirst": "2–4 days", "timeRepeat": "—", "difficulty": 5, "cost": "$1,500–4,600", "risk": "DME coding · missing parts", "why": "SMG and manual cars use the same Getrag gearbox, so converting is far cheaper than on later M cars. It ends SMG pump worries for good.", "note": "Keep the SMG parts: the conversion is reversible."}, "lifespan": {"headline": ["One-time conversion"], "factors": [], "confidence": {"level": "medium", "n": 2, "note": ""}}, "variants": {"question": "Which route?", "options": [{"id": "diy", "label": "DIY with used parts", "when": "M3Forum MP675 write-up"}, {"id": "kit", "label": "Professional kit", "when": "Everything M3s (UK), from about £3,500 fitted", "brand": true}]}, "should": {"yesIf": ["SMG pump failed again", "You want a pedal"], "codes": [], "notes": [], "confidence": {"level": "medium", "n": 2, "note": ""}}, "parts": [{"name": "Manual pedal box with clutch pedal", "price": "$200–400 used", "tier": "oe", "only": ["diy"]}, {"name": "Clutch master and slave, lines", "price": "$150", "tier": "oe", "only": ["diy"]}, {"name": "Hack Engineering SMG-to-manual braided clutch line", "price": "$60", "tier": "aftermarket", "only": ["diy"]}, {"name": "Shifter, carrier, selector linkage", "price": "$200", "tier": "oe", "only": ["diy"]}, {"name": "Clutch and flywheel (SMG clutch differs)", "price": "$500+", "tier": "oem", "only": ["diy"]}, {"name": "Everything M3s conversion", "price": "£3,500+ fitted", "tier": "aftermarket", "only": ["kit"]}], "aftermarket": [], "tools": [{"name": "Coding software for the DME and cluster"}, {"name": "Transmission jack"}], "before": ["Read the full write-up and source every part first."], "steps": [{"title": "Remove the SMG system", "blocks": [{"t": "text", "b": "Remove the SMG pump, lines, actuator, gear position sensor and slave cylinder."}], "only": ["diy"], "timeSink": true}, {"title": "Fit the manual parts", "blocks": [{"t": "text", "b": "Fit the pedal box, clutch master, slave, clutch line and shifter linkage. Hack Engineering notes SMG boxes lack only a selector centring spring."}], "only": ["diy"]}, {"title": "Bleed and code", "blocks": [{"t": "text", "b": "Bleed the clutch hydraulics, then code the DME to run without SMG gear data. Hack''s car kept SMG clocks with the gear display disabled."}], "only": ["diy"], "caution": true}, {"title": "Book the conversion", "blocks": [{"t": "text", "b": "Everything M3s fits a kit of 180 genuine BMW parts, reversible, with a waiting list."}], "only": ["kit"]}], "alsoReplace": [{"name": "Clutch and flywheel", "why": "The gearbox is coming out anyway."}], "check": {"tab": "Check it", "title": "After conversion", "illId": "e46-smg-hero", "illCap": "Parts swapped.", "rows": [{"see": "Check engine light, no gear data", "means": "DME not coded.", "do": "Code it."}, {"see": "Soft pedal", "means": "Air.", "do": "Bleed."}, {"see": "Clean shifts", "means": "Done.", "do": ""}], "c": {"level": "medium", "n": 2, "note": ""}}, "aftercare": [], "disagreements": [], "sources": ["Hack Engineering KED SMG-to-manual journal", "The Drive: Everything M3s CSL conversion", "Jalopnik: M3Forum MP675 conversion tutorial"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-smg-fluid', '{"id": "e46-smg-fluid", "title": "SMG fluid change & bleed (SMG)", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "SMG II cars", "category": "Drivetrain", "kind": "repair", "heroId": "e46-smg-hero", "heroCap": "The SMG reservoir is in the engine bay; there''s no drain, so the fluid is exchanged at the reservoir and bled with software.", "glance": {"timeFirst": "1–2 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$30–60", "risk": "Mixing fluids · air in the pump", "why": "Fresh fluid helps the pump reach pressure, especially when hot. Burkhart''s fluid claims faster pressure build, but can''t be mixed with Pentosin.", "note": "Never use transmission or brake fluid in the SMG reservoir."}, "lifespan": {"headline": ["No BMW interval; owners exchange it every few years"], "factors": ["Heat"], "confidence": {"level": "community", "n": 2, "note": ""}}, "variants": {"question": "Which fluid?", "options": [{"id": "pent", "label": "Pentosin CHF 11S", "when": "Factory fluid"}, {"id": "burk", "label": "Burkhart HP fluid", "when": "Needs ≤5% old fluid left: several exchanges plus a full bleed", "brand": true}]}, "should": {"yesIf": ["Dark fluid", "Pump-duty codes when hot"], "codes": ["56"], "notes": [], "confidence": {"level": "community", "n": 2, "note": ""}}, "parts": [{"name": "Pentosin CHF 11S", "price": "1 L", "tier": "oe", "only": ["pent"]}, {"name": "Burkhart HP SMG fluid", "price": "£42/L", "tier": "aftermarket", "only": ["burk"]}], "aftermarket": [], "tools": [{"name": "Clean syringe or turkey baster (SMG only)"}, {"name": "INPA / GT1 / ISTA"}, {"name": "Battery charger"}], "before": ["Engine cold. Clean around the reservoir cap before opening."], "steps": [{"title": "Exchange the reservoir", "blocks": [{"t": "text", "b": "Remove the cap and draw out the fluid with a clean syringe. Refill with new fluid to the mark."}]}, {"title": "Cycle and bleed", "blocks": [{"t": "text", "b": "Run the bleed routines in INPA or GT1 (actuator, then clutch), topping up between runs. Repeat the exchange several times to replace most of the fluid."}, {"t": "note", "b": "BMW''s clutch-only bleed uses a reservoir pressure adaptor and holding the slave piston; that''s a dealer-tool procedure."}], "caution": true}, {"title": "Adapt", "blocks": [{"t": "text", "b": "Run the complete adaptation with the battery on a charger."}]}], "alsoReplace": [], "check": {"tab": "Check it", "title": "After the change", "illId": "e46-smg-hero", "illCap": "Reservoir and pump.", "rows": [{"see": "Smooth shifts", "means": "Done.", "do": ""}, {"see": "Gear warning", "means": "Air.", "do": "Bleed again."}, {"see": "Level dropping", "means": "Leak.", "do": "Find it before driving."}], "c": {"level": "community", "n": 2, "note": ""}}, "aftercare": ["Recheck level after a drive."], "disagreements": [{"topic": "Should you change it at all?", "pos": "Some shops advise leaving SMG fluid alone; others exchange it regularly.", "call": "Exchange it if dark, with software on hand to bleed."}], "sources": ["Hack Engineering Burkhart SMG fluid listing", "e46fanatics SMG fluid threads", "m3cutters SMG fluid threads", "Holland Motorsport SMG clutch bleed procedure"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-smg-pump', '{"id": "e46-smg-pump", "title": "SMG hydraulic pump & motor (SMG)", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "SMG II cars including CSL", "category": "Drivetrain", "kind": "repair", "heroId": "e46-smg-hero", "heroCap": "The SMG hydraulic unit (pump, motor, accumulator) sits in the engine bay and drives the clutch and gear actuator.", "glance": {"timeFirst": "3–5 hr", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$630–3,100", "risk": "Running the pump dry · skipping the bleed and adaptation", "why": "BimmerWorld says the pump usually lasts around 100k miles, sometimes much less, and a failed pump strands the car. A worn motor is the usual cause, and Burkhart sells a plug-in replacement.", "note": "You''ll need INPA, GT1/DIS or ISTA afterwards to bleed and re-adapt."}, "lifespan": {"headline": ["~100,000 miles"], "factors": ["Heat", "Old fluid"], "confidence": {"level": "medium", "n": 1, "note": "BimmerWorld."}}, "variants": {"question": "Which fix?", "options": [{"id": "motor", "label": "Burkhart replacement motor", "when": "Keeps your pump block", "brand": true}, {"id": "rebuilt", "label": "Rebuilt pump + accumulator", "when": "MLR via BimmerWorld", "brand": true}, {"id": "reloc", "label": "Burkhart relocation kit", "when": "Moves the unit away from engine heat", "brand": true}]}, "should": {"yesIf": ["Drops out of gear or won''t engage", "Gear cog warning", "Codes 53, 55, 56 or 57"], "codes": ["53", "55", "56", "57"], "notes": ["Try a new SMG relay and fuse first: they come with the rebuilt pump for a reason."], "confidence": {"level": "medium", "n": 2, "note": "Burkhart, BimmerWorld."}}, "parts": [{"name": "Burkhart motor repair kit (with HP fluid)", "pn": "54160", "price": "$629", "tier": "aftermarket", "only": ["motor"]}, {"name": "Rebuilt pump + accumulator (MLR)", "pn": "21532229715", "price": "$3,067", "tier": "aftermarket", "only": ["rebuilt"]}, {"name": "Burkhart relocation kit", "pn": "BE-SMG2-RK", "price": "$649", "tier": "aftermarket", "note": "Not for cars with the ABS unit in the passenger-side bin", "only": ["reloc"]}, {"name": "SMG relay + 40 A fuse", "price": "$40", "tier": "oe"}, {"name": "SMG fluid", "price": "1 L", "tier": "oe"}], "aftermarket": [], "tools": [{"name": "INPA, GT1/DIS or ISTA with a cable"}, {"name": "Battery charger", "note": "The bleed and adaptation runs take ~30 minutes"}, {"name": "Pin tool (Burkhart, optional)", "only": ["motor"]}], "before": ["Car cold and level.", "Battery on a charger throughout."], "steps": [{"title": "Depressurise and disconnect", "blocks": [{"t": "text", "b": "Remove the SMG relay so the pump can''t run, then unplug the motor and disconnect the lines as your kit describes. Expect fluid."}], "caution": true}, {"title": "Fit the motor, pump or relocation kit", "blocks": [{"t": "text", "b": "Follow the kit''s instructions. Owners fill the pump ports with fluid before reconnecting the lines so it isn''t started dry."}]}, {"title": "Bleed and adapt", "blocks": [{"t": "text", "b": "Fill the reservoir. In INPA: F9 special tests, ''SMG adaptation'', then F1/F8 bleed the actuator, F2/F8 bleed the clutch, F3/F8 run the complete adaptation. Top up between runs."}, {"t": "note", "b": "One owner ran the bleed twice and topped up after each; another stressed doing it cold and level."}], "caution": true, "timeSink": true}], "alsoReplace": [{"name": "SMG relay", "why": "Cheap and a common failure."}], "check": {"tab": "Check it", "title": "After the bleed", "illId": "e46-smg-hero", "illCap": "SMG hydraulic unit.", "rows": [{"see": "Pump cycles briefly and stops", "means": "Healthy.", "do": ""}, {"see": "Pump runs long or often", "means": "Leak or accumulator.", "do": "Check lines and accumulator."}, {"see": "Codes return", "means": "Air or adaptation incomplete.", "do": "Bleed and adapt again."}], "c": {"level": "community", "n": 2, "note": ""}}, "aftercare": ["Re-run the adaptation every 6–12 months, owners suggest."], "disagreements": [{"topic": "Motor or whole pump", "pos": "Burkhart sells the motor alone; BimmerWorld''s rebuilt unit adds a new accumulator.", "call": "Motor kit if the accumulator is healthy."}], "sources": ["Burkhart Engineering SMG2 motor and relocation kits (IND)", "BimmerWorld rebuilt SMG pump", "m3cutters SMG pump bleed thread", "e46fanatics SMG bleed thread"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-trans-fluid', '{"id": "e46-trans-fluid", "title": "Transmission fluid (Getrag 420G)", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Manual and SMG cars use the same Getrag 420G gearbox", "category": "Drivetrain", "kind": "repair", "heroId": "e46-drive-hero", "heroCap": "Drain plug at the bottom of the gearbox, fill plug on the side. Always open the fill plug first.", "glance": {"timeFirst": "45–60 min", "timeRepeat": "30 min", "difficulty": 1, "cost": "$40–90", "risk": "Draining before you know the fill plug will open", "why": "Fresh fluid makes cold shifts smoother and protects the synchros. BMW calls it lifetime fluid, but specialists change it.", "note": "Capacity is about 1.8 litres: fill until it runs out of the fill hole."}, "lifespan": {"headline": ["Every 50,000–60,000 miles, or after track use"], "factors": ["Track days", "Notchy cold shifts"], "confidence": {"level": "community", "n": 2, "note": ""}}, "variants": {"question": "Which fluid?", "options": [{"id": "bmw", "label": "BMW MTF-LT-2", "when": "Factory spec, 75W-80 GL-4"}, {"id": "redline", "label": "Red Line", "when": "MTL, MT-90 or D4 ATF; popular, but not the BMW spec"}]}, "should": {"yesIf": ["No record of a change", "Notchy shifts when cold", "Doing the clutch"], "codes": [], "notes": [], "confidence": {"level": "medium", "n": 2, "note": ""}}, "parts": [{"name": "BMW MTF-LT-2", "pn": "83220309031", "price": "~1.8 L", "tier": "oe", "only": ["bmw"]}, {"name": "Red Line MTL / MT-90 / D4 ATF", "price": "~2 qt", "tier": "aftermarket", "only": ["redline"]}, {"name": "Plug crush washers (if fitted)", "price": "$4", "tier": "oe"}], "aftermarket": [], "tools": [{"name": "17 mm socket or hex (per your plugs)"}, {"name": "Fluid pump"}, {"name": "Torque wrench"}], "before": ["Car level on four stands: a tilted car under-fills."], "steps": [{"title": "Open the fill plug first", "blocks": [{"t": "text", "b": "Crack the fill plug on the side of the gearbox. If it won''t move, stop: don''t drain a gearbox you can''t refill."}], "caution": true}, {"title": "Drain", "blocks": [{"t": "text", "b": "Remove the drain plug and let it drain fully. Clean the magnet."}, {"t": "torque", "label": "Drain plug", "nm": 50, "c": {"level": "medium", "n": 1, "note": "Buildjournal E46 M3 Inspection I DIY."}, "note": "37 ft-lb"}]}, {"title": "Fill", "blocks": [{"t": "text", "b": "Pump fluid in until it runs out of the fill hole, about 1.8 L."}, {"t": "torque", "label": "Fill plug", "nm": 50, "c": {"level": "medium", "n": 1, "note": "Buildjournal E46 M3 Inspection I DIY."}, "note": "37 ft-lb"}]}], "alsoReplace": [{"name": "Diff fluid", "why": "Same tools, same afternoon."}], "check": {"tab": "Read the fluid", "title": "What the old fluid tells you", "illId": "e46-drive-hero", "illCap": "Gearbox plugs.", "rows": [{"see": "Clean, light paste on the magnet", "means": "Normal.", "do": ""}, {"see": "Chunks on the magnet", "means": "Internal wear.", "do": "Inspect before driving hard."}, {"see": "Burnt smell", "means": "Overheated.", "do": "Shorter intervals."}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": ["Shifts may feel stiff for a few miles."], "disagreements": [{"topic": "Red Line vs MTF-LT-2", "pos": "NAM3 owners note BMW specifies 75W-80 GL-4 and Red Line MT-90 is a different spec; many run it happily.", "call": "MTF-LT-2 unless you have a reason to change."}], "sources": ["Buildjournal E46 M3 Inspection I DIY", "FCP Euro E46 M3 fluids", "NAM3Forum transmission fluid thread"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-battery', '{"id": "e46-battery", "title": "Battery (trunk)", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "E46 coupe and convertible", "category": "Electrical", "kind": "repair", "heroId": "e46-elec-hero", "heroCap": "The battery lives under the trunk floor, with a vent tube to the outside.", "glance": {"timeFirst": "30 min", "timeRepeat": "20 min", "difficulty": 1, "cost": "$180–450", "risk": "Forgetting the vent tube · wrong group size", "why": "Weak batteries cause odd electrical faults and slow starts, and SMG cars are especially sensitive to low voltage.", "note": "Match the size and capacity printed on your old battery; E46 owners commonly fit group 49 (H8) or 94R (H7) AGM batteries."}, "lifespan": {"headline": ["5–7 years"], "factors": ["Short trips", "Storage without a tender"], "confidence": {"level": "community", "n": 2, "note": ""}}, "variants": {"question": "Which battery?", "options": [{"id": "agm", "label": "AGM, same size as original"}, {"id": "li", "label": "Lightweight lithium (track)", "when": "Antigravity and others; check charging compatibility", "brand": true}]}, "should": {"yesIf": ["Slow cranking", "Battery over 5 years old", "SMG faults on low voltage"], "codes": [], "notes": ["Test it first: many ''bad'' batteries are just discharged."], "confidence": {"level": "community", "n": 1, "note": ""}}, "parts": [{"name": "AGM battery (match your original''s size)", "price": "$180–300", "tier": "aftermarket", "only": ["agm"]}, {"name": "Lithium battery", "price": "$400–700", "tier": "aftermarket", "only": ["li"]}], "aftermarket": [{"name": "Odyssey / Bosch S6 AGM", "note": "Group 49 (H8) options listed for BMWs of this era", "price": "$250–350"}], "tools": [{"name": "10 mm and 13 mm sockets"}, {"name": "Memory saver (optional)"}], "before": ["Have the radio code if your car has one.", "Ignition off, key out."], "steps": [{"title": "Open up", "blocks": [{"t": "text", "b": "Lift the trunk floor and remove the battery cover."}]}, {"title": "Disconnect", "blocks": [{"t": "text", "b": "Negative terminal first, then positive. Remove the vent tube from the battery and the hold-down."}]}, {"title": "Fit the new battery", "blocks": [{"t": "text", "b": "Fit the hold-down, reconnect the vent tube to the new battery''s vent port, then positive first and negative last."}, {"t": "warn", "b": "A missing vent tube lets gas into the trunk."}], "caution": true}, {"title": "Reset", "blocks": [{"t": "text", "b": "Reset one-touch windows by running each window fully up and holding the switch a moment. Owners with later BMWs register batteries with software; the E46 doesn''t require it."}]}], "alsoReplace": [], "check": {"tab": "Check it", "title": "After fitting", "illId": "e46-elec-hero", "illCap": "Battery location.", "rows": [{"see": "12.6 V+ engine off", "means": "Charged.", "do": ""}, {"see": "13.8–14.4 V running", "means": "Alternator OK.", "do": ""}, {"see": "Under 13 V running", "means": "Charging fault.", "do": "Test the alternator."}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": ["Use a tender if the car sits."], "disagreements": [], "sources": ["FCP Euro BMW battery listings", "M3Post battery DIY threads", "1addicts battery DIY"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-headlight-bulbs', '{"id": "e46-headlight-bulbs", "title": "Headlight bulbs (halogen or xenon)", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "E46 headlights came halogen (H7) or xenon (D2S); xenon igniters changed from 03/2003", "category": "Electrical", "kind": "repair", "heroId": "e46-elec-hero", "heroCap": "Bulbs are reached from behind the headlight under the hood.", "glance": {"timeFirst": "30–60 min", "timeRepeat": "20 min", "difficulty": 1, "cost": "$20–200", "risk": "Touching bulb glass · high voltage on xenon", "why": "Old xenon bulbs dim and colour-shift; a failing igniter or ballast causes flicker. Halogen bulbs are a quick swap.", "note": "Disconnect the battery before touching xenon components."}, "lifespan": {"headline": ["Halogen ~2 years · D2S ~5–8 years"], "factors": ["Hours on"], "confidence": {"level": "community", "n": 1, "note": ""}}, "variants": {"question": "Which headlights?", "options": [{"id": "hal", "label": "Halogen (H7)"}, {"id": "xen", "label": "Xenon (D2S)"}]}, "should": {"yesIf": ["Bulb out", "Xenon pink/purple or flickering"], "codes": [], "notes": ["Flicker after a new D2S bulb points to the igniter or ballast."], "confidence": {"level": "community", "n": 1, "note": ""}}, "parts": [{"name": "H7 halogen bulbs", "price": "$20–40", "tier": "oem", "only": ["hal"]}, {"name": "D2S xenon bulb (Osram OEM)", "pn": "63217160806", "price": "$90", "tier": "oem", "only": ["xen"]}, {"name": "Xenon igniter (from 03/2003)", "pn": "63126919886", "price": "$100", "tier": "aftermarket", "only": ["xen"]}], "aftermarket": [], "tools": [{"name": "Gloves"}, {"name": "Screwdriver for the access cover"}], "before": ["Lights off; disconnect the battery for xenon work."], "steps": [{"title": "Open the cover", "blocks": [{"t": "text", "b": "Remove the access cover on the back of the headlight."}]}, {"title": "Swap the bulb", "blocks": [{"t": "text", "b": "Release the clip or igniter, swap the bulb without touching the glass, refit."}, {"t": "warn", "b": "Xenon igniters run at very high voltage. Battery off first.", "only": ["xen"]}], "caution": true}, {"title": "Test and aim", "blocks": [{"t": "text", "b": "Check both beams and have the aim checked if you changed housings."}]}], "alsoReplace": [{"name": "Both bulbs", "why": "Xenon bulbs colour-match better in pairs."}], "check": {"tab": "Check it", "title": "After the swap", "illId": "e46-elec-hero", "illCap": "Headlight access.", "rows": [{"see": "Even colour both sides", "means": "Done.", "do": ""}, {"see": "Flicker", "means": "Igniter/ballast.", "do": "Swap sides to diagnose."}, {"see": "Bulb out warning", "means": "Connection.", "do": "Reseat."}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": [], "disagreements": [], "sources": ["Turner Motorsport E46 bulb listings", "Retrofitlab E46 headlight guide"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-window-regulator', '{"id": "e46-window-regulator", "title": "Window regulator & motor", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Coupe and convertible frameless doors", "category": "Electrical", "kind": "repair", "heroId": "e46-door-hero", "heroCap": "The regulator bolts inside the door behind the panel; the motor bolts to it.", "glance": {"timeFirst": "2–3 hr", "timeRepeat": "1.5 hr", "difficulty": 2, "cost": "$60–200", "risk": "Dropping the glass · breaking door panel clips", "why": "A crunching or dropped window usually means a broken regulator cable or clip. The motor is often reusable.", "note": "Afterwards, re-teach one-touch and the frameless drop by running the window fully up and holding the switch."}, "lifespan": {"headline": ["Fails on condition"], "factors": ["Ice", "Age"], "confidence": {"level": "community", "n": 1, "note": ""}}, "should": {"yesIf": ["Window drops or grinds", "Motor runs but the glass doesn''t move"], "codes": [], "notes": [], "confidence": {"level": "community", "n": 1, "note": ""}}, "parts": [{"name": "Front window regulator (side-specific)", "pn": "51338229106 (right)", "price": "$60–150", "tier": "oem", "note": "URO, Genuine BMW"}, {"name": "Door panel clips", "price": "$10", "tier": "oe"}], "aftermarket": [], "tools": [{"name": "T20 Torx", "note": "Motor screws"}, {"name": "10 mm socket"}, {"name": "Trim tools"}, {"name": "Tape to hold the glass"}], "before": ["Disconnect the battery (side airbag in the door)."], "steps": [{"title": "Remove the door panel", "blocks": [{"t": "text", "b": "See the door panel guide."}]}, {"title": "Free the glass", "blocks": [{"t": "text", "b": "Lower the glass to the clips, release the two sliding tabs, and tape the glass up."}]}, {"title": "Swap the regulator", "blocks": [{"t": "text", "b": "Unbolt and remove the regulator. Move the motor across (three T20 screws), fitting the new gear bushings if supplied."}]}, {"title": "Refit", "blocks": [{"t": "text", "b": "Bolt in, reconnect the glass to the clips, test before refitting the panel."}]}], "alsoReplace": [], "check": {"tab": "Check it", "title": "After fitting", "illId": "e46-door-hero", "illCap": "Regulator inside the door.", "rows": [{"see": "Glass tilts", "means": "One clip not engaged.", "do": "Re-seat."}, {"see": "No auto-drop on opening", "means": "Not taught.", "do": "Hold the switch up a few seconds."}, {"see": "Smooth travel", "means": "Done.", "do": ""}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": [], "disagreements": [], "sources": ["FCP Euro BMW window regulator DIY", "ECS Tuning E46 M3 regulator listing"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-air-filter', '{"id": "e46-air-filter", "title": "Engine air filter", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Stock airbox only. CSL-style carbon airboxes use their own filter.", "category": "Engine", "kind": "repair", "heroId": "e46-af-hero", "heroCap": "The filter sits in the airbox, upstream of the air mass sensor and the intake plenum.", "glance": {"timeFirst": "15–20 min", "timeRepeat": "10 min", "difficulty": 1, "cost": "$25–45", "risk": "Dirt falling into the clean side · a mis-seated element", "why": "The S54 breathes a lot of air at 8,000 rpm. A clean filter is free performance, and a ten-minute job.", "note": "If you''re thinking about a CSL-style airbox, see the airbox upgrade guide instead."}, "lifespan": {"headline": ["Every 30,000 miles, sooner on dusty roads"], "factors": ["Dirt roads", "Track days"], "inspect": ["Look at it at every oil change"], "confidence": {"level": "medium", "n": 1, "note": "Common service practice."}}, "should": {"yesIf": ["It''s grey or clogged", "30k miles since the last one"], "codes": [], "notes": [], "confidence": {"level": "medium", "n": 1, "note": "Service practice."}}, "parts": [{"name": "Air filter element (Mann/Mahle OE)", "price": "$25–45", "tier": "oem", "note": "Check fitment for the E46 M3 when ordering"}], "aftermarket": [{"name": "BMC or K&N drop-in", "note": "Reusable; oiled filters can foul the air mass sensor if over-oiled", "price": "$60–90"}], "tools": [{"name": "Screwdriver or Torx bit for the airbox"}, {"name": "Vacuum or clean rag"}], "before": ["Engine off and cool."], "steps": [{"title": "Open the airbox", "blocks": [{"t": "text", "b": "Release the airbox lid fasteners and lift the lid enough to reach the element."}]}, {"title": "Swap the element", "blocks": [{"t": "text", "b": "Lift the old filter out without shaking dirt into the clean side. Wipe or vacuum the dirty side of the box, then seat the new element evenly all round."}, {"t": "warn", "b": "A filter that isn''t seated lets unfiltered air straight into the engine."}]}, {"title": "Close it up", "blocks": [{"t": "text", "b": "Refit the lid and check every clip or screw is home."}]}], "alsoReplace": [], "check": {"tab": "Read the filter", "title": "What the old filter tells you", "illId": "e46-af-hero", "illCap": "Airbox upstream of the air mass sensor.", "rows": [{"see": "Light grey", "means": "Fine for a while longer.", "do": "Refit it if you like."}, {"see": "Dark and packed", "means": "Restricting air.", "do": "Replace it."}, {"see": "Dirt on the clean side", "means": "It wasn''t sealing.", "do": "Clean the box and check the seating."}], "c": {"level": "community", "n": 1, "note": "Standard practice."}}, "aftercare": [], "disagreements": [{"topic": "Oiled reusable filters", "pos": "They flow well, but over-oiling can coat the air mass sensor.", "call": "Paper on a stock car; follow the oiling instructions exactly if you go reusable."}], "sources": ["E46 M3 owner service practice", "Evolve and Eventuri airbox listings (for the upgrade path)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-airbox', '{"id": "e46-airbox", "title": "CSL-style airbox", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "S54 Z4 M versions exist from Evolve; CSL plenum fitment on SMG cars needs a reservoir bracket", "category": "Engine", "kind": "upgrade", "heroId": "e46-ab-hero", "heroCap": "Stock: a plastic plenum over the six throttle bodies, fed through an air-mass meter. CSL-style: a carbon plenum with a bigger intake mouth and no air-mass meter, so the ECU needs a tune that doesn''t rely on one (Alpha-N).", "glance": {"timeFirst": "3–5 hr + tune", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$1,300–4,200 incl. tune", "risk": "Running a MAF-less box without the right tune · breaking the small vent hose under the plenum", "why": "The CSL airbox is the single most-loved S54 mod: a deep intake roar under load and real power when it''s tuned properly. The sound is quiet at idle and part throttle, then arrives above about 2,500 rpm.", "note": "Most of the gain comes from the tune, not the box. A box without a proper Alpha-N tune (or a box built to keep the MAF) won''t deliver the numbers you''ve seen."}, "lifespan": {"headline": ["Permanent upgrade"], "factors": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "variants": {"questions": [{"question": "Which box?", "options": [{"id": "eventuri", "label": "Eventuri Hybrid", "when": "Keeps the MAF: no tune required", "brand": true}, {"id": "turner", "label": "Turner CSL-style", "when": "Uses CSL filter and boots; MAF delete, needs Alpha-N", "brand": true}, {"id": "karb", "label": "Karbonius / Evolve / other carbon CSL", "when": "MAF delete; Evolve ships its own Alpha-N file", "brand": true}, {"id": "csl", "label": "Genuine BMW CSL airbox", "when": "Rare and expensive; needs CSL-style tuning"}]}, {"question": "Transmission?", "options": [{"id": "mt", "label": "6-speed manual"}, {"id": "smg", "label": "SMG", "when": "The SMG reservoir has to move: Turner sells a bracket"}]}]}, "should": {"yesIf": ["You love the CSL sound", "You''re planning headers and a tune anyway", "Track car chasing every whp"], "codes": [], "notes": ["Removing or replacing catalytic converters on a road car is illegal in the US and most other markets, and an Alpha-N or catless tune generally won''t pass emissions readiness checks. These routes are for track cars."], "confidence": {"level": "medium", "n": 2, "note": ""}}, "parts": [{"name": "Eventuri Hybrid Carbon Airbox System", "price": "$2,000–3,000", "tier": "aftermarket", "only": ["eventuri"]}, {"name": "Turner CSL-style intake", "price": "~$1,500", "tier": "aftermarket", "note": "Uses the factory CSL filter and CSL intake boots", "only": ["turner"]}, {"name": "Karbonius / Evolve carbon airbox", "price": "$2,200–4,200", "tier": "aftermarket", "note": "Evolve''s package includes the Alpha-N file, IAT relocation and CSL dipstick", "only": ["karb"]}, {"name": "Genuine BMW CSL airbox", "price": "$4,000+", "tier": "oe", "only": ["csl"]}, {"name": "Alpha-N tune (custom dyno or off-the-shelf)", "price": "$600–1,200", "tier": "aftermarket", "only": ["turner", "karb", "csl"]}, {"name": "IAT relocation kit + CSL IAT sensor", "price": "$120–150", "tier": "aftermarket", "note": "Turner plug-and-play kit", "only": ["turner", "karb", "csl"]}, {"name": "CSL dipstick", "price": "$40", "tier": "oe", "only": ["turner", "karb", "csl"]}, {"name": "Throttle body boot clamps ×6 (or silicone boot set)", "price": "$20–110", "tier": "oe", "note": "Single-use clamps"}, {"name": "Turner CSL SMG expansion tank bracket", "price": "$60", "tier": "aftermarket", "only": ["smg"]}], "aftermarket": [{"name": "Epic Motorsports Alpha-N", "note": "Custom dyno tune on the stock MSS54; one hour of dyno included", "price": "$1,199"}, {"name": "Evolve Alpha-N via Evolve-R cable", "note": "Flashed at home; ships with the Evolve box", "price": "incl."}, {"name": "HTE / other S54 tuners", "note": "Owners report 335 whp with a Turner box and HTE Alpha-N", "price": "varies"}], "tools": [{"name": "Clamp pliers for the throttle-body clamps"}, {"name": "10 mm socket, Torx set"}, {"name": "Flash cable for your tuner (Alpha-N routes)", "only": ["turner", "karb", "csl"]}], "before": ["Book the tune before you fit a MAF-less box: the car shouldn''t be driven hard until it''s mapped.", "Remove the strut brace (4 nuts) and the cabin filter housing (4 Torx)."], "chapters": [{"id": "gain", "title": "What you get"}, {"id": "out", "title": "Stock airbox out"}, {"id": "in", "title": "CSL box in"}, {"id": "tune", "title": "Tune & finish"}], "steps": [{"title": "What you get", "blocks": [{"t": "chart", "title": "Same car, same dyno: intake vs stock", "unit": "whp", "baseline": "Stock", "bars": [{"label": "Stock", "v": 286, "note": "91 octane"}, {"label": "Catless headers + tune", "v": 315}, {"label": "+ Eventuri intake", "v": 321}, {"label": "+ Turner CSL box, Alpha-N", "v": 341, "note": "with supporting mods"}], "source": "Buildjournal: same 2003 E46 M3, same dyno (European Auto Source, Anaheim), 91 octane, wheel hp.", "c": {"level": "high", "n": 1, "note": "One car, back-to-back on one dyno: the best kind of comparison, but still one car."}}, {"t": "chart", "title": "Turner box on a Stage 2 car", "unit": "whp", "baseline": "Before (Stage 2)", "bars": [{"label": "Before (Stage 2)", "v": 312, "note": "220k-mile E46 M3"}, {"label": "Turner CSL box + retune", "v": 334, "note": "+12 wtq"}], "source": "22RPD shop dyno.", "c": {"level": "medium", "n": 1, "note": "Shop test on one customer car."}}, {"t": "chart", "title": "Maker claims, airbox alone", "unit": "hp gain", "baseline": null, "bars": [{"label": "Eventuri Hybrid (no tune)", "v": 22, "note": "claimed 20–22 hp"}, {"label": "Evolve + Alpha-N", "v": 30, "note": "claimed ''up to 30 bhp''"}], "source": "Manufacturer figures; test conditions not published the same way.", "c": {"level": "single", "n": 2, "note": "Maker claims."}}, {"t": "note", "b": "Read these together: Buildjournal''s +54 whp is versus a completely stock car with headers and a tune already on. The box itself is worth roughly 15–25 whp on a tuned car, and one tuner found only ~2 whp from the box with most of the gain coming from Alpha-N VANOS tuning."}], "chapter": "gain"}, {"title": "Remove the elbow and stock airbox", "blocks": [{"t": "text", "b": "Loosen the clamps at the air-mass meter housing and the intake elbow, release the airbox clips and lift the airbox and elbow out. Remove the crankcase vent hose and the dipstick nut."}, {"t": "ill", "id": "e46-ab-plenum", "cap": "Plenum removal: six throttle-body clamps on top, two 10 mm nuts and two vent hoses underneath."}], "chapter": "out"}, {"title": "Remove the plenum", "blocks": [{"t": "text", "b": "Remove all six throttle-body clamps and the two 10 mm nuts under the plenum, unclip the large vent hose, then pull the plenum halfway out and reach under to unclip the small vent hose."}, {"t": "warn", "b": "The small vent hose underneath is the part everyone breaks. Don''t lift the plenum until it''s unclipped."}], "chapter": "out", "caution": true}, {"title": "Prepare the new box", "blocks": [{"t": "text", "b": "Fit the filter and transfer any sensors. MAF-delete boxes need the intake air temperature sensor relocated into the box with the IAT kit."}, {"t": "ill", "id": "e46-ab-iat", "cap": "MAF-delete boxes: the air-mass meter goes, the IAT sensor moves into the box, and the ECU runs Alpha-N (throttle angle + rpm)."}, {"t": "note", "b": "Eventuri''s Hybrid box keeps the air-mass meter in the path, which is why it needs no tune.", "only": ["eventuri"]}], "chapter": "in"}, {"title": "Fit the box", "blocks": [{"t": "text", "b": "Set the box on the throttle bodies with new boots or clamps, line up the two mounts underneath, and refit the vent hoses and dipstick."}, {"t": "note", "b": "SMG cars: fit the Turner bracket to relocate the SMG expansion tank before the box goes in.", "only": ["smg"]}], "chapter": "in"}, {"title": "Flash the Alpha-N file", "blocks": [{"t": "text", "b": "Flash the file from your tuner. Custom tunes are then refined on a dyno; Epic''s Alpha-N includes an hour of dyno time."}, {"t": "warn", "b": "Don''t drive hard on a MAF-less box with a stock file."}], "chapter": "tune", "only": ["turner", "karb", "csl"], "caution": true}, {"title": "Check and drive", "blocks": [{"t": "text", "b": "Clear codes, idle to temperature, check for vacuum leaks around the boots. With Eventuri, no flash is needed."}], "chapter": "tune"}], "alsoReplace": [{"name": "Throttle body boots", "why": "Cracked boots cause vacuum leaks and will be exposed anyway."}, {"name": "Throttle actuator pull rod", "why": "It''s right there with the plenum off; see the throttle actuator guide."}, {"name": "Idle control valve cleaning", "why": "Easy with the plenum out."}], "check": {"tab": "Check the result", "title": "After the swap", "illId": "e46-ab-hero", "illCap": "Stock vs CSL-style intake path.", "rows": [{"see": "Smooth idle, no lean codes", "means": "Sealed and mapped.", "do": "Enjoy it."}, {"see": "Hunting idle or lean codes", "means": "Vacuum leak or tune mismatch.", "do": "Smoke-test the boots; check the file is for your box."}, {"see": "Fails emissions readiness", "means": "Expected with Alpha-N.", "do": "Flash back to stock and refit the stock box for testing."}], "c": {"level": "medium", "n": 3, "note": "Owner and tuner reports."}}, "aftercare": ["Re-check boot clamps after the first heat cycles.", "Log a few pulls or return for a dyno refinement if your tuner offers one."], "disagreements": [{"topic": "How much the box itself adds", "pos": "Shops show +20–30 whp; one tuner measured ~2 whp from the box alone with the rest from tuning.", "call": "Budget for the tune: that''s where the power is."}, {"topic": "Turner vs Karbonius", "pos": "Turner flow-tested ~20% over stock; Karbonius fans note a snorkel option for cooler air.", "call": "Either works; pick on fit, snorkel and price."}], "sources": ["Buildjournal: Turner CSL-style intake dyno results", "22RPD: S54 Turner airbox on the dyno", "Eventuri E46 M3 Hybrid release (IND)", "BMWBLOG: Evolve carbon airbox", "BimmerWorld Epic Alpha-N listing", "Right Foot Down: tuner''s guide to the E46 M3", "ZPost and NAM3Forum CSL airbox threads", "Buildjournal throttle body/ICV and CSL install DIYs"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-belts', '{"id": "e46-belts", "title": "Drive belts, tensioners & idler", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Same belts for the S54 Z3 M and Z4 M", "category": "Engine", "kind": "repair", "heroId": "e46-belt-hero", "heroCap": "Two belts: the main belt (water pump, alternator, power steering) on a hydraulic tensioner, and the A/C belt on a mechanical tensioner. The upper idler comes off first. Photograph your routing before anything comes off.", "glance": {"timeFirst": "1.5–2 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$40–200", "risk": "Wrong routing on the A/C belt · a brittle plastic pulley breaking later", "why": "The pulleys are plastic with bearings inside. When one seizes or shatters, the belt goes and takes power steering, charging and the water pump with it.", "note": "BimmerWorld suggests new pulleys every other belt change, about every 80,000 miles."}, "lifespan": {"headline": ["Belts ~60,000 miles · pulleys ~80,000 miles"], "earliest": "Owners report idler pulleys seizing from about 57,000 miles.", "factors": ["Age", "Heat"], "inspect": ["Cracks across the ribs, frayed edges, a growling idler"], "confidence": {"level": "medium", "n": 2, "note": "BimmerWorld; ZHP Mafia owner reports."}}, "should": {"yesIf": ["Squeal or chirp at start-up", "Cracked or glazed belt", "Growling from the front with the fan clutch ruled out", "Doing the cooling overhaul"], "codes": [], "notes": [], "confidence": {"level": "medium", "n": 2, "note": "BimmerWorld."}}, "parts": [{"name": "Main drive belt 6PK1460", "pn": "11287837898", "price": "$25", "tier": "oe"}, {"name": "A/C belt 5PK829", "pn": "11287830946", "price": "$12", "tier": "oe"}, {"name": "Upper idler pulley", "pn": "11281748130", "price": "$15", "tier": "oe", "note": "Early cars use an off-centre-bolt idler: check yours before ordering"}, {"name": "Hydraulic tensioner pulley", "pn": "11281748131", "price": "$15", "tier": "oe"}, {"name": "A/C tensioner assembly", "price": "$60–90", "tier": "oe", "note": "Its pulley only comes with a new tensioner"}], "aftermarket": [{"name": "BimmerWorld belt and pulley set", "note": "Both belts plus idler and tensioner pulleys", "price": "$70", "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Engine/Pulleys/Belt-and-Pulley-Set-OEM-E46-M3-MZ3-S54-Z4M.html"}]}], "tools": [{"name": "16 mm socket", "note": "Idler bolt"}, {"name": "Long ratchet or breaker bar for the tensioners"}, {"name": "Torque wrench"}], "before": ["Photograph the routing.", "Fan and shroud out makes this much easier; most people do it with the cooling job."], "steps": [{"title": "Remove the idler", "blocks": [{"t": "text", "b": "Pop the plastic cap off the upper idler and remove its bolt. Owners stress this has to come off before the A/C belt will."}]}, {"title": "Remove the A/C belt", "blocks": [{"t": "text", "b": "Lever the mechanical A/C tensioner and slip the belt off."}]}, {"title": "Remove the main belt", "blocks": [{"t": "text", "b": "Lever the hydraulic tensioner slowly to compress it and remove the main belt."}]}, {"title": "Spin every pulley", "blocks": [{"t": "text", "b": "Each should turn smoothly and silently with no wobble. Replace any that grind, wobble or show cracks."}]}, {"title": "Fit the new belts", "blocks": [{"t": "text", "b": "Main belt first, finishing at the power steering pulley with the tensioner held back. Then the A/C belt: owners report it runs over the power steering pulley and under the idler, so fit the belt before the idler goes back on."}, {"t": "torque", "label": "Idler and tensioner pulley bolts, grade 8.8", "nm": 24, "c": {"level": "medium", "n": 1, "note": "Bentley E46 manual: where BMW gives no unique torque, use the general value for the bolt grade marked on the head."}}, {"t": "torque", "label": "Idler and tensioner pulley bolts, grade 10.9", "nm": 34, "c": {"level": "medium", "n": 1, "note": "Bentley E46 manual: where BMW gives no unique torque, use the general value for the bolt grade marked on the head."}}, {"t": "note", "b": "No S54-specific pulley torque was found. Check the grade stamped on the bolt head and use the matching value."}, {"t": "note", "b": "Your photo beats any written routing. Check it before refitting the fan."}], "caution": true}], "alsoReplace": [{"name": "Fan clutch", "why": "Already reachable."}], "check": {"tab": "Read the parts", "title": "What the old parts tell you", "illId": "e46-belt-hero", "illCap": "Pulley layout, schematic.", "rows": [{"see": "Cracks across the ribs", "means": "Belt aged out.", "do": "Replace it."}, {"see": "Pulley wobbles or grinds", "means": "Bearing worn.", "do": "Replace the pulley."}, {"see": "Shiny glazed belt edges", "means": "Slipping: weak tensioner.", "do": "Replace the tensioner."}], "c": {"level": "community", "n": 2, "note": "Standard practice."}}, "aftercare": ["Listen for squeal on the first cold start."], "disagreements": [{"topic": "Pulley interval", "pos": "BimmerWorld: every other belt change. Owners who''ve had seizures say replace them with every belt.", "call": "Pulleys are cheap; do them every time on a high-mileage car."}, {"topic": "Pulley bolt torque", "pos": "BMW publishes no unique S54 figure. E9x M3 owners quote TIS at 40 Nm for that engine''s idler, a different engine.", "call": "Use Bentley''s bolt-grade value for the grade on the head."}], "sources": ["BimmerWorld S54 belt and pulley set", "BimmerWorld A/C belt listing", "Turner/Bremmen S54 tensioner listings", "M3Post E46 M3 belt DIY threads", "ZHP Mafia idler pulley thread"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-cooling-overhaul', '{"id": "e46-cooling-overhaul", "title": "Cooling system overhaul", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Water pump and thermostat are shared with the S54 Z3 M and Z4 M; radiator and hoses are E46 M3-specific", "category": "Engine", "kind": "repair", "heroId": "e46-cool-hero", "heroCap": "On the S54 the thermostat lives inside the water pump housing at the front of the engine, behind the mechanical fan. Radiator, expansion tank and hoses sit ahead of it.", "glance": {"timeFirst": "4–7 hr", "timeRepeat": "3–4 hr", "difficulty": 3, "cost": "$250–1,100", "risk": "Air trapped after refill · cracking an old plastic neck while removing hoses", "why": "Overheating hurts the S54 twice: directly, and by thinning the oil the rod bearings depend on. Plastic tanks and necks age out, and the water pump is a 60–80k part.", "note": "Everything here comes off from the front with the fan out, so refreshing the lot at once saves doing it twice."}, "lifespan": {"headline": ["Water pump 60,000–80,000 miles · plastic parts by age"], "factors": ["Age over mileage for plastic", "Track heat", "Old coolant"], "inspect": ["Squeeze hoses cold: soft or crunchy means replace", "Look for white crust at the expansion tank seams"], "confidence": {"level": "medium", "n": 2, "note": "Bremmen and Turner suggest 60–80k for the pump."}}, "variants": {"questions": [{"question": "How far are you going?", "options": [{"id": "refresh", "label": "Water pump & thermostat", "when": "The parts that wear: pump, 80 °C thermostat, O-rings, coolant"}, {"id": "full", "label": "Full overhaul", "when": "Plus radiator, expansion tank, hoses and cap"}]}, {"question": "Replacing the radiator?", "options": [{"id": "keep", "label": "No, keeping it", "when": "Pump & thermostat only, or the radiator is recent"}, {"id": "oerad", "label": "OE replacement", "when": "Behr/Nissens-style plastic-tank radiator"}, {"id": "alu", "label": "Aluminium upgrade", "when": "CSF triple-pass or Mishimoto, for track use", "brand": true}]}]}, "should": {"yesIf": ["Coolant weeping at the pump weep hole or hoses", "Temperature creeping on track", "No record of a pump past 60k", "Erratic gauge or a thermostat code"], "codes": [], "notes": ["The thermostat can be swapped without the pump, but it''s the same teardown and spills the same coolant (Turner). Do both."], "confidence": {"level": "medium", "n": 2, "note": "Turner, Bremmen."}}, "parts": [{"name": "Water pump with gasket, dowel and thermostat O-ring", "price": "$90–180", "tier": "oem", "note": "Bremmen, Graf, Genuine BMW"}, {"name": "Thermostat, 80 °C", "pn": "11531318274", "price": "$50", "tier": "oe"}, {"name": "Thermostat O-rings ×3 + coolant pipe O-rings ×2", "pn": "11537830712 (pipe)", "price": "$15", "tier": "oe"}, {"name": "BMW coolant + distilled water", "price": "$40"}, {"name": "Radiator (OE type)", "price": "$200–350", "tier": "oem", "only": ["oerad"]}, {"name": "Aluminium radiator", "price": "$450–700", "tier": "aftermarket", "note": "CSF triple-pass, Mishimoto", "only": ["alu"]}, {"name": "Expansion tank + cap", "price": "$70–120", "tier": "oem", "only": ["full"]}, {"name": "Upper and lower radiator hoses", "price": "$60–120", "tier": "oem", "only": ["full"]}, {"name": "Bleeder screw", "price": "$8", "tier": "oem"}], "aftermarket": [{"name": "CSF triple-pass aluminium radiator", "note": "Popular track upgrade for the E46 M3", "price": "$550–700", "only": ["alu"]}, {"name": "BMW Motorsport thermostat", "note": "Lower-temperature thermostat used on track cars", "price": "$60"}, {"name": "Mishimoto E46 M3 oil cooler kit", "note": "Bolt-in cooler; claims a 16.7 °C oil temperature drop", "price": "$600"}], "tools": [{"name": "32 mm fan nut wrench + water pump pulley holder", "note": "The BMW fan clutch tool set"}, {"name": "Torque wrench 10–40 Nm"}, {"name": "Hose pick, drain pan, funnel"}], "before": ["Engine stone cold. Hot coolant under pressure scalds.", "Have 2+ gallons of 50/50 ready."], "chapters": [{"id": "front", "title": "Front end off", "blurb": "Fan, shroud, belts."}, {"id": "pump", "title": "Pump & thermostat"}, {"id": "rad", "title": "Radiator, tank & hoses"}, {"id": "fill", "title": "Fill & bleed"}], "steps": [{"title": "Drain and remove the fan", "blocks": [{"t": "text", "b": "Drain the coolant. Hold the pump pulley with the holder and undo the fan''s 32 mm nut, then lift the fan and shroud out together."}, {"t": "note", "b": "BMW viscous fan nuts are usually left-hand threaded, so they loosen clockwise viewed from the front. If it won''t move, try the other way before using force."}], "chapter": "front"}, {"title": "Remove the drive belt", "blocks": [{"t": "text", "b": "Relieve the tensioner and slip the belt off. Note the routing, or photograph it, before it comes off."}], "chapter": "front"}, {"title": "Remove the water pump", "blocks": [{"t": "text", "b": "Remove the pulley, the pump housing bolts, and the pump. Don''t miss the flanged bolt that goes into the cylinder head behind the thermostat cover."}, {"t": "warn", "b": "That flanged bolt holds the left timing chain guide rail. Turner says make sure it''s tight before you close up: if it backs out the engine can be badly damaged."}], "chapter": "pump", "caution": true}, {"title": "Fit the new pump and thermostat", "blocks": [{"t": "text", "b": "Clean the sealing faces. Fit the new thermostat with its three O-rings and the coolant pipe O-rings, then the pump with its dowel and gasket."}, {"t": "torque", "label": "Pump and housing bolts (M6)", "nm": 10, "c": {"level": "medium", "n": 2, "note": "Standard BMW M6 fastener torque used on the S54''s pump and housing bolts; confirm in Bentley."}}], "chapter": "pump"}, {"title": "Replace radiator, tank and hoses", "blocks": [{"t": "text", "b": "Remove the hoses at their necks, unclip the radiator and lift it out with the expansion tank if fitted together. Fit the new parts, with new O-rings on every push-in connection."}, {"t": "warn", "b": "Old plastic necks snap. Support the neck when you pull a hose, and check new hoses seat to their stops."}], "chapter": "rad", "only": ["full"]}, {"title": "Refit belt, fan and shroud", "blocks": [{"t": "text", "b": "Belt on along the noted route, fan and shroud back in, fan nut tight against the pulley holder."}], "chapter": "fill"}, {"title": "Fill and bleed", "blocks": [{"t": "text", "b": "Open the bleeder. Ignition on (engine off), heater to full hot. Fill slowly until coolant runs from the bleeder without bubbles, close it, then start the engine and top up as it warms."}, {"t": "note", "b": "Squeeze the upper hose to push air out. Check the level again cold the next morning."}], "chapter": "fill", "caution": true}], "alsoReplace": [{"name": "Drive belt", "why": "It''s off anyway."}, {"name": "Fan clutch", "why": "Already out. A clutch that spins freely hot won''t cool at idle."}], "check": {"tab": "Read the parts", "title": "What the old parts tell you", "illId": "e46-cool-hero", "illCap": "Pump and thermostat at the front of the engine.", "rows": [{"see": "Wobble in the old pump pulley", "means": "Bearing worn.", "do": "You did it in time."}, {"see": "Brown sludge in the coolant", "means": "Old or mixed coolant.", "do": "Flush until clear before the final fill."}, {"see": "Cracked necks or tank seams", "means": "Plastic aged out.", "do": "Full overhaul is the right call."}], "c": {"level": "community", "n": 2, "note": "Owner practice."}}, "aftercare": ["Recheck coolant level cold for the next few days.", "Look for drips at each new connection."], "disagreements": [{"topic": "Lower-temperature thermostat", "pos": "Track builds often fit BMW Motorsport or lower-temperature thermostats; street cars run the 80 °C part.", "call": "80 °C on the street."}], "sources": ["Turner Motorsport S54 thermostat listings", "Bremmen Parts S54 water pump listing", "Beisan Systems (fan and shroud removal tools)", "Mishimoto E46 M3 oil cooler kit", "BimmerWorld NASA GTS3 E46 M3 build list"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-exhaust', '{"id": "e46-exhaust", "title": "Aftermarket exhaust: section 1, section 2 & mufflers", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Pieces mix with stock and with each other", "category": "Engine", "kind": "upgrade", "heroId": "e46-ex-hero", "heroCap": "After the headers: section 1 (front resonator on US cars), section 2 (rear resonator) and the quad-tip rear mufflers.", "glance": {"timeFirst": "2–3 hr", "timeRepeat": "1.5 hr", "difficulty": 2, "cost": "$400–3,500", "risk": "Drone on the highway · hanger alignment", "why": "Behind the headers, exhaust changes are about sound: the S54''s high-rev rasp, made deeper, louder or more exotic. Owners agree the install is much the same across brands; what differs is tone, drone and fit.", "note": "Listen before you buy: owners on every forum say clips flatter loud systems, and drone at 70–80 mph in 6th is what makes people switch back."}, "lifespan": {"headline": ["Permanent"], "factors": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "variants": {"questions": [{"question": "What are you replacing?", "options": [{"id": "s1", "label": "Section 1", "when": "Front pipe: US resonator, or cats on Euro-style setups"}, {"id": "s2", "label": "Section 2", "when": "Rear resonator / X-pipe before the mufflers"}, {"id": "muff", "label": "Rear mufflers", "when": "Where most of the brand choice is"}, {"id": "full", "label": "Full cat-back system"}]}, {"question": "What sound are you after?", "options": [{"id": "quiet", "label": "Close to stock, a bit deeper", "when": "Daily driver, no drone"}, {"id": "sporty", "label": "Noticeably sportier", "when": "Louder under load, livable on the highway"}, {"id": "loud", "label": "Loud / track", "when": "Expect drone and cabin noise"}]}]}, "should": {"yesIf": ["You want more S54 sound", "Fitting headers that need a new section 1"], "codes": [], "notes": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "parts": [{"name": "Section 1 (straight pipe, resonated or with high-flow cats)", "price": "$400–2,300", "tier": "aftermarket", "only": ["s1", "full"]}, {"name": "Section 2 (resonator, delete or X-pipe)", "price": "$400–800", "tier": "aftermarket", "only": ["s2", "full"]}, {"name": "Rear mufflers", "price": "$600–3,500", "tier": "aftermarket", "only": ["muff", "full"]}, {"name": "Exhaust gaskets, clamps and new nuts", "price": "$30–60", "tier": "oe"}, {"name": "Exhaust hangers (if sagging)", "price": "$20–40", "tier": "oe"}], "aftermarket": [{"name": "Eisenmann Performance (Sport sound)", "note": "Bolt-on using factory mounting points; 304 stainless, handmade in Germany; 4×76 or 4×83 mm Le Mans tips. A NAM3 owner calls the Sport ''OE enhanced plus a little deeper''.", "price": "$2,670", "only": ["muff+quiet", "full+quiet"]}, {"name": "Dinan rear muffler", "note": "The best-mannered of the common options with no drone, per an e46fanatics owner. Two of the four tips are dummies.", "price": "$1,000–1,400", "only": ["muff+quiet", "full+quiet"]}, {"name": "Borla", "note": "Drifted rates it the quietest, with next to no drone and little rasp. One e46fanatics owner disagrees and calls it very loud.", "price": "varies", "only": ["muff+quiet", "full+quiet"]}, {"name": "Remus", "note": "Calmer, clean sound with a throaty growl at high rpm; 4×84 mm tips (Drifted). Availability is patchy.", "price": "varies", "only": ["muff+quiet", "full+quiet"]}, {"name": "Supersprint Street (Stradale)", "note": "A NAM3 owner with Euro headers and a CSL box says it sounds like stock with a subtle deeper touch.", "price": "$1,000–1,500", "only": ["muff+quiet", "full+quiet"]}, {"name": "Eisenmann Performance (Race sound)", "note": "The louder Eisenmann. Deeper idle than Supersprint; some owners find it raspy.", "price": "$2,670", "only": ["muff+sporty", "full+sporty"]}, {"name": "Supersprint Sport", "note": "Probably closest to still sounding like the BMW note, per an owner who''s run several.", "price": "$1,200–1,600", "only": ["muff+sporty", "full+sporty"]}, {"name": "Billy Boat (B&B)", "note": "Low, rumbly idle that screams up top; maker claims no interior resonance. Quad 76 mm tips.", "price": "varies", "only": ["muff+sporty", "full+sporty"]}, {"name": "Megan Racing axle-back", "note": "Budget pick: deep clean tone, light, clamps instead of flanges. Some drone and slight sag reported.", "price": "$300–450", "only": ["muff+sporty", "full+sporty"]}, {"name": "Milltek cat-back", "note": "Love-or-hate: several owners on m3cutters and RMS say it''s boomy and loses the rasp; Drifted also notes fitment complaints.", "price": "$1,500–2,000", "only": ["muff+sporty", "full+sporty"]}, {"name": "Rogue Engineering muffler", "note": "Much lighter than stock; one owner thought the Y-pipe tips looked cheap.", "price": "varies", "only": ["muff+sporty", "full+sporty"]}, {"name": "MagnaFlow", "note": "A 6SpeedOnline owner called it the best daily-driver option he''d run.", "price": "varies", "only": ["muff+sporty", "full+sporty"]}, {"name": "Supersprint Race / Lightweight Race", "note": "The most popular E46 M3 system: loud and throaty to the redline. A UK owner says the Lightweight Race doesn''t drone at 70–80 mph in 6th; others find it too loud for a daily.", "price": "$1,200–1,800", "only": ["muff+loud", "full+loud"]}, {"name": "Gruppe M titanium", "note": "Close to straight pipes. Several owners call it unbearable inside the car for daily use.", "price": "varies", "only": ["muff+loud", "full+loud"]}, {"name": "Agency Power titanium", "note": "60 mm pipe, quad 70 mm tips; loud and aggressive with some cruising drone (Drifted).", "price": "varies", "only": ["muff+loud", "full+loud"]}, {"name": "Kreissieg valved cat-back", "note": "The only common E46 M3 system with internal valves to change volume. Priciest; one owner called it the loudest thing he''d heard.", "price": "varies", "only": ["muff+loud", "full+loud"]}, {"name": "Meisterschaft (GTHAUS) titanium or stainless", "note": "Aggressive tone; Drifted reports some mounting-bracket fit issues, so check fit before final tightening.", "price": "varies", "only": ["muff+loud", "full+loud"]}, {"name": "Scorpion", "note": "Good reviews, but a UK owner found it too loud.", "price": "varies", "only": ["muff+loud", "full+loud"]}, {"name": "Supersprint section 1 straight pipe / with HFC", "note": "Straight pipe replaces the US front resonator; the HFC version works with stock headers and stock section 2.", "price": "$400–2,300", "only": ["s1", "full"]}, {"name": "Fabspeed VAC section 1", "note": "Listed in the m3cutters E46 M3 exhaust guide.", "price": "~$1,100 (forum list)", "only": ["s1", "full"]}, {"name": "CPI Euro-style section 1 with high-flow cats", "note": "Euro/CSL layout with HJS-certified cats, no crossover.", "price": "~$1,500 (forum list)", "only": ["s1", "full"]}, {"name": "Status Gruppe section 1 with high-flow cats", "note": "200- or 400-cell; a CA-compliant 400-cell version listed.", "price": "~$630 (forum list)", "only": ["s1", "full"]}, {"name": "Supersprint section 2 (resonated, delete or X-pipe)", "note": "Resonated to tame drone, delete for volume; X-pipe works with stock section 1 and muffler.", "price": "$400–800", "only": ["s2", "full"]}, {"name": "Agency Power / Sound of Speed section 2", "note": "True dual (Agency Power) or X-pipe crossover with no resonators (Sound of Speed).", "price": "$400–680 (forum list)", "only": ["s2", "full"]}, {"name": "Borla mid-pipe V2", "note": "Replaces sections 1 and 2 together; can''t be used separately.", "price": "~$800 (forum list)", "only": ["s1", "s2", "full"]}], "tools": [{"name": "Penetrating oil"}, {"name": "Exhaust hanger pliers"}, {"name": "Jack to support sections"}], "before": ["Exhaust cold."], "steps": [{"title": "What you get", "blocks": [{"t": "note", "b": "We couldn''t find an independent before/after dyno for any E46 M3 cat-back. Owners of older M3s report under 10 hp from muffler and resonator changes; the measured gains are in headers and tuning (see those guides)."}, {"t": "ill", "id": "e46-ex-sound", "cap": "What each section changes: section 1 adds rasp, section 2 adds volume, mufflers set the character and drone."}]}, {"title": "Hear them first", "blocks": [{"t": "text", "b": "Here are clips for the options that match the sound you picked. Phone speakers flatten everything: use headphones, and listen for the 3,000–4,000 rpm cruise range as well as the redline."}, {"t": "embed", "id": "TR--f4KnIJ4", "title": "Sound clip: Eisenmann", "note": "From Drifted''s E46 M3 exhaust guide; they warn the cars in these videos may have other mods (headers, intakes), so judge the character, not the volume.", "only": ["muff+quiet", "muff+sporty", "full+quiet", "full+sporty"]}, {"t": "embed", "id": "q1gAPVPPSlQ", "title": "Sound clip: Dinan", "note": "From Drifted''s E46 M3 exhaust guide; they warn the cars in these videos may have other mods (headers, intakes), so judge the character, not the volume.", "only": ["muff+quiet", "full+quiet"]}, {"t": "embed", "id": "p83nb98KBhM", "title": "Sound clip: Borla", "note": "From Drifted''s E46 M3 exhaust guide; they warn the cars in these videos may have other mods (headers, intakes), so judge the character, not the volume.", "only": ["muff+quiet", "full+quiet"]}, {"t": "embed", "id": "c9NEmh6X8lk", "title": "Sound clip: Remus", "note": "From Drifted''s E46 M3 exhaust guide; they warn the cars in these videos may have other mods (headers, intakes), so judge the character, not the volume.", "only": ["muff+quiet", "full+quiet"]}, {"t": "embed", "id": "nmmbeCLVZxE", "title": "Sound clip: Billy Boat", "note": "From Drifted''s E46 M3 exhaust guide; they warn the cars in these videos may have other mods (headers, intakes), so judge the character, not the volume.", "only": ["muff+sporty", "full+sporty"]}, {"t": "embed", "id": "zBuBnFN8Yos", "title": "Sound clip: Megan Racing", "note": "From Drifted''s E46 M3 exhaust guide; they warn the cars in these videos may have other mods (headers, intakes), so judge the character, not the volume.", "only": ["muff+sporty", "full+sporty"]}, {"t": "embed", "id": "dceYfd-WM8E", "title": "Sound clip: Milltek", "note": "From Drifted''s E46 M3 exhaust guide; they warn the cars in these videos may have other mods (headers, intakes), so judge the character, not the volume.", "only": ["muff+sporty", "full+sporty"]}, {"t": "embed", "id": "N3TP4ngPtIw", "title": "Sound clip: Supersprint Race", "note": "From Drifted''s E46 M3 exhaust guide; they warn the cars in these videos may have other mods (headers, intakes), so judge the character, not the volume.", "only": ["muff+loud", "muff+sporty", "full+loud", "full+sporty"]}, {"t": "embed", "id": "oUOImLeby2Y", "title": "Sound clip: Full Supersprint (headers, race cats, X-pipe, Race mufflers)", "note": "An owner''s car posted on 6SpeedOnline; headers and cats are also changed.", "only": ["muff+loud", "full+loud"]}, {"t": "embed", "id": "2B4_CO4G86I", "title": "Sound clip: Gruppe M titanium", "note": "From Drifted''s E46 M3 exhaust guide; they warn the cars in these videos may have other mods (headers, intakes), so judge the character, not the volume.", "only": ["muff+loud", "full+loud"]}, {"t": "embed", "id": "AWpaWiBpw0w", "title": "Sound clip: Agency Power titanium", "note": "From Drifted''s E46 M3 exhaust guide; they warn the cars in these videos may have other mods (headers, intakes), so judge the character, not the volume.", "only": ["muff+loud", "full+loud"]}, {"t": "embed", "id": "ZgQIe_q-36M", "title": "Sound clip: Kreissieg valved", "note": "From Drifted''s E46 M3 exhaust guide; they warn the cars in these videos may have other mods (headers, intakes), so judge the character, not the volume.", "only": ["muff+loud", "full+loud"]}, {"t": "embed", "id": "BXYeDA4OJMk", "title": "Sound clip: Meisterschaft titanium", "note": "From Drifted''s E46 M3 exhaust guide; they warn the cars in these videos may have other mods (headers, intakes), so judge the character, not the volume.", "only": ["muff+loud", "full+loud"]}, {"t": "note", "b": "An m3cutters meet video lined up stock, an Eisenmann backbox and Supersprint Race side by side. Owners there found stock quiet below 4,000 rpm, the Eisenmann deeper, and the Supersprint loudest. Search ''E46 M3 OEM exhaust sound comparison Eisenmann Supersprint'' to find it."}]}, {"title": "Pick the front pieces", "blocks": [{"t": "text", "b": "Section 1 changes the most rasp for the money; section 2 is how you tune volume and drone. Many owners keep a resonated section 2 so a louder muffler stays livable."}, {"t": "note", "b": "If you have aftermarket headers, buy a section 1 that matches their outlet size and flange (Euro and US flanges are clocked differently)."}], "only": ["s1", "s2", "full"]}, {"title": "Support and separate", "blocks": [{"t": "text", "b": "Exhaust cold, car high and level. Support the system with a jack, undo the clamp or flange for the section you''re replacing, and slide it off its rubber hangers."}, {"t": "note", "b": "The install is much the same for every brand: most bolt to the factory mounting points with the factory hardware."}]}, {"title": "Fit loosely and align", "blocks": [{"t": "text", "b": "Fit new gaskets, hang the new piece loosely on all hangers, and line up the tips evenly in the bumper cut-outs before anything is tight. Then tighten from front to rear."}], "caution": true}, {"title": "Brand-specific notes", "blocks": [{"t": "note", "b": "Eisenmann: true bolt-on using factory mounting points and hardware (IND Distribution)."}, {"t": "note", "b": "Megan Racing: uses clamps instead of flanges; re-check them after the first heat cycle."}, {"t": "note", "b": "Dinan: two of the four tips are dummies by design."}, {"t": "note", "b": "Meisterschaft titanium: check the mounting bracket fit before final tightening; Drifted reports some issues."}, {"t": "note", "b": "Kreissieg: valved; set up the valve control per the kit before the first drive."}], "only": ["muff", "full"]}, {"title": "Check for leaks and drone", "blocks": [{"t": "text", "b": "Start it and listen for ticking at every joint. Then drive at highway speed in 6th: if it drones, a resonated section 2 is the usual fix before giving up on the muffler."}]}], "alsoReplace": [{"name": "Exhaust hangers", "why": "Old rubber sags and makes tips sit unevenly."}], "check": {"tab": "Check it", "title": "After fitting", "illId": "e46-ex-hero", "illCap": "Exhaust sections.", "rows": [{"see": "Tips uneven or touching the bumper", "means": "Alignment.", "do": "Loosen everything and re-hang front to back."}, {"see": "Drone at 70–80 mph", "means": "Too little resonance for that muffler.", "do": "Fit a resonated section 2."}, {"see": "Ticking from a joint", "means": "Leak.", "do": "New gasket, re-tighten."}], "c": {"level": "community", "n": 3, "note": "Owner reports across forums."}}, "aftercare": [], "disagreements": [{"topic": "Power from a cat-back", "pos": "Some brands advertise gains; we found no independent E46 M3 data.", "call": "Buy it for the sound."}, {"topic": "How loud is the Borla?", "pos": "Drifted calls it the quietest option; an e46fanatics owner says it''s very loud.", "call": "Listen to a clip on a car with your setup."}, {"topic": "Milltek", "pos": "Several UK owners call it boomy with the rasp gone; others like its depth.", "call": "Hear one in person if you can."}, {"topic": "Is any aftermarket muffler better than stock?", "pos": "Some owners prefer the OEM sound and say the CSL intake roar matters more.", "call": "Pair a mild muffler with a CSL airbox if you want character without drone."}], "sources": ["Drifted: Ultimate BMW E46 M3 exhaust guide (videos and owner notes)", "IND Distribution: Eisenmann E46 M3 Performance exhaust", "e46fanatics: OEM vs Eisenmann vs Supersprint comparison; exhaust decision threads", "m3cutters: E46 M3 sound comparison; definitive E46 M3 exhaust guide", "NAM3Forum: best sounding exhaust thread", "RMS Motoring forum: E46 M3 exhaust thread", "6SpeedOnline: best sounding E46 M3 exhaust thread", "Turner Motorsport Supersprint E46 M3 listings"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-fuel-filter', '{"id": "e46-fuel-filter", "title": "Fuel filter & pressure regulator", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Filter 13327831089 is also listed for the S54 Z3 M", "category": "Engine", "kind": "repair", "heroId": "e46-ff-hero", "heroCap": "Under the car on the driver''s side, behind plastic underbody covers and a small metal shield: the filter with the pressure regulator screwed onto its end.", "glance": {"timeFirst": "1–1.5 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$110–330", "risk": "Fuel spray from a pressurised line · fire", "why": "A clogged filter makes the pump work harder and can starve the engine at high rpm. On the M3 the regulator sits on the same housing, which makes it the place for an adjustable regulator if you''re adding power.", "note": "Depressurise first and work with the battery disconnected. No sparks, no smoking, extinguisher nearby."}, "lifespan": {"headline": ["Every 60,000 miles or when fuel pressure drops"], "factors": ["Old fuel", "Tank debris"], "confidence": {"level": "community", "n": 1, "note": "Common BMW practice; no M3-specific interval found."}}, "variants": {"question": "OE filter or the Radium kit?", "options": [{"id": "oe", "label": "Genuine BMW filter", "when": "Like-for-like (13327831089)"}, {"id": "radium", "label": "Radium FPR + filter kit", "when": "Adjustable regulator, high-flow filter, E85-ready", "brand": true}]}, "should": {"yesIf": ["No record of a filter", "Lean codes under load", "Adding a supercharger or E85"], "codes": ["P0171", "P0174"], "notes": [], "confidence": {"level": "medium", "n": 1, "note": "Turner, Radium."}}, "parts": [{"name": "Fuel filter", "pn": "13327831089", "price": "$110", "tier": "oe", "only": ["oe"]}, {"name": "Radium FPR & fuel filter kit", "pn": "20-0932-03 / -05", "price": "$280–330", "tier": "aftermarket", "note": "Stainless (03) or microglass (05) element", "only": ["radium"]}, {"name": "Hose clamps (if fitted)", "price": "$5"}, {"name": "Copper crush washer (filter to regulator)", "price": "$2", "tier": "oe", "only": ["oe"]}, {"name": "Small vacuum line connector", "price": "$3", "tier": "oe", "note": "Often brittle; have a spare"}], "aftermarket": [], "tools": [{"name": "19 mm open-end or thin adjustable wrench", "note": "On the filter"}, {"name": "Second adjustable wrench or channel locks", "note": "On the regulator: don''t crush it"}, {"name": "8 mm deep and 10 mm sockets", "note": "Covers and shield"}, {"name": "Drain pan, rags, safety glasses"}, {"name": "Fire extinguisher"}], "before": ["Pull the fuel pump fuse or relay (check the label in your fuse box), start the engine and let it stall, then crank a few seconds.", "Disconnect the battery."], "steps": [{"title": "Get to the filter", "blocks": [{"t": "text", "b": "Raise the driver''s side safely. Remove the plastic underbody covers, then the small metal shield over the filter (8 mm and 10 mm). The filter shows behind the shield."}, {"t": "note", "b": "Owner DIY on e46fanatics. The filter sits under the driver''s footwell area, mounted horizontally."}]}, {"title": "Split the filter from the regulator", "blocks": [{"t": "text", "b": "Catch the fuel in a pan. Hold the filter with the 19 mm wrench and the regulator with the second wrench, and unscrew the regulator from the filter. Unclip the small vacuum line, disconnect the fuel line, and remove the filter from its bracket."}, {"t": "note", "b": "You can also remove filter and regulator together, but the owner who wrote the DIY found the rubber hose on the regulator side wouldn''t come off and left it in place."}, {"t": "warn", "b": "Fuel will spill. Eyes protected, no ignition sources."}], "caution": true}, {"title": "Fit the new filter", "blocks": [{"t": "text", "b": "New copper crush washer between filter and regulator. Fit the filter with its flow arrow toward the engine, screw the regulator on snug, reconnect the fuel and vacuum lines and secure the bracket."}, {"t": "note", "b": "Radium kit: follow its instructions for the adapter fittings and set pressure with the supplied gauge.", "only": ["radium"]}]}, {"title": "Check for leaks", "blocks": [{"t": "text", "b": "Refit the fuse, reconnect the battery, and turn the key to run the pump a few times without starting. Check every joint is dry before starting the engine."}]}], "alsoReplace": [], "check": {"tab": "Check your work", "title": "After the swap", "illId": "e46-ff-hero", "illCap": "Filter and regulator on the underside.", "rows": [{"see": "Long crank on the first start", "means": "Normal: the filter is filling.", "do": "Let the pump prime a few times."}, {"see": "Fuel smell or drip", "means": "A fitting isn''t sealed.", "do": "Stop and fix it before driving."}, {"see": "Lean codes return", "means": "Pump or regulator, not the filter.", "do": "Test fuel pressure."}], "c": {"level": "community", "n": 1, "note": "General fuel-system practice."}}, "aftercare": ["Recheck for leaks the next day."], "disagreements": [{"topic": "Interval", "pos": "BMW lists none for many models; specialists suggest 50–60k.", "call": "60k, or sooner if you add power."}], "sources": ["Turner Motorsport Genuine BMW E46 M3 fuel filter and FPR housing listings", "Radium Engineering E46 M3 FPR & fuel filter kit", "e46fanatics: E46 M3 fuel filter change DIY"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-headers', '{"id": "e46-headers", "title": "Headers & catalytic converters", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "US cars carry the cats in the headers; Euro cars carry them in section 1, with differently clocked flanges", "category": "Engine", "kind": "upgrade", "heroId": "e46-hdr-hero", "heroCap": "US E46 M3: the catalytic converters are built into the exhaust manifolds. Any tubular header is therefore also a cat change. Euro cars have catless manifolds with the cats in section 1.", "glance": {"timeFirst": "5–8 hr", "timeRepeat": "4 hr", "difficulty": 4, "cost": "$700–3,000 + tune", "risk": "Seized manifold studs · O2 sensor leads near hot pipes · legal compliance", "why": "The US manifold-cats are the biggest restriction on the S54. Catless or high-flow headers with a tune are the largest naturally aspirated gain short of cams.", "note": "Long primaries move power up the rev range: Buildjournal''s ARH test gained up top but lost torque between 3,200 and 5,000 rpm versus a traditional header."}, "lifespan": {"headline": ["Permanent upgrade"], "factors": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "variants": {"questions": [{"question": "Which headers?", "options": [{"id": "ss", "label": "Supersprint stepped + sport cats", "when": "Stepped headers, metallic cats in section 1", "brand": true}, {"id": "epic", "label": "Epic equal-length", "when": "Stepped primaries; needs aftermarket section 1", "brand": true}, {"id": "arh", "label": "American Racing long-tube", "when": "Catted or catless; top-end power", "brand": true}, {"id": "euro", "label": "Euro OE manifolds", "when": "Used take-offs; cats move to a catted section 1"}, {"id": "afe", "label": "aFe catted manifold", "when": "Built-in 400-cell cats", "brand": true}]}, {"question": "Car use?", "options": [{"id": "road", "label": "Road car (keep cats)"}, {"id": "track", "label": "Track-only (catless)"}]}]}, "should": {"yesIf": ["You want the biggest NA gain", "Planning a tune anyway"], "codes": ["P0420", "P0430"], "notes": ["Removing or replacing catalytic converters on a road car is illegal in the US and most other markets, and an Alpha-N or catless tune generally won''t pass emissions readiness checks. These routes are for track cars.", "Cat codes return if the file doesn''t match the hardware."], "confidence": {"level": "medium", "n": 2, "note": ""}}, "parts": [{"name": "Supersprint stepped headers + sport-cat section 1", "price": "$2,500–3,500", "tier": "aftermarket", "only": ["ss"]}, {"name": "Epic E46 M3 headers", "price": "$1,800–2,200", "tier": "aftermarket", "note": "304L stainless, made in USA", "only": ["epic"]}, {"name": "ARH long-tube system", "price": "$2,000–3,000", "tier": "aftermarket", "only": ["arh"]}, {"name": "Euro OE manifolds (used) + catted section 1", "price": "$800+", "tier": "oe", "only": ["euro"]}, {"name": "aFe catted manifold", "price": "$1,200–1,600", "tier": "aftermarket", "only": ["afe"]}, {"name": "Manifold stud and nut kit", "price": "$40–80", "tier": "oe", "note": "Turner sells an E46 M3 kit"}, {"name": "Exhaust gaskets", "price": "$30", "tier": "oe"}, {"name": "Tune for headers", "price": "$400–1,200", "tier": "aftermarket"}], "aftermarket": [], "tools": [{"name": "Penetrating oil, long extensions, swivels"}, {"name": "22 mm O2 sensor socket"}, {"name": "Torque wrench"}], "before": ["Soak every manifold nut for a day before.", "Exhaust cold, car high on stands."], "chapters": [{"id": "gain", "title": "What you get"}, {"id": "out", "title": "Old manifolds out"}, {"id": "in", "title": "Headers in & tune"}], "steps": [{"title": "What you get", "blocks": [{"t": "chart", "title": "Headers on the same car, same dyno", "unit": "whp", "baseline": "Stock", "bars": [{"label": "Stock", "v": 286, "note": "91 octane"}, {"label": "Catless + tune (traditional header)", "v": 315}, {"label": "ARH headers, untuned", "v": 329}, {"label": "ARH headers, tuned", "v": 351, "note": "91 octane"}, {"label": "ARH headers, tuned, E30", "v": 355}], "source": "Buildjournal: same 2003 E46 M3, same dyno (European Auto Source, Anaheim), 91 octane, wheel hp.", "c": {"level": "high", "n": 1, "note": "One car, back-to-back on one dyno: the best kind of comparison, but still one car."}}, {"t": "note", "b": "The trade-off: against a traditional header on the same car, the ARH long-tube lost about 34 wtq and 26 whp at 4,000 rpm and gave less torque from 3,200–5,000 rpm, then gained 1–6 whp above 6,200 rpm (Buildjournal)."}, {"t": "chart", "title": "Maker claims", "unit": "whp gain", "baseline": null, "bars": [{"label": "aFe catted manifold", "v": 15, "note": "claimed"}, {"label": "Epic vs a competitor header", "v": 10, "note": "claimed +10 hp, +40 lb-ft"}], "source": "Manufacturer figures, different baselines.", "c": {"level": "single", "n": 2, "note": "Maker claims."}}, {"t": "note", "b": "Right Foot Down: headers without a tune may only net 10–15 whp; with a tune, up to ~35 whp over stock."}, {"t": "ill", "id": "e46-hdr-flow", "cap": "US vs Euro layout: cats in the US manifolds, cats in section 1 on Euro cars."}], "chapter": "gain"}, {"title": "Unplug and remove section 1", "blocks": [{"t": "text", "b": "Unplug the O2 sensors at the valve cover bracket, drop section 1 from under the car, and support the rest of the exhaust."}], "chapter": "out"}, {"title": "Remove the manifolds", "blocks": [{"t": "text", "b": "Undo the manifold nuts (expect some studs to come out with them) and lift the manifolds out. Replace damaged studs from the kit."}, {"t": "warn", "b": "A snapped stud in the head means drilling it out: go slowly with heat and penetrating oil."}], "chapter": "out", "caution": true, "timeSink": true}, {"title": "Fit the headers", "blocks": [{"t": "text", "b": "New gaskets, headers on, nuts snug in sequence per the header maker''s instructions. Fit the section 1 that matches your headers (Euro flange clocking differs from US)."}, {"t": "torque", "label": "Oxygen sensors", "nm": 50, "c": {"level": "varies", "n": 2, "note": "No S54 value found; 45–50 Nm is the common BMW/Bosch range."}, "alt": [45]}], "chapter": "in"}, {"title": "Tune", "blocks": [{"t": "text", "b": "Flash a file built for your exact header and cat setup."}, {"t": "note", "b": "Track-only catless setups need a race file to stop cat and O2 codes.", "only": ["track"]}], "chapter": "in", "caution": true}], "alsoReplace": [{"name": "O2 sensors", "why": "Old sensors often break on removal."}, {"name": "Section 1 / exhaust", "why": "Many headers need a matching section 1."}], "check": {"tab": "Check the result", "title": "After fitting", "illId": "e46-hdr-hero", "illCap": "Header and cat layout.", "rows": [{"see": "Ticking when cold", "means": "Gasket leak.", "do": "Re-torque or re-gasket."}, {"see": "P0420/P0430", "means": "Cat efficiency.", "do": "Matching file or catted section."}, {"see": "Soft below 5,000 rpm", "means": "Long-tube character.", "do": "Expected; shorter headers keep more midrange."}], "c": {"level": "medium", "n": 2, "note": ""}}, "aftercare": ["Re-check manifold nuts after a few heat cycles."], "disagreements": [{"topic": "Long-tube vs traditional", "pos": "ARH made more peak power; Buildjournal measured a midrange torque loss versus a traditional header.", "call": "Long-tube for track; traditional for a road car."}], "sources": ["Buildjournal: ARH E46 M3 headers dyno review", "American Racing Headers E46 M3 blog", "Right Foot Down tuner''s guide", "Epic Motorsports E46 M3 headers", "Turner Motorsport Supersprint header listings", "iFixit (US cats in headers)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-o2-sensors', '{"id": "e46-o2-sensors", "title": "Oxygen sensors", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "US-market S54. Euro cars carry their cats in section 1, so post-cat sensors sit further back", "category": "Engine", "kind": "repair", "heroId": "e46-o2-hero", "heroCap": "Four sensors. On US cars the catalysts are inside the exhaust manifolds, so pre- and post-cat sensors are both on the manifolds.", "glance": {"timeFirst": "1–2.5 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$70–400", "risk": "Stripping a seized sensor · mixing up connectors", "why": "A tired pre-cat sensor makes the S54 run rich or lean and hurts fuel economy; a failed post-cat sensor sets a catalyst code.", "note": "Use the code to pick the sensor. Bank 1 is cylinders 1–3, bank 2 is 4–6; sensor 1 is pre-cat, sensor 2 post-cat."}, "lifespan": {"headline": ["Pre-cat sensors ~100,000 miles"], "factors": ["Oil burning", "Misfires"], "confidence": {"level": "community", "n": 2, "note": "Owner experience."}}, "variants": {"question": "Which sensors?", "options": [{"id": "pre", "label": "Pre-cat (sensor 1)", "when": "Lean/rich or heater codes"}, {"id": "post", "label": "Post-cat (sensor 2)", "when": "Catalyst efficiency or sensor 2 codes"}, {"id": "all", "label": "All four", "when": "High mileage, original sensors"}]}, "should": {"yesIf": ["O2 sensor or heater circuit codes", "Rich/lean codes with no vacuum leak", "New catalysts going in"], "codes": ["P0130", "P0136", "P0150", "P0156", "P0171", "P0174", "P0420", "P0430"], "notes": ["Fix vacuum leaks and misfires first; they make good sensors read bad."], "confidence": {"level": "medium", "n": 2, "note": "OBD-II code definitions, BimmerWorld."}}, "parts": [{"name": "Pre-cat sensor, cyl 1–3", "pn": "11781743994", "price": "$90–140", "tier": "oem", "only": ["pre", "all"]}, {"name": "Pre-cat sensor, cyl 4–6", "pn": "Bosch 13952", "price": "$90–140", "tier": "oem", "only": ["pre", "all"]}, {"name": "Post-cat sensor, cyl 4–6", "pn": "11781406622", "price": "$70–110", "tier": "oem", "only": ["post", "all"]}, {"name": "Post-cat sensor, cyl 1–3", "price": "$70–110", "tier": "oem", "note": "Order by position: lengths differ", "only": ["post", "all"]}, {"name": "Anti-seize (if not pre-applied)", "price": "$8"}], "aftermarket": [], "tools": [{"name": "22 mm (7/8\") O2 sensor socket or slotted wrench"}, {"name": "Penetrating oil"}, {"name": "Torque wrench"}], "before": ["Exhaust warm, not hot: sensors come out easier warm.", "Note which connector belongs to which sensor."], "steps": [{"title": "Unplug the sensor", "blocks": [{"t": "text", "b": "Trace the sensor''s lead to its connector bracket on the valve cover (Beisan shows the O2 connectors clipped there) and unplug it."}]}, {"title": "Remove the sensor", "blocks": [{"t": "text", "b": "Soak the threads, then turn it out with the slotted socket. If it fights, warm the engine and try again rather than forcing it."}]}, {"title": "Fit the new sensor", "blocks": [{"t": "text", "b": "Most new Bosch sensors come with anti-seize on the threads; keep it off the tip. Thread it in by hand, then torque."}, {"t": "torque", "label": "Oxygen sensor", "nm": 50, "c": {"level": "varies", "n": 2, "note": "No S54 value found. Bosch''s general spec for M18 sensors and BMW TIS for the E9x M3''s pre-cat sensors are both 50 Nm; that E9x lists 25 Nm for its post-cat sensors."}, "alt": [45]}]}, {"title": "Route and reconnect", "blocks": [{"t": "text", "b": "Route the lead along the original clips, away from the manifold, and reconnect it."}]}], "alsoReplace": [{"name": "Exhaust gas temperature sensor", "why": "Also in the manifold on the S54; inspect its lead while you''re there."}], "check": {"tab": "Read the sensor", "title": "What the old sensor tells you", "illId": "e46-o2-hero", "illCap": "Sensors on the manifolds.", "rows": [{"see": "Light grey tip", "means": "Normal.", "do": "Old age; fine to replace."}, {"see": "Black sooty tip", "means": "Running rich.", "do": "Check injectors, coils, ICV."}, {"see": "White or glazed tip", "means": "Coolant or additive contamination.", "do": "Check for coolant loss."}], "c": {"level": "community", "n": 2, "note": "Standard plug/sensor reading."}}, "aftercare": ["Clear codes and let readiness monitors run over a few drives."], "disagreements": [{"topic": "Replace in pairs?", "pos": "Some replace both sensors on a bank together; others replace only the failed one.", "call": "Replace the failed sensor; do pairs only on original high-mileage sensors."}, {"topic": "Post-cat torque", "pos": "TIS for the E9x M3 lists its post-cat sensors at 25 Nm, half the pre-cat value. We found no S54 figure.", "call": "45–50 Nm on clean, anti-seized threads; don''t exceed 50."}], "sources": ["Turner Motorsport Bosch and Genuine BMW E46 M3 O2 sensor listings", "BimmerWorld Bosch 11781406622 listing", "iFixit E46 M3 oil change guide (US cats in headers)", "Beisan Systems S54 procedure (connector bracket)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-ofh-gasket', '{"id": "e46-ofh-gasket", "title": "Oil filter housing gasket", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Same profile gasket (11421719855) as the M50/M52/M54/S52 six-cylinders; S54 removal steps differ in detail", "category": "Engine", "kind": "repair", "heroId": "e46-ofh-hero", "heroCap": "The housing bolts to the side of the block on a small profile gasket. Alternator, power steering pump and the VANOS oil line all attach to it.", "glance": {"timeFirst": "3–4 hr", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$15–60", "risk": "Oil dripping onto the belt and alternator · forgetting the guide-rail bolt check", "why": "A $6 gasket shrinks with age and lets oil weep down the side of the block onto belts and the exhaust. Turner calls it one of the most common jobs in their shop.", "note": "The VANOS oil line comes off with the housing, so replace its seals, or the line itself, at the same time."}, "lifespan": {"headline": ["Typically weeps by 80,000–120,000 miles"], "factors": ["Age and heat cycles"], "inspect": ["Look for oil on the alternator and under the housing at every oil change"], "confidence": {"level": "community", "n": 2, "note": "Shop and owner experience; no BMW interval."}}, "should": {"yesIf": ["Oil on the alternator or the side of the block below the filter", "Burning-oil smell after a drive", "You''re replacing the alternator or belts anyway"], "codes": [], "notes": ["Rule out the valve cover and VANOS line first: they drip into the same area."], "confidence": {"level": "medium", "n": 2, "note": "Turner, Bentley."}}, "parts": [{"name": "Oil filter housing profile gasket", "pn": "11421719855", "price": "$6", "tier": "oem"}, {"name": "VANOS oil line seals or line", "price": "$15–90", "tier": "oe"}, {"name": "Oil filter kit", "pn": "11427833769", "price": "$15", "tier": "oem"}, {"name": "Drive belt (if worn)", "pn": "11287837898", "price": "$25", "tier": "oe"}], "aftermarket": [], "tools": [{"name": "Torque wrench 10–40 Nm"}, {"name": "Sockets 10–17 mm, Torx set"}, {"name": "Gasket scraper (plastic), brake cleaner"}], "before": ["Engine cold. Loosen the filter cap first so the housing drains into the pan.", "Have rags under the housing: it holds oil."], "steps": [{"title": "Drain the housing and remove the belt", "blocks": [{"t": "text", "b": "Loosen the oil filter cap and wait a few minutes. Remove the drive belt (see the belts guide) and set the tensioner aside."}]}, {"title": "Clear the housing", "blocks": [{"t": "text", "b": "Unbolt the alternator and the power steering pump from the housing bracket and move them aside with their lines attached. Unplug the oil pressure and oil temperature sensors. Disconnect the VANOS oil line from the housing."}, {"t": "note", "b": "Bentley''s sequence is for the M54, but the S54 housing carries the same parts. Photograph each connection before it comes off."}], "timeSink": true}, {"title": "Remove the housing and gasket", "blocks": [{"t": "text", "b": "Remove the housing bolts and lift it off its dowels. Peel out the old profile gasket and clean both faces with a plastic scraper and brake cleaner."}]}, {"title": "Check the guide-rail bolt", "blocks": [{"t": "warn", "b": "On the S54 there''s a flanged bolt into the cylinder head behind the thermostat cover. It holds the left timing chain guide rail: Turner says check it''s tight, because if it backs out the engine can be badly damaged."}, {"t": "text", "b": "Snug it if it''s loose. If it was loose, Turner suggests a new seal ring and a touch of oil-resistant thread sealer."}], "caution": true}, {"title": "Refit", "blocks": [{"t": "text", "b": "New gasket dry into the groove. Align the housing on its dowels and fit the bolts. Tighten to the value for the grade marked on each bolt head."}, {"t": "torque", "label": "Housing bolts, grade 8.8", "nm": 24, "c": {"level": "medium", "n": 1, "note": "Bentley E46 manual (M52/M54 procedure): BMW gives no unique torque, so use the general value for the bolt grade marked on the head."}}, {"t": "torque", "label": "Housing bolts, grade 10.9", "nm": 34, "c": {"level": "medium", "n": 1, "note": "Bentley E46 manual (M52/M54 procedure): BMW gives no unique torque, so use the general value for the bolt grade marked on the head."}}, {"t": "text", "b": "Refit the VANOS line with new seals, the sensors, pump, alternator, tensioner and belt. Top up oil and power steering fluid."}]}], "alsoReplace": [{"name": "VANOS oil line seals", "why": "It''s off anyway, and it''s the other classic leak point here."}, {"name": "Drive belt and pulleys", "why": "The belt is already off."}], "check": {"tab": "Find the leak", "title": "Is it really the housing?", "illId": "e46-ofh-hero", "illCap": "Housing on the side of the block.", "rows": [{"see": "Wet seam between housing and block", "means": "Profile gasket.", "do": "This guide."}, {"see": "Oil on top of the housing and running down", "means": "Valve cover or VANOS line above.", "do": "Fix those first."}, {"see": "Wet filter cap only", "means": "Cap O-rings.", "do": "New filter kit O-rings."}], "c": {"level": "community", "n": 2, "note": "Owner diagnosis."}}, "aftercare": ["Clean the area and check it''s dry after a drive."], "disagreements": [{"topic": "Torque", "pos": "Bentley says BMW gives no unique value for these bolts and lists the general bolt-grade torque.", "call": "Go by the grade on each bolt head."}], "sources": ["Turner Motorsport oil filter housing gasket listing (S54 notes)", "Bentley E46 service manual: oil filter housing gasket, M52/M54 procedure"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-oil-change', '{"id": "e46-oil-change", "title": "Oil & filter change", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Same filter and oil for the S54 Z3 M and Z4 M", "category": "Engine", "kind": "repair", "heroId": "e46-oil-hero", "heroCap": "Filter housing on top of the engine (13 mm bolt in the cap), drain plug under the round cover in the aluminium underpanel.", "glance": {"timeFirst": "45–60 min", "timeRepeat": "30 min", "difficulty": 1, "cost": "$70–110", "risk": "Forgetting the small O-ring on the cap bolt · overfilling", "why": "The S54''s rod bearings live and die by oil. Short intervals with the right oil are the cheapest insurance this engine has.", "note": "Many owners change every 5,000–7,500 miles and send a sample for analysis, well inside the dash indicator."}, "lifespan": {"headline": ["Every 5,000–7,500 miles (owners) · per the service indicator (BMW)"], "earliest": "Track days: change after every few events.", "factors": ["Track use", "Short trips", "High rpm"], "inspect": ["Check the dipstick every fuel stop or two"], "confidence": {"level": "medium", "n": 2, "note": "BimmerWorld recommends 5–6k with oil analysis; iFixit notes 7.5–10k as common."}}, "variants": {"question": "Which oil?", "hint": "BMW specifies 10W-60 for every S54. The debate is only about alternatives.", "options": [{"id": "bmw", "label": "BMW / Castrol 10W-60", "when": "Factory spec for all S54s"}, {"id": "redline", "label": "Red Line 10W-60 or 15W-50", "when": "BimmerWorld''s preference, especially for track use"}, {"id": "other", "label": "Another 10W-60", "when": "Any 10W-60 that meets the BMW M spec"}]}, "should": {"yesIf": ["The service indicator is due", "It''s been 5,000–7,500 miles", "You''re about to go on track"], "codes": [], "notes": [], "confidence": {"level": "high", "n": 2, "note": "BMW oil bulletin; BimmerWorld."}}, "parts": [{"name": "Oil filter kit (Mahle OX 187)", "pn": "11427833769", "price": "$15", "tier": "oem", "note": "Filter, two cap O-rings, cap bolt washer, drain plug seal"}, {"name": "BMW 10W-60 engine oil", "pn": "83212365944", "price": "~6 L", "tier": "oe", "only": ["bmw"]}, {"name": "Red Line 10W-60 or 15W-50", "price": "~6 qt", "tier": "aftermarket", "only": ["redline"]}, {"name": "10W-60 engine oil", "price": "~6 L", "only": ["other"]}], "aftermarket": [], "tools": [{"name": "6 mm hex socket", "note": "Drain plug"}, {"name": "13 mm socket", "note": "Filter housing cap bolt"}, {"name": "Torque wrench"}, {"name": "Drain pan, funnel, gloves"}], "before": ["Warm the engine, then let it sit 10 minutes so it''s not scalding.", "Car level on stands, or use the front centre jack point."], "steps": [{"title": "Loosen the filter cap", "blocks": [{"t": "text", "b": "Remove the oil filler cap. Loosen the 13 mm bolt in the top of the filter housing so the oil in the housing drains down."}]}, {"title": "Drain the oil", "blocks": [{"t": "text", "b": "Underneath, pop off the small round cover in the aluminium underpanel near the front centre jack point. Loosen the drain plug with a 6 mm hex, then remove it and let it drain."}, {"t": "torque", "label": "Drain plug (new sealing ring)", "nm": 25, "c": {"level": "medium", "n": 1, "note": "iFixit E46 M3 oil change guide (owner-contributed, from EuroAddiction)."}, "alt": [24]}, {"t": "note", "b": "iFixit gives 18 ft-lb, which is about 24–25 Nm."}]}, {"title": "Replace the filter and O-rings", "blocks": [{"t": "text", "b": "Lift out the cap and element. Fit the new element, the big O-ring on the cap, the new washer under the bolt head, and the small O-ring at the bolt tip. That small one is easy to forget and causes a slow leak."}, {"t": "torque", "label": "Filter housing cap bolt", "nm": 33, "c": {"level": "medium", "n": 1, "note": "iFixit E46 M3 oil change guide (owner-contributed, from EuroAddiction)."}, "note": "24 ft-lb"}], "caution": true}, {"title": "Fill and check", "blocks": [{"t": "text", "b": "Pour in about 5.75 L, start the engine for 30 seconds, stop, wait a few minutes and check the dipstick. Top up to the mark."}, {"t": "note", "b": "Don''t overfill. The S54''s level is checked with the dipstick, warm and level."}]}], "alsoReplace": [], "check": {"tab": "Read the oil", "title": "What the old oil tells you", "illId": "e46-oil-hero", "illCap": "Filter on top, drain plug underneath.", "rows": [{"see": "Dark but clean, no glitter", "means": "Normal.", "do": "Change on schedule."}, {"see": "Fine metallic sparkle in the drain pan", "means": "Could be bearing material.", "do": "Send an oil sample and plan the rod bearing job."}, {"see": "Milky or coffee-coloured oil", "means": "Coolant in the oil.", "do": "Don''t drive it. Pressure-test the cooling system."}], "c": {"level": "community", "n": 2, "note": "Owner practice; used-oil analysis labs."}}, "aftercare": ["Re-check the level after a short drive.", "Reset the service indicator.", "Consider a used-oil analysis every other change."], "disagreements": [{"topic": "10W-60 or 15W-50", "pos": "BMW specifies 10W-60. BimmerWorld prefers Red Line and notes the newer BMW 10W-60 formula is weaker at high temperature.", "call": "10W-60 from a reputable brand; Red Line if you track it."}, {"topic": "Interval", "pos": "The dash indicator allows long intervals. Specialists say 5,000–7,500 miles.", "call": "5,000–7,500 miles. It''s cheap compared with bearings."}], "sources": ["BMW SI B11 01 15 engine oil quick reference (10W-60 for all S54)", "BMW ST041 M3 technical training", "iFixit: 2001–2006 BMW M3 oil & filter change", "BimmerWorld S54 oil change package", "Turner Motorsport Mahle OX 187 filter kit"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-plugs-coils', '{"id": "e46-plugs-coils", "title": "Spark plugs & ignition coils", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Same plugs and coils for the S54 Z3 M and Z4 M", "category": "Engine", "kind": "repair", "heroId": "e46-plugs-hero", "heroCap": "Six pencil coils press into the plug wells on top of the valve cover. No bolts hold them: they pull straight up.", "glance": {"timeFirst": "1–1.5 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$60–450", "risk": "Cross-threading a plug in the aluminium head · gapping a non-adjustable plug", "why": "Fresh plugs keep the S54 crisp to 8,000 rpm. A misfire on this engine is almost always a coil or a plug, and both are a short job.", "note": "Coils fail one at a time. Swap the suspect coil to another cylinder and see if the misfire follows it."}, "lifespan": {"headline": ["Plugs: every 30,000 miles · Coils: when they fail"], "factors": ["Oil in the plug wells", "Forced induction"], "inspect": ["Look for oil in the wells: it means the plug-well gaskets are leaking"], "confidence": {"level": "medium", "n": 2, "note": "Common service practice; coil life varies."}}, "variants": {"question": "Is the engine stock or supercharged?", "options": [{"id": "stock", "label": "Stock", "when": "NGK DCPR8EKP, the BMW-listed plug"}, {"id": "fi", "label": "Supercharged", "when": "Use the colder plug your kit specifies"}]}, "should": {"yesIf": ["30k miles since the last set", "A misfire code", "You''re doing a valve adjustment"], "codes": ["P0300", "P0301", "P0302", "P0303", "P0304", "P0305", "P0306"], "notes": ["P0301–P0306 tell you which cylinder: start there."], "confidence": {"level": "high", "n": 1, "note": "OBD-II standard codes."}}, "parts": [{"name": "NGK DCPR8EKP spark plugs ×6", "pn": "DCPR8EKP", "price": "$110 set", "tier": "oem", "note": "Non-adjustable: don''t gap them", "only": ["stock"]}, {"name": "Colder plug per your supercharger kit ×6", "price": "$80–130", "tier": "aftermarket", "only": ["fi"]}, {"name": "Ignition coil (Eldor/Bosch OEM)", "price": "$45–70 ea", "tier": "oem", "note": "Replace only the failed ones, or all six if they''re original"}], "aftermarket": [{"name": "NGK DCPR8EIX iridium", "note": "Listed for the S54; longer life", "price": "$15 ea"}], "tools": [{"name": "16 mm spark plug socket with swivel or magnet"}, {"name": "Long extension"}, {"name": "Torque wrench 20–30 Nm"}], "before": ["Engine cold: the head is aluminium.", "Blow out the plug wells before removing plugs."], "steps": [{"title": "Remove the engine cover and coils", "blocks": [{"t": "text", "b": "Remove the engine cover. Unplug each coil by lifting its connector lock, then wiggle the coil hard side to side and pull straight up. Keep them in order if you''re diagnosing."}]}, {"title": "Remove the plugs", "blocks": [{"t": "text", "b": "Blow out each well, then remove the plugs with the 16 mm socket. Look at each one as it comes out."}]}, {"title": "Fit the new plugs", "blocks": [{"t": "text", "b": "Start each plug by hand, using the socket and extension without the ratchet, for several turns. If it binds, stop and back out."}, {"t": "torque", "label": "Spark plugs (M12, dry threads)", "nm": 23, "c": {"level": "high", "n": 1, "note": "BMW spark plug application chart: S54 uses NGK DCPR8EKP, non-adjustable, M12 thread."}}, {"t": "warn", "b": "The DCPR8EKP is non-adjustable. Don''t gap it or use anti-seize unless the plug maker says to."}], "caution": true}, {"title": "Refit the coils", "blocks": [{"t": "text", "b": "Line up each coil''s tab with its slot in the valve cover and press it down until it snaps. Reconnect each connector and push its lock down."}]}], "alsoReplace": [{"name": "Plug-well gaskets", "why": "If you found oil in the wells, they''re leaking and will kill the new coils. They come off with the valve cover."}], "check": {"tab": "Read the plugs", "title": "What the old plugs tell you", "illId": "e46-plugs-hero", "illCap": "Pencil coils press straight into the wells.", "rows": [{"see": "Light tan, even on all six", "means": "Healthy.", "do": "Nothing."}, {"see": "One plug black and sooty", "means": "That cylinder ran rich or misfired.", "do": "Swap its coil to another cylinder and watch the code."}, {"see": "Oil on the threads or in the well", "means": "Leaking plug-well gasket.", "do": "Replace the valve cover gaskets."}], "c": {"level": "community", "n": 2, "note": "Standard plug reading."}}, "aftercare": ["Clear any misfire codes and recheck after a drive."], "disagreements": [{"topic": "Iridium or the OEM platinum plug", "pos": "BMW lists the DCPR8EKP. NGK also lists the DCPR8EIX iridium for the S54.", "call": "Either; stick to NGK heat range 8 on a stock engine."}], "sources": ["BMW spark plug application chart (SIB B12 01 99)", "Turner Motorsport NGK listings for the E46 M3", "Beisan Systems S54 procedure (coil removal)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-position-sensors', '{"id": "e46-position-sensors", "title": "Crank & cam position sensors", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Cam sensor locations are S54-specific; non-M E46s have the intake sensor at the front", "category": "Engine", "kind": "repair", "heroId": "e46-pos-hero", "heroCap": "Both S54 cam sensors sit at the rear of the head: exhaust on the right, intake on the left near the firewall. The crank sensor is low on the left rear of the block, under the intake.", "glance": {"timeFirst": "1–3 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$40–250", "risk": "Stripping the small bolt · losing the sensor O-ring in the head", "why": "A failing crank sensor causes hard starts, stalling and misfires; a cam sensor sets position codes and dulls the engine. They''re cheap, but on the M3 two of the three are hidden.", "note": "Most E46 how-tos show the non-M layout with the intake cam sensor at the front. On the M3 it''s at the back of the head."}, "lifespan": {"headline": ["Fail on condition, often after heat soak"], "factors": ["Heat", "Oil leaks onto connectors"], "confidence": {"level": "community", "n": 2, "note": "Owner reports."}}, "variants": {"question": "Which sensor?", "options": [{"id": "exh", "label": "Exhaust cam sensor", "when": "Easiest: rear right of the head"}, {"id": "int", "label": "Intake cam sensor", "when": "Rear left, behind the intake manifold · P0340"}, {"id": "crank", "label": "Crank sensor", "when": "Hard start, stalling, misfire; rear left of the block"}]}, "should": {"yesIf": ["A code names the sensor", "Hot-start or stalling problems with a crank sensor code"], "codes": ["P0335", "P0340", "P0365"], "notes": ["Check the connector and wiring for oil and corrosion before buying a sensor."], "confidence": {"level": "medium", "n": 2, "note": "OBD-II code definitions; mforum and e46fanatics owner write-ups."}}, "parts": [{"name": "Exhaust camshaft position sensor", "pn": "13627796054", "price": "$60–150", "tier": "oe", "only": ["exh"]}, {"name": "Intake camshaft position sensor", "pn": "12147539171", "price": "$60–150", "tier": "oe", "only": ["int"]}, {"name": "Crankshaft position sensor", "pn": "12141709616 (family)", "price": "$40–120", "tier": "oem", "note": "Confirm by VIN; the Valeo equivalent lists the S54", "only": ["crank"]}, {"name": "Sensor O-ring", "price": "$2", "tier": "oe"}, {"name": "New sensor bolt", "price": "$2", "tier": "oe", "note": "BMW suggests new fasteners because of the factory threadlocker"}], "aftermarket": [], "tools": [{"name": "5 mm hex socket or key, with extensions and a flex joint"}, {"name": "Medium threadlocker"}, {"name": "Flashlight, mirror"}], "before": ["Engine cool.", "Disconnect the battery."], "steps": [{"title": "Exhaust cam sensor: open up", "blocks": [{"t": "text", "b": "Remove the engine cover so the harness can move. The sensor is at the right rear of the head."}], "only": ["exh"]}, {"title": "Exhaust cam sensor: swap it", "blocks": [{"t": "text", "b": "Unplug it, remove the single bolt, pull the sensor and its O-ring. Fit the new sensor with a new O-ring and bolt."}], "only": ["exh"]}, {"title": "Intake cam sensor: get access", "blocks": [{"t": "text", "b": "It''s at the rear of the head on the intake side, near the firewall. Pelican''s S54 procedure removes the intake manifold and moves the injector harness aside; the sensor''s connector is along the fuel rail under the black cover around cylinders 3–4."}, {"t": "note", "b": "Owners with small hands and thin hex keys have done it with the manifold in place. Removing it is the reliable route; see the throttle actuator guide for plenum removal."}], "only": ["int"], "timeSink": true}, {"title": "Intake cam sensor: swap it", "blocks": [{"t": "text", "b": "Remove the 5 mm hex bolt, unhook the harness clips, and pull the sensor. Make sure its green O-ring comes out too; fish it out if it stays in the head. Fit the new one with a new O-ring and a little threadlocker on the bolt."}], "only": ["int"]}, {"title": "Crank sensor: find it", "blocks": [{"t": "text", "b": "It''s on the left rear of the block under the intake, with a 3-pin black connector. From the top, remove the intake elbow and filter housing and reach down; owners also do it from underneath."}], "only": ["crank"]}, {"title": "Crank sensor: swap it", "blocks": [{"t": "text", "b": "Remove the 5 mm hex bolt (it''s threadlocked), pull the sensor out firmly, fit the new one with its O-ring, and reconnect it underneath."}, {"t": "warn", "b": "Don''t drop the bolt: it falls straight onto the starter area."}], "only": ["crank"], "caution": true}, {"title": "Clear codes and test", "blocks": [{"t": "text", "b": "Reconnect the battery, clear codes and start it. A cam sensor code should not return after several drives."}]}], "alsoReplace": [{"name": "VANOS solenoid check", "why": "Position codes can also come from the VANOS. If a new cam sensor doesn''t clear it, see the VANOS guide."}], "check": {"tab": "Narrow it down", "title": "Sensor or something else?", "illId": "e46-pos-hero", "illCap": "Rear of the head and block.", "rows": [{"see": "Circuit code (open/short)", "means": "Sensor or its wiring.", "do": "Check the connector, then replace the sensor."}, {"see": "Position or correlation code", "means": "Could be the VANOS.", "do": "Rule out the VANOS before buying sensors."}, {"see": "Stalls hot, restarts cold", "means": "Classic crank sensor.", "do": "Replace the crank sensor."}], "c": {"level": "community", "n": 2, "note": "Owner diagnosis; Beisan VANOS notes."}}, "aftercare": ["Watch for codes over the next few drives."], "disagreements": [{"topic": "Torque", "pos": "We found no published S54 figure for these small sensor bolts; Pelican notes BMW''s advice to replace them because of factory threadlocker.", "call": "New bolt, medium threadlocker, snug by hand with a short wrench."}], "sources": ["ECS Tuning S54 camshaft position sensor listings", "Pelican Parts: S54 camshaft sensor testing (Z4 M)", "mforum: E46 M3 P0340 intake cam sensor procedure", "e46fanatics: E46 M3 S54 intake cam sensor DIY", "e46fanatics: E46 M3 crankshaft position sensor DIY"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-rod-bearings', '{"id": "e46-rod-bearings", "title": "Rod bearing service", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Same bearings and bolt rules apply to the S54 in the 2001–2002 Z3 M and 2006–2008 Z4 M, but the front-end teardown differs", "category": "Engine", "kind": "repair", "heroId": "e46-rod-hero", "heroCap": "The S54 is done with the engine in the car: support it from above, drop the front subframe with the rack and arms still attached, then the oil pan comes off and each rod cap is reached from below.", "glance": {"timeFirst": "12–20 hr", "timeRepeat": "8–10 hr", "difficulty": 5, "cost": "$250–900", "risk": "Mixing up rod caps · wrong bolt procedure for your build date · debris on the shells", "why": "Worn rod bearings are the S54''s best-known way to destroy itself. Replacing the shells before they fail costs a weekend and a few hundred dollars; a spun bearing usually costs the crank or the engine.", "note": "Plan it as a two-day job the first time, and line up engine mounts and an oil pan gasket so the subframe only comes down once."}, "lifespan": {"headline": ["Treat it as a ~100,000-mile service"], "earliest": "Even upgraded shells aren''t lifetime parts: if the last service was at 50k, the next is due around 150k.", "detail": "Early cars had rod bearing clearances BMW later revised, and the factory''s long oil-change interval didn''t help. Hard track use and overheating shorten it.", "factors": ["Track days", "Long oil intervals", "Overheating", "High-rpm cold running"], "inspect": ["Ask for receipts on any used M3: date, mileage, which shells"], "confidence": {"level": "medium", "n": 3, "note": "ECS and Turner put it at about 100k miles; there''s no BMW interval, so treat it as a planned service rather than a spec."}}, "variants": {"questions": [{"question": "Which rod bolts does your engine have?", "hint": "BMW''s bulletin splits at 12/12/2002 production. Cars built before it have M11 bolts with a 12-point head; later cars have M10 stretch bolts with a Torx head and a longer thread. Your build date is on the door-jamb sticker; confirm on the first cap you remove.", "options": [{"id": "m11", "label": "M11, built before 12/12/2002", "when": "12-point head · reusable, back in the same hole"}, {"id": "m10", "label": "M10, built from 12/12/2002", "when": "Torx head · stretch bolt, replace all 12"}]}, {"question": "Which bearings?", "options": [{"id": "oe", "label": "Genuine BMW shells", "when": "Red and blue factory shells, standard size"}, {"id": "wpc", "label": "WPC-treated BMW shells", "when": "Same shells, surface-treated (Turner, BimmerWorld)", "brand": true}, {"id": "be", "label": "BE Bearings", "when": "Revised clearance, sold with BE-spec ARP bolts", "brand": true}]}, {"question": "Which bolts are you installing?", "options": [{"id": "stock", "label": "Factory bolts", "when": "Reused M11s, or new M10s"}, {"id": "arp", "label": "ARP rod bolts", "when": "Reusable; torque to the sheet in your kit"}]}]}, "should": {"yesIf": ["The car is near or past 100k miles with no receipt for bearings", "You''re about to start tracking it", "You''re doing an oil pan gasket, engine mounts or front suspension anyway", "A used oil analysis shows rising copper or lead"], "codes": [], "notes": ["A knock that grows with rpm, or low oil pressure warm, means stop driving and inspect. New shells won''t save a scored crank."], "confidence": {"level": "medium", "n": 4, "note": "ECS, Turner, BimmerWorld and the buyer guides all treat it as preventative."}}, "parts": [{"name": "Rod bearing shell, red, standard", "pn": "11247835439", "price": "$15 ea ×6", "tier": "oe", "only": ["oe", "wpc"]}, {"name": "Rod bearing shell, blue, standard", "pn": "11247835440", "price": "$15 ea ×6", "tier": "oe", "only": ["oe", "wpc"]}, {"name": "BE Bearings S54 rod bearing set", "price": "$450–600", "tier": "aftermarket", "note": "Check the set includes or specifies its bolts", "only": ["be"]}, {"name": "M10 × 1.25 connecting rod bolts ×12", "pn": "11247834310", "price": "$3–5 ea", "tier": "oe", "note": "New every time; never reuse", "only": ["m10+stock"]}, {"name": "ARP rod bolt set ×12 (match M10 or M11)", "pn": "ARP 201-6103 (M11)", "price": "$170–250", "tier": "aftermarket", "note": "Order the set for your bolt size", "only": ["arp"]}, {"name": "Oil pan gasket", "pn": "11131437237", "price": "$35", "tier": "oe"}, {"name": "Oil pan cover gasket", "pn": "11137834886", "price": "$20", "tier": "oe"}, {"name": "Oil suction pipe O-ring", "pn": "11411401769", "price": "$4", "tier": "oe"}, {"name": "Dipstick tube O-ring", "pn": "11431707164", "price": "$4", "tier": "oe"}, {"name": "Power steering crush washers (2 pairs)", "pn": "32411093596 / 32411093597", "price": "$8", "tier": "oe", "note": "Kit routes unbolt the PS lines at the pump"}, {"name": "Assembly lube", "price": "$12"}, {"name": "Oil filter (Mahle OX 187)", "pn": "11427833769", "price": "$15", "tier": "oem"}, {"name": "10W-60 engine oil", "price": "~7 L", "tier": "oe", "note": "More than a normal change: the pan and pickup are empty"}], "aftermarket": [{"name": "Turner WPC rod bearing kit", "note": "WPC-treated shells, early or late kit, ARP option", "price": "$600–900", "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E46-M3-Parts/c-580-bmw-bearings/m-1241-packaged-by-turner"}]}, {"name": "BimmerWorld rod bearing overhaul kits", "note": "OE or WPC shells plus pan gaskets, O-rings and PS washers; early and late versions", "price": "$300–700", "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Engine/Engine-Maintenance/Rod-Bearing-Overhaul-Kit-Basic-OEM-E46-M3-2004.html"}]}, {"name": "BE Bearings S54 kit", "note": "Bearings designed around a revised clearance, paired with BE-spec ARP bolts", "price": "$500–750"}], "tools": [{"name": "Engine support bar", "note": "Spans the strut towers or fender rails and holds the engine while the subframe is down"}, {"name": "Floor jack + transmission or subframe cradle"}, {"name": "Torque wrench 5–60 Nm + angle gauge", "note": "The angle steps are not optional"}, {"name": "12 mm 12-point socket", "note": "M11 bolts", "only": ["m11"]}, {"name": "Torx socket for M10 bolts", "only": ["m10"]}, {"name": "Plastigauge (optional)", "note": "To check clearance if you want proof"}, {"name": "Lint-free towels, brake cleaner, nitrile gloves"}], "before": ["Drain the oil warm, then let the car cool fully.", "Mark every cap with its cylinder and its direction before it comes off. The S54''s caps are fracture-split and only fit their own rod one way.", "Work clean: one grain of grit under a shell does more harm than old bearings.", "Have a helper for the angle-torque steps."], "chapters": [{"id": "prep", "title": "Prep & support", "blurb": "Car up, engine held from above."}, {"id": "down", "title": "Subframe down", "blurb": "The front subframe drops with the rack and arms attached."}, {"id": "pan", "title": "Oil pan off", "blurb": "Pan, cover and pickup."}, {"id": "bear", "title": "Bearings", "blurb": "One rod at a time."}, {"id": "close", "title": "Close up", "blurb": "Pan, subframe, oil, first start."}], "steps": [{"title": "Lift the car and drain the oil", "blocks": [{"t": "text", "b": "Get the car level and high on four stands. Drain the oil and remove the filter element. Remove the under-trays and the front underbody plate."}, {"t": "note", "b": "Disconnect the battery before you start unplugging things around the subframe."}], "chapter": "prep"}, {"title": "Support the engine from above", "blocks": [{"t": "text", "b": "Set the support bar across the car and hook it to the engine lifting eye. Take up just enough load that the mounts unload; you''ll undo the mount nuts from below next."}, {"t": "warn", "b": "Never have the engine held only by a jack under the pan. The pan is coming off."}], "chapter": "prep", "caution": true}, {"title": "Free the subframe", "blocks": [{"t": "text", "b": "Disconnect the steering shaft at the rack, the sway bar links, and anything clipped to the subframe. Unbolt the power steering lines at the pump if your route needs it (new crush washers go back on). Remove the engine mount nuts from below."}, {"t": "note", "b": "BimmerWorld and Turner both prefer dropping the subframe with the steering rack and control arms still attached. It sounds like more, but it''s the fewest disconnections."}], "chapter": "down"}, {"title": "Lower the subframe", "blocks": [{"t": "text", "b": "Support the subframe on a jack, remove its mounting bolts, and lower it far enough to clear the oil pan. Keep the brake lines and ABS wiring slack."}, {"t": "note", "b": "We couldn''t verify an E46 M3 figure for the subframe bolts. Use your Bentley or TIS value; the 108 Nm quoted in S65 write-ups is for the E9x M3, not this car."}], "chapter": "down", "caution": true, "timeSink": true}, {"title": "Remove the oil pan, cover and pickup", "blocks": [{"t": "text", "b": "Remove the pan bolts working from the outside in, then the pan. Remove the oil pickup with its O-ring and anything else blocking the rod caps."}, {"t": "torque", "label": "Oil pan bolts, M6 (8.8 grade)", "nm": 10, "c": {"level": "medium", "n": 2, "note": "TIS values posted by owners; 10.9-grade M6 bolts are 12 Nm."}}, {"t": "note", "b": "Clean every sealing face to bare metal. Put sealant only at the joints where the timing cover and the rear main seal carrier meet the block, not around the whole gasket; extra RTV ends up in the pickup screen."}], "chapter": "pan"}, {"title": "Bring rod 1 to the bottom and remove its cap", "blocks": [{"t": "text", "b": "Turn the crank by hand until the rod you''re working on is at the bottom. Loosen both bolts, remove the cap and its shell, then push the rod up gently to free the upper shell."}, {"t": "note", "b": "Lay the old shells out in order on a towel. They''re your diagnosis: see the check tab."}, {"t": "warn", "b": "Don''t let the rod drop onto the crank, and don''t scratch the journal with a tool."}], "chapter": "bear"}, {"title": "Inspect the journal", "blocks": [{"t": "text", "b": "Wipe the journal and look at it under a light. A smooth, even finish is fine. Grooves you can catch with a fingernail mean the crank needs a machinist before new shells go in."}, {"t": "ill", "id": "e46-rod-shells", "cap": "What the old shells tell you: grey even wear is normal; copper showing in a band means it was due; copper across the shell or a scored journal means stop and get the crank checked."}], "chapter": "bear"}, {"title": "Fit the new shells", "blocks": [{"t": "text", "b": "Clean the rod and cap bores dry. Seat the new shells with their tabs in the notches; the backs go in dry and clean. Put assembly lube on the bearing faces only."}, {"t": "note", "b": "Keep each colour in the position the kit instructions show, and keep each cap with its own rod."}, {"t": "text", "b": "Pull the rod down onto the journal, fit the cap the same way round it came off, and start both bolts by hand."}], "chapter": "bear"}, {"title": "Torque the bolts: M11 (reused)", "blocks": [{"t": "text", "b": "Reuse each M11 bolt in the hole it came out of. Tighten both bolts on the rod in stages, then angle-turn both in one smooth stroke."}, {"t": "torque", "label": "M11 rod bolts, settling", "nm": 5, "c": {"level": "high", "n": 3, "note": "BMW service bulletin for the S54 rod bearing action, repeated by the ECS install sheet and NAM3Forum owners."}}, {"t": "torque", "label": "M11 rod bolts, initial", "nm": 30, "c": {"level": "high", "n": 3, "note": "BMW service bulletin for the S54 rod bearing action, repeated by the ECS install sheet and NAM3Forum owners."}}, {"t": "note", "b": "Then angle both bolts 70° in one stroke. That''s it for M11: once."}], "chapter": "bear", "caution": true, "only": ["m11+stock"]}, {"title": "Torque the bolts: M10 (new)", "blocks": [{"t": "text", "b": "Fit new M10 bolts. BMW has these stretch bolts tightened through the full sequence at least three times to reach full strength, backing off about one turn in between."}, {"t": "torque", "label": "M10 rod bolts, settling", "nm": 5, "c": {"level": "high", "n": 3, "note": "BMW service bulletin for the S54 rod bearing action, repeated by the ECS install sheet and NAM3Forum owners."}}, {"t": "torque", "label": "M10 rod bolts, initial", "nm": 30, "c": {"level": "high", "n": 3, "note": "BMW service bulletin for the S54 rod bearing action, repeated by the ECS install sheet and NAM3Forum owners."}}, {"t": "note", "b": "Then angle both bolts 105° in one stroke. Back both off about a turn, and repeat 5 Nm → 30 Nm → 105°. Do the full sequence three times in total. Owners following TIS report three to five."}, {"t": "warn", "b": "Never reuse an M10 bolt, and don''t mix M10 bolts into an M11 rod. The rods themselves are different part numbers."}], "chapter": "bear", "caution": true, "only": ["m10+stock"]}, {"title": "Torque the bolts: ARP", "blocks": [{"t": "text", "b": "Lubricate with the ARP lube supplied and follow the sheet that came with your set. Measure bolt stretch if you have a stretch gauge; that is what ARP actually specifies."}, {"t": "torque", "label": "ARP rod bolts (sheet value)", "nm": 68, "c": {"level": "varies", "n": 3, "note": "ECS''s sheet says 50 ft-lb; UK owners measured 66–68 ft-lb from BMW''s M10 procedure and warn ARP''s M10 sheet is the S50 figure. Use your kit''s sheet or stretch."}, "note": "check your sheet", "alt": [90]}, {"t": "warn", "b": "An over-torqued ARP bolt pulls the big end out of round. If your sheet and this guide disagree, the sheet for your exact kit wins."}], "chapter": "bear", "caution": true, "only": ["arp"]}, {"title": "Repeat for rods 2–6", "blocks": [{"t": "text", "b": "Turn the crank to bring each rod to the bottom in turn and repeat. After each rod, spin the crank by hand: it should turn smoothly with no tight spot."}], "chapter": "bear", "timeSink": true}, {"title": "Refit the pickup, pan and subframe", "blocks": [{"t": "text", "b": "New O-ring on the pickup, new pan and cover gaskets, sealant only at the corner joints. Torque the pan bolts in a cross pattern. Raise the subframe, refit everything in reverse, and torque the engine mounts."}, {"t": "torque", "label": "Engine mount nuts", "nm": 49, "c": {"level": "single", "n": 1, "note": "TIS list posted on z4-forum for the S54 cars; confirm against your Bentley."}}], "chapter": "close"}, {"title": "Fill, prime and first start", "blocks": [{"t": "text", "b": "Fit a new filter and fill with about 7 L of 10W-60, then check the dipstick. Crank the engine with the fuel pump fuse pulled for 10–15 seconds to build oil pressure before it fires, then refit the fuse and start it."}, {"t": "note", "b": "Rod bearings don''t need a break-in; just let the oil come up to temperature before using high rpm."}], "chapter": "close"}], "alsoReplace": [{"name": "Engine mounts", "why": "The mount nuts are already off and the subframe is down. Worn mounts let the engine move on a lift-off, which the new bearings don''t need."}, {"name": "Front control arm bushings and ball joints", "why": "The arms are attached to the subframe you just dropped; refreshing them now saves a second teardown."}, {"name": "Oil pump nut check", "why": "Owners commonly check the oil pump drive nut while the pan is off. Follow your Bentley before touching it."}], "check": {"tab": "Read the old shells", "title": "What the old shells tell you", "illId": "e46-rod-shells", "illCap": "Lay them out in cylinder order: the pattern matters more than any single shell.", "rows": [{"see": "Even grey finish, no copper", "means": "Normal wear. You did it in time.", "do": "Fit new shells and carry on."}, {"see": "Copper showing in a band on several shells", "means": "The overlay is worn through. It was due.", "do": "New shells; check journals carefully and send an oil sample after 1,000 miles."}, {"see": "Copper across a whole shell, flaking, or a scored journal", "means": "The bearing was failing and the crank may be damaged.", "do": "Stop. Have the crank measured before reassembly."}], "c": {"level": "community", "n": 3, "note": "Owner write-ups and shop photo sets; there''s no BMW wear chart for this."}}, "aftercare": ["Recheck the oil level after the first drive.", "Change the oil and send a used-oil analysis after about 1,000 miles.", "Keep the receipt with the build date, bolt type and shell brand. Buyers ask for it."], "disagreements": [{"topic": "When the bolt change happened", "pos": "BMW''s bulletin says 12/12/2002 production. BimmerWorld''s kits are split at 2/2003 and 4/2003.", "call": "Go by the bolt head you find, not the calendar."}, {"topic": "ARP torque", "pos": "ECS''s install sheet gives 50 ft-lb. UK owners say ARP''s M10 sheet is the S50 figure and measured 66–68 ft-lb from BMW''s own procedure.", "call": "Use the sheet for your exact ARP kit, ideally with a stretch gauge."}, {"topic": "How many times to torque the M10s", "pos": "The bulletin says at least three. Owners quoting TIS say three to five.", "call": "Three full sequences."}, {"topic": "OE, WPC or BE", "pos": "BimmerWorld prefers WPC-treated shells. BE sells a revised clearance. Many owners run Genuine BMW shells and change them on schedule.", "call": "Any of the three is fine if you also keep the oil changes short."}], "sources": ["BMW Service Information: E46 M3 S54 connecting rod bearings replacement (via siwilson.com)", "ECS Tuning S54 WPC rod bearing kit installation sheet", "BimmerWorld rod bearing overhaul kits (early and late)", "Turner Motorsport rod bearing kits", "NAM3Forum E46 rod bearing DIY threads", "e46fanatics S54 rod bolt torque threads", "m3cutters UK ARP bolt discussion", "ECS Tuning: Most common BMW E46 M3 problems"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-throttle-actuator', '{"id": "e46-throttle-actuator", "title": "Throttle actuator, linkage & position sensors", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Same actuator (13627840537) as the S54 Z3 M and Z4 M", "category": "Engine", "kind": "repair", "heroId": "e46-th-hero", "heroCap": "One electric actuator drives all six throttle bodies through a pull rod and a shaft. It sits under the intake plenum with throttle position sensor #2; sensor #1 is at the front of the throttle bodies.", "glance": {"timeFirst": "2–4 hr", "timeRepeat": "1.5 hr", "difficulty": 3, "cost": "$35–900", "risk": "Breaking the small vent hose under the plenum · skipping the adaptation reset", "why": "EML light plus limp mode is the S54''s classic throttle failure. It''s often a worn plastic pull rod or a position sensor, which are cheap, before it''s the actuator itself.", "note": "BMW has discontinued the actuator, so a replacement is usually a rebuilt or OEM Pierburg unit."}, "lifespan": {"headline": ["Pull rod and sensors wear with age; actuators fail from heat"], "factors": ["Heat", "Worn linkage"], "confidence": {"level": "medium", "n": 2, "note": "BimmerWorld; Go-Parts S54 guide."}}, "variants": {"question": "What are you replacing?", "options": [{"id": "rod", "label": "Pull rod & linkage", "when": "Sloppy throttle, link popping off"}, {"id": "tps", "label": "Position sensors", "when": "Hesitation, TPS plausibility codes"}, {"id": "act", "label": "Throttle actuator", "when": "Limp mode that persists after rod and sensors"}]}, "should": {"yesIf": ["EML and DSC lights with limp mode", "Throttle feels jerky or hangs", "P1637 or throttle plausibility codes"], "codes": ["P1637"], "notes": ["Check the cheap things first: front TPS, pull rod, and whether a throttle-body boot clamp is hitting the throttle lever."], "confidence": {"level": "medium", "n": 3, "note": "MotoIQ, PistonHeads, Go-Parts owner reports."}}, "parts": [{"name": "Throttle actuator pull rod", "pn": "13547839073", "price": "$35", "tier": "oe", "note": "Plastic ball sockets wear and pop off", "only": ["rod"]}, {"name": "Throttle position sensor", "pn": "13637840383", "price": "$80–120 ea", "tier": "oe", "only": ["tps"]}, {"name": "Throttle actuator (OEM Pierburg)", "pn": "13627840537", "price": "$600–900", "tier": "oem", "only": ["act"]}, {"name": "Throttle body boot clamps ×6", "price": "$20", "tier": "oe", "note": "Single-use: new ones every time"}], "aftermarket": [{"name": "Silicone throttle body boot set", "note": "Replaces cracked rubber boots while the plenum is off", "price": "$110"}], "tools": [{"name": "Clamp pliers / needle-nose and locking pliers", "note": "For the throttle body clamps"}, {"name": "10 mm socket, Torx set"}, {"name": "Scan tool that can reset throttle adaptations"}], "before": ["Engine cool.", "Remove the strut brace (4 nuts) and the cabin filter housing (4 Torx)."], "steps": [{"title": "Remove the intake elbow and airbox", "blocks": [{"t": "text", "b": "Loosen the clamps at the air mass sensor housing, release the airbox clips, and remove the airbox and elbow. Remove the crankcase vent hose and the dipstick nut."}]}, {"title": "Remove the plenum", "blocks": [{"t": "text", "b": "Remove all six throttle-body clamps, the two 10 mm nuts under the plenum, and unclip the large vent hose underneath. Tilt the plenum up and out."}, {"t": "warn", "b": "The small vent hose underneath is the part everyone breaks. Pull the plenum halfway out and reach in to unclip it before lifting it clear."}], "caution": true}, {"title": "Inspect the linkage", "blocks": [{"t": "text", "b": "Check the pull rod''s ball sockets for play, and that nothing rubs the throttle lever. Replace the rod if it''s sloppy."}], "only": ["rod", "act"]}, {"title": "Replace the position sensor", "blocks": [{"t": "text", "b": "Sensor #2 is on the actuator, reachable now; #1 is at the front of the throttle bodies. Unplug, unscrew and replace."}], "only": ["tps"]}, {"title": "Replace the actuator", "blocks": [{"t": "text", "b": "Unplug the actuator, disconnect the pull rod, unbolt it and fit the new unit. Reconnect the rod."}], "only": ["act"]}, {"title": "Refit and reset adaptations", "blocks": [{"t": "text", "b": "Refit the plenum with new clamps, the vent hoses, airbox and elbow. Clear codes and reset throttle adaptations with a scan tool, then let it idle."}, {"t": "note", "b": "Owners also report the pedal method (pedal to the floor several times with ignition on) for older E46s; a scan tool is more reliable."}]}], "alsoReplace": [{"name": "Idle control valve cleaning", "why": "It''s exposed with the plenum off and a common rough-idle fix."}, {"name": "Throttle body boots", "why": "Cracked boots cause vacuum leaks."}], "check": {"tab": "Narrow it down", "title": "Which part is it?", "illId": "e46-th-hero", "illCap": "Actuator and sensor #2 under the plenum.", "rows": [{"see": "Pull rod pops off or has play", "means": "Worn ball sockets.", "do": "New rod."}, {"see": "Codes point to a TPS", "means": "Sensor failing.", "do": "Replace the front one first, then #2."}, {"see": "Limp mode persists with good rod and sensors", "means": "Actuator.", "do": "Replace it and reset adaptations."}], "c": {"level": "community", "n": 3, "note": "Owner troubleshooting threads."}}, "aftercare": ["Drive gently for a few miles while the DME relearns."], "disagreements": [{"topic": "Replace both sensors?", "pos": "Some replace only the coded sensor; others do both while the plenum is off.", "call": "Do both if the car is high-mileage: the plenum is the hard part."}], "sources": ["BimmerWorld S54 pull rod and Pierburg actuator listings", "Turner Motorsport S54 throttle body parts", "MotoIQ Project E46 M3 part 8: EML light", "The Build Journal E46 M3 throttle body and ICV cleaning DIY", "Pelican Parts S54 throttle actuator replacement", "Go-Parts S54 throttle body guide"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-tuning', '{"id": "e46-tuning", "title": "Engine software: street, race & Alpha-N", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "MSS54 ECU (stock M3); the CSL used MSS54HP", "category": "Engine", "kind": "upgrade", "heroId": "e46-tune-hero", "heroCap": "The usual path: software, then headers, then a CSL airbox with Alpha-N, then cams. Each step needs the software to match the hardware.", "glance": {"timeFirst": "1 hr flash · half-day dyno", "timeRepeat": "30 min", "difficulty": 2, "cost": "$400–1,200", "risk": "A file that doesn''t match your parts · flashing on a weak battery", "why": "Software alone wakes the S54 up at the top: Epic claims 23+ hp between 6,500 and 8,000 rpm. Every hardware step after that needs the tune updated to pay off.", "note": "Off-the-shelf files assume stock cats and sensors. Alpha-N is a custom, per-car dyno tune."}, "lifespan": {"headline": ["Re-tune whenever hardware changes"], "factors": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "variants": {"question": "Which kind of tune?", "options": [{"id": "street", "label": "Off-the-shelf street file", "when": "Epic Performance, ESS, Evolve; keeps cats, EGT and O2 sensors"}, {"id": "race", "label": "Race / catless file", "when": "Track cars with headers; O2/EGT thresholds changed"}, {"id": "alpha", "label": "Custom Alpha-N on a dyno", "when": "Required for CSL boxes, cams or forced induction"}]}, "should": {"yesIf": ["You''ve added or are adding headers or an airbox", "Track car wanting the top end", "Removing the 6,300 rpm dyno limiter for dyno work"], "codes": [], "notes": ["Removing or replacing catalytic converters on a road car is illegal in the US and most other markets, and an Alpha-N or catless tune generally won''t pass emissions readiness checks. These routes are for track cars."], "confidence": {"level": "medium", "n": 2, "note": ""}}, "parts": [{"name": "Epic Motorsports street/race file", "price": "$400–700", "tier": "aftermarket", "note": "Built from your stock file; options include sport-mode memory and custom rev limit", "only": ["street", "race"]}, {"name": "Custom Alpha-N dyno tune", "price": "$1,000–1,200", "tier": "aftermarket", "only": ["alpha"]}, {"name": "Flash cable (DCAN / Evolve-R / ESS E-Flash)", "price": "$50–150", "tier": "aftermarket"}], "aftermarket": [{"name": "Epic Motorsports", "note": "Street, race and Alpha-N; claims 23+ hp 6,500–8,000 rpm", "price": "$400–1,199"}, {"name": "Evolve", "note": "Remote Alpha-N via the Evolve-R cable", "price": "varies"}, {"name": "ESS", "note": "E-Flash software and supercharger maps", "price": "varies"}], "tools": [{"name": "Battery charger (10 A+)", "note": "Keeps voltage steady during the flash"}, {"name": "Laptop with the tuner''s software"}, {"name": "Dyno time (Alpha-N)", "only": ["alpha"]}], "before": ["Save your stock file first.", "Battery on a charger; all accessories off."], "steps": [{"title": "What you get", "blocks": [{"t": "chart", "title": "Software and supporting mods, same car", "unit": "whp", "baseline": "Stock", "bars": [{"label": "Stock", "v": 286, "note": "91 octane"}, {"label": "Catless headers + tune", "v": 315}, {"label": "ARH headers, tuned", "v": 351, "note": "91 octane"}, {"label": "ARH headers, tuned, E30 blend", "v": 355}], "source": "Buildjournal: same 2003 E46 M3, same dyno (European Auto Source, Anaheim), 91 octane, wheel hp.", "c": {"level": "high", "n": 1, "note": "One car, back-to-back on one dyno: the best kind of comparison, but still one car."}}, {"t": "chart", "title": "Maker claim: software alone", "unit": "hp gain", "baseline": null, "bars": [{"label": "Epic street/race file", "v": 23, "note": "claimed ''23+ hp'' at 6,500–8,000 rpm"}], "source": "Epic Motorsports via BimmerWorld; no same-car before/after published.", "c": {"level": "single", "n": 1, "note": "Maker claim."}}, {"t": "note", "b": "Right Foot Down''s rule of thumb: a catless header plus a good 93-octane tune takes a stock ~280 whp car to roughly 320 whp, and 20–25 whp of that comes from the tune alone."}]}, {"title": "Save the stock file", "blocks": [{"t": "text", "b": "Connect the flash cable, read and save the original ECU file somewhere safe. You''ll need it for emissions tests and resale."}], "caution": true}, {"title": "Flash the file", "blocks": [{"t": "text", "b": "Flash the file that matches your hardware. Off-the-shelf files are built from your own stock file."}], "only": ["street", "race"]}, {"title": "Dyno tune", "blocks": [{"t": "text", "b": "Alpha-N uses throttle angle and rpm instead of the air-mass meter, so the car is mapped on a dyno for your exact parts. Plan a re-tune if you change hardware."}, {"t": "ill", "id": "e46-tune-alpha", "cap": "MAF-based tuning measures air; Alpha-N predicts it from throttle angle and rpm, which suits CSL boxes, cams and boost."}], "only": ["alpha"]}, {"title": "Check", "blocks": [{"t": "text", "b": "Clear codes, adaptation reset, drive gently through a few warm-up cycles."}]}], "alsoReplace": [{"name": "Spark plugs", "why": "Fresh plugs before a dyno session."}], "check": {"tab": "Check the result", "title": "After flashing", "illId": "e46-tune-hero", "illCap": "The S54 tuning path.", "rows": [{"see": "Pulls hard to the new limit", "means": "Done.", "do": ""}, {"see": "Cat or O2 codes on a street file", "means": "Hardware doesn''t match the file.", "do": "Race file or catted section."}, {"see": "Rough idle on Alpha-N", "means": "Needs refinement.", "do": "Back to the tuner."}], "c": {"level": "medium", "n": 2, "note": ""}}, "aftercare": ["Keep the stock file."], "disagreements": [{"topic": "Off-the-shelf vs custom", "pos": "Epic says off-the-shelf street and race files gain the same power; Alpha-N needs dyno time.", "call": "Off-the-shelf until you add a CSL box, cams or boost."}], "sources": ["BimmerWorld Epic Motorsports software listings", "Buildjournal ARH and Turner intake dyno articles", "Right Foot Down tuner''s guide", "Evolve airbox listings (dyno limiter note)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-valve-adjustment', '{"id": "e46-valve-adjustment", "title": "Valve adjustment & valve cover gasket", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Same shims, clearances and tools for the S54 in the 2001–2002 Z3 M and the Z4 M", "category": "Engine", "kind": "repair", "heroId": "e46-valve-hero", "heroCap": "The S54 has solid lifters: each rocker presses on a small shim on top of the valve. Clearance is measured between cam and rocker with the lobe pointing away.", "glance": {"timeFirst": "5–7 hr", "timeRepeat": "3–4 hr", "difficulty": 3, "cost": "$60–400", "risk": "Measuring on a warm engine · dropping a shim into the head", "why": "Unlike most modern engines, the S54 doesn''t adjust its own valves. As the rockers wear the gap grows, the valves open less, and the top end starts to tick. Re-shimming takes an afternoon and a feeler gauge.", "note": "It pairs naturally with plugs, coils and a VANOS job, since all three need the valve cover off."}, "lifespan": {"headline": ["BMW: every 30,000 miles"], "earliest": "Some specialists stretch it to 50,000 miles.", "detail": "A rattle from the valve cover means you''re overdue, but don''t wait for the noise.", "factors": ["High-rpm and track use", "Worn rockers"], "inspect": ["Measure at every plug change if the cover''s off anyway"], "confidence": {"level": "high", "n": 3, "note": "BimmerWorld, Turner and BMW all quote 30k; BimmerWorld notes the 50k view."}}, "variants": {"question": "Which shims?", "options": [{"id": "bmw", "label": "Genuine BMW shims", "when": "BMW shim set 11340031525, six of each size"}, {"id": "wiseco", "label": "Wiseco shims", "when": "Two VSK4 sets match the BMW range (BimmerWorld kit)", "brand": true}]}, "should": {"yesIf": ["It''s been 30k miles or you have no record", "There''s a ticking from the valve cover", "You''re doing VANOS, plugs or the valve cover gasket"], "codes": [], "notes": ["Measure first: many valves will still be in spec and keep their shims."], "confidence": {"level": "high", "n": 2, "note": "BMW training data, BimmerWorld."}}, "parts": [{"name": "Valve shim set", "pn": "11340031525", "price": "$600+", "tier": "oe", "note": "Six of each thickness; most owners buy only what they need", "only": ["bmw"]}, {"name": "Wiseco shim kit VSK4 ×2", "pn": "VSK4", "price": "$130", "tier": "aftermarket", "only": ["wiseco"]}, {"name": "Valve cover front corner stud grommets ×2", "pn": "11121437395", "price": "$4", "tier": "oe", "note": "The other gaskets are Viton and reusable, per Beisan"}, {"name": "Valve cover gasket + plug-well gaskets (if damaged)", "pn": "11127832034 / 11127831271", "price": "$60", "tier": "oe", "note": "Replace only if torn or hard"}, {"name": "Oil drain hose crush washers ×2", "pn": "07119963129", "price": "$2", "tier": "oe"}], "aftermarket": [{"name": "BimmerWorld S54 valve adjustment kit", "note": "Two Wiseco shim sets, BMW shim tool, full gasket set", "price": "$235", "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Engine/Engine-Maintenance/S54-Valve-Adjustment-Kit.html"}]}, {"name": "Turner S54 valve adjustment kits", "note": "Wiseco or Genuine shims, BMW shim tool, feeler set; some versions add oil and filter", "price": "$130–1,200", "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/p-401675-valve-adjustment-kit-plus/"}]}], "tools": [{"name": "BMW shim tool 83300493743", "note": "Holds the rocker down so the shim slides out"}, {"name": "Feeler gauge set, 0.02 mm steps", "note": "Stacking blades gives finer readings"}, {"name": "Micrometer 0–25 mm", "note": "To read shim thickness"}, {"name": "Magnetic pickup"}, {"name": "Crank turning socket", "note": "36 mm 12-point or the BMW tool"}, {"name": "Torque wrench 8–25 Nm"}], "before": ["The engine must be below 35 °C. Overnight cold is safest.", "Print a grid: 12 intake, 12 exhaust, measured, shim fitted, shim needed.", "Stuff rags around the shim area so nothing falls into the head."], "steps": [{"title": "Remove the valve cover", "blocks": [{"t": "text", "b": "Engine cover off, coils out, then the 15 valve cover bolts and studs and the oil drain banjo. Break the gasket loose at the front corners with a putty knife."}]}, {"title": "Know the numbers", "blocks": [{"t": "warn", "b": "Measure only below 35 °C engine temperature (BMW). A warm engine reads tight and you''ll fit the wrong shims."}, {"t": "text", "b": "Intake: 0.18–0.23 mm. Exhaust: 0.28–0.33 mm. Exhaust is the side nearer the exhaust manifold."}, {"t": "ill", "id": "e46-valve-gap", "cap": "Measure between the base circle of the cam and the rocker, with the lobe pointing away."}], "caution": true}, {"title": "Measure every valve", "blocks": [{"t": "text", "b": "Turn the crank clockwise until both lobes for a cylinder point away from their rockers. Slide the feeler between cam and rocker: the right blade drags slightly. Record it, then move to the next cylinder in firing order."}, {"t": "note", "b": "The S54 fires 1-5-3-6-2-4. Following it means the least crank turning."}], "timeSink": true}, {"title": "Work out the shims", "blocks": [{"t": "text", "b": "For each valve out of range: new shim = old shim + (measured − target). Aim for the middle of the range: 0.20 mm intake, 0.30 mm exhaust."}, {"t": "note", "b": "Example: an exhaust valve measures 0.38 mm on a 1.72 mm shim. 1.72 + (0.38 − 0.30) = 1.80 mm shim."}]}, {"title": "Swap the shims", "blocks": [{"t": "text", "b": "With the lobe pointing away, use the BMW tool to press the rocker down, then slide the shim out with a magnet. Measure it with the micrometer (don''t trust the printed number), fit the new one, release the tool."}, {"t": "warn", "b": "Count shims in and out. One dropped into the head means fishing until you find it."}], "caution": true}, {"title": "Recheck the ones you changed", "blocks": [{"t": "text", "b": "Turn the engine two full revolutions and re-measure every valve you shimmed. Anything still out gets another shim."}]}, {"title": "Refit the valve cover", "blocks": [{"t": "text", "b": "Clean the gaskets with brake cleaner (they''re Viton), seat every locating pin, fit the cover, the two new corner grommets and the drain banjo with new washers. Tighten the bolts evenly back and forth."}, {"t": "torque", "label": "Valve cover bolts", "nm": 8, "c": {"level": "medium", "n": 1, "note": "Beisan Systems S54 procedure."}}, {"t": "torque", "label": "Valve cover oil drain banjo", "nm": 25, "c": {"level": "medium", "n": 1, "note": "Beisan Systems S54 procedure."}}]}], "alsoReplace": [{"name": "Spark plugs", "why": "The coils are already out."}, {"name": "VANOS inspection", "why": "With the cover off you can see the exhaust hub tabs. Look before you close it."}], "check": {"tab": "Read your numbers", "title": "What your measurements mean", "illId": "e46-valve-gap", "illCap": "Cam lobe away, feeler between cam and rocker.", "rows": [{"see": "Everything inside the range", "means": "No shims needed.", "do": "Close it up; check again in 30k."}, {"see": "A few exhaust valves wide", "means": "Normal wear: the exhaust side opens up first.", "do": "Re-shim those to mid-range."}, {"see": "A valve tighter than the minimum", "means": "Less common, and it can burn the valve.", "do": "Re-shim it, and recheck after 1,000 miles."}], "c": {"level": "medium", "n": 2, "note": "Owner DIYs; the direction of wear isn''t in BMW''s training notes."}}, "aftercare": ["Check for oil at the valve cover corners after the first drive.", "Keep the shim log with the car''s records."], "disagreements": [{"topic": "30k or 50k miles", "pos": "BMW says 30k. Some specialists say 50k is fine on a road car.", "call": "Measure at 30k; if nothing moved, 50k next time is reasonable."}, {"topic": "Replace the valve cover gasket?", "pos": "Kits include a full gasket set. Beisan says the Viton gaskets can be cleaned and reused.", "call": "Reuse unless torn; always replace the two front corner grommets."}], "sources": ["BMW ST041 M3 technical training: S54 engine data", "BimmerWorld S54 valve adjustment kit", "Turner Motorsport S54 valve adjustment kits", "Z4-forum: E85 Z4 M valve adjustment DIY", "Beisan Systems S54 VANOS procedure (valve cover torques)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-vanos', '{"id": "e46-vanos", "title": "VANOS overhaul: pump disc, seals & solenoid", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Same S54 VANOS unit (11367838161) as the 2001–2002 Z3 M and the Z4 M; front-end access differs", "category": "Engine", "kind": "repair", "heroId": "e46-vanos-hero", "heroCap": "The S54''s double VANOS bolts to the front of the head. Its oil pump disc is driven by two tabs on the exhaust cam hub; the solenoid pack hangs underneath.", "glance": {"timeFirst": "8–12 hr", "timeRepeat": "5–6 hr", "difficulty": 4, "cost": "$300–750", "risk": "Fitting the VANOS without the pump disc engaging the tabs · dropping a bolt into the timing case", "why": "The S54''s VANOS runs on its own high-pressure oil pump, driven by two small tabs on the exhaust cam hub. Those tabs break, and when one goes it can end up in the pan or the timing chain. A re-drilled pump disc removes the slop that breaks them; doing the seals and solenoid at the same time fixes the other two common faults.", "note": "The seals-and-disc job doesn''t disturb cam timing. The rattle repair does, and needs BMW''s alignment bridge and crank pin."}, "lifespan": {"headline": ["Inspect the hub tabs by ~80k miles; overhaul when you find wear"], "earliest": "Codes for intake or exhaust VANOS position, or a 1,800–2,200 rpm rattle.", "detail": "Beisan finds the stock exhaust upper chain guide breaking by around 80k miles too, so it''s worth checking whenever the VANOS is off.", "factors": ["Rattle left unfixed", "Old oil", "High mileage"], "inspect": ["Valve cover off: look at the two tabs on the exhaust hub"], "confidence": {"level": "medium", "n": 2, "note": "Beisan Systems and Hack Engineering; there is no BMW interval."}}, "variants": {"question": "How far are you going?", "hint": "The definitive test for broken tabs is valve cover off and look. Both options include the machined pump disc.", "options": [{"id": "core", "label": "Pump disc, seals, sealing plate & solenoid", "when": "Cam timing isn''t disturbed · 7+ hr DIY"}, {"id": "full", "label": "Everything, plus the rattle repair", "when": "Splined shaft bearings, S62 springs, bolts, chain guide · retimes the engine"}]}, "should": {"yesIf": ["You have VANOS position codes or a VANOS solenoid circuit code", "There''s a rattle around 1,800–2,200 rpm or at idle", "You''re doing a valve adjustment and the hub tabs show wear", "The car is past ~80k with no record of VANOS work"], "codes": ["P0011", "P0012", "P0014", "P0015", "P1525", "P1531"], "notes": ["A circuit code usually means the solenoid pack. Position codes can be the pack or a broken tab. Beisan''s quick test: clear codes and idle; broken tabs usually set the light within a few minutes, a failing pack often needs a drive."], "confidence": {"level": "high", "n": 2, "note": "Beisan diagnostic notes; Hack Engineering workshop journals."}}, "parts": [{"name": "Machined VANOS oil pump disc (exchange)", "pn": "Beisan BS025", "price": "$150 + $300 core", "tier": "aftermarket", "note": "Hack Engineering offers a machining service on your own disc"}, {"name": "VANOS seals repair kit", "pn": "Beisan BS021", "price": "$60", "tier": "aftermarket", "note": "Includes the oil pressure restrictor O-rings"}, {"name": "VANOS sealing plate repair kit", "pn": "Beisan BS024", "price": "$10", "tier": "aftermarket"}, {"name": "Rebuilt solenoid coil pack (exchange)", "pn": "Beisan BS023", "price": "$200 + $300 core", "tier": "aftermarket", "note": "Optional if your pack tests fine"}, {"name": "VANOS gasket", "pn": "11367831938", "price": "$20", "tier": "oe"}, {"name": "Valve cover front corner stud grommets ×2", "pn": "11121437395", "price": "$4", "tier": "oe", "note": "The only valve cover seals that wear: the rest are Viton"}, {"name": "Oil drain hose crush washers ×2", "pn": "07119963129", "price": "$2", "tier": "oe"}, {"name": "VANOS oil accumulator pipe crush washers ×2", "pn": "07119963072", "price": "$2", "tier": "oe"}, {"name": "Three Bond 1209 sealant", "pn": "Beisan BS0SS", "price": "$15"}, {"name": "Rattle repair kit (bearing rings + washers)", "pn": "Beisan BS022", "price": "$80", "tier": "aftermarket", "only": ["full"]}, {"name": "Rattle tools (splined shaft holder + socket)", "pn": "Beisan BS095", "price": "$30 + $15 core", "tier": "aftermarket", "only": ["full"]}, {"name": "S62 sprocket hub diaphragm spring + pressure plate ×2", "pn": "11367833218", "price": "$40", "tier": "oe", "note": "Thicker spring; don''t mix with S54 parts", "only": ["full"]}, {"name": "Cam sprocket bolt set (24)", "pn": "Beisan BS029", "price": "$60–90", "tier": "aftermarket", "note": "Or updated Genuine BMW Torx sleeve bolts", "only": ["full"]}, {"name": "Exhaust upper chain guide", "pn": "Beisan BS026", "price": "$80", "tier": "aftermarket", "note": "Solid-body guide", "only": ["full"]}, {"name": "Chain guide bolt washer + chain tensioner washer", "pn": "07119963342 / 07119963418", "price": "$4", "tier": "oe", "only": ["full"]}], "aftermarket": [{"name": "Hack Engineering rebuilt VANOS unit (exchange)", "note": "Complete rebuilt unit with machined disc, Beisan seals and rattle kit, tested; send yours back", "price": "£795 + core", "links": [{"store": "Hack Engineering", "url": "https://hackengineering.co.uk/product/rebuilt-vanos-unit-s54"}]}, {"name": "Hack Engineering mail-order rebuild", "note": "Send your unit; it comes back with the Beisan parts and a machined disc", "price": "varies"}], "tools": [{"name": "Torque wrench 4–55 Nm"}, {"name": "24 mm open wrench", "note": "Turns the cams on their hex"}, {"name": "22 mm open wrench", "note": "Oil pressure restrictor"}, {"name": "5 mm hex bit, E5 Torx/4 mm, 10 mm, 14 mm and 17 mm sockets"}, {"name": "Internal retaining ring pliers"}, {"name": "Picks, small putty knives, razor knife"}, {"name": "Strong magnets", "note": "To open the solenoid valves for cleaning"}, {"name": "BMW crankshaft turning socket or 36 mm 12-point", "note": "Early engines have 4 Torx bolts on the pulley; later have a 27 mm hex adapter"}, {"name": "BMW cam alignment bridge 83300493749", "note": "Genuine only: Beisan says aftermarket bridges aren''t precise enough", "only": ["full"]}, {"name": "BMW crankshaft locking pin 83300490861", "only": ["full"]}, {"name": "1/2\" impact wrench + bench vise", "note": "To break the splined shaft covers loose", "only": ["full"]}], "before": ["Engine cold.", "Remove the fan and shroud, the cabin filter housing and any strut brace.", "Stuff towels into every gap below the sprockets before you remove a single bolt there.", "If you''re also doing a valve adjustment, do it while the VANOS is fully mounted: just before removal or just after refit."], "chapters": [{"id": "open", "title": "Open up", "blurb": "Valve cover off, engine to TDC."}, {"id": "off", "title": "VANOS off", "blurb": "Solenoid first to release the pressure, then the unit."}, {"id": "bench", "title": "On the bench", "blurb": "Pump disc, seals, sealing plate, solenoid."}, {"id": "rattle", "title": "Rattle repair", "blurb": "Splined shafts, hub springs, bolts, chain guide, retiming."}, {"id": "on", "title": "Refit", "blurb": "VANOS on, solenoid on, valve cover on."}], "steps": [{"title": "Remove the engine cover and valve cover", "blocks": [{"t": "text", "b": "Unplug the coils and pull them (they''re tight, wiggle hard). Remove the 15 valve cover bolts and studs, the oil drain banjo on the exhaust side, and break the gasket free with a putty knife at the front corners."}, {"t": "note", "b": "The S54''s valve cover gaskets and most grommets are Viton and can be reused. Only the two front corner stud grommets need replacing."}], "chapter": "open"}, {"title": "Set the engine to TDC", "blocks": [{"t": "text", "b": "Manual cars in neutral. Turn the crank clockwise until cylinder 1''s cams point toward each other at about 45°, then line up the TDC pointer with the single mark on the balancer at about 11 o''clock."}, {"t": "ill", "id": "e46-vanos-tabs", "cap": "The exhaust hub''s two tabs drive the VANOS pump disc. Look here first: a cracked or missing tab confirms the diagnosis."}], "chapter": "open"}, {"title": "Inspect the exhaust hub tabs", "blocks": [{"t": "text", "b": "Look at the two driver tabs on the front of the exhaust sprocket hub. If one is broken, find the missing piece: it can be lodged in the pump disc, in the pan, or near the chain."}, {"t": "warn", "b": "A broken tab means a new or used exhaust hub. The machined disc prevents the next break but doesn''t fix this one."}], "chapter": "open", "caution": true}, {"title": "Remove the solenoid pack", "blocks": [{"t": "text", "b": "Unplug the solenoid. Cover the lower radiator hose with towels. Crack the oil pressure restrictor loose with a 22 mm wrench while the pack is still bolted on, then remove the five 5 mm hex bolts and lower the pack with its sealing plate."}, {"t": "note", "b": "Removing the solenoid releases the VANOS hydraulics, so you can move the cams by hand without compressed air."}], "chapter": "off"}, {"title": "Fully retard both cams", "blocks": [{"t": "text", "b": "Put the 24 mm wrench on the exhaust cam hex and turn it counter-clockwise to its stop, rocking if it sticks. Repeat on the intake cam. With both retarded, the alignment holes between cylinders 2 and 3 point straight up."}], "chapter": "off"}, {"title": "Unbolt the VANOS", "blocks": [{"t": "text", "b": "Remove the upper chain guide (two 5 mm bolts), the VANOS bracket, and the accumulator pipe banjo and its lower bracket bolt. Then remove the five VANOS bolts and pry the unit forward evenly with a putty knife."}, {"t": "text", "b": "Thread two long solenoid bolts into the top corners to hang the VANOS, then unscrew each piston from its splined shaft stud. They''re left-hand threads: counter-hold the stud with a 7 mm wrench."}, {"t": "note", "b": "Before it goes to the bench, note where the pump disc holes sit. You''ll need to match them to the tabs on refit."}], "chapter": "off", "caution": true}, {"title": "Replace the oil pump disc", "blocks": [{"t": "text", "b": "Remove the retaining ring and washer, bag the pump side, and tap the unit on the bench to drop the disc out. Transfer the four spring pads (nipple facing out), springs and caps into the new disc, seat it in its bearing ring, and refit the washer and ring."}, {"t": "note", "b": "Use the newly drilled holes, which Beisan marks in black. If one cap sticks in the new disc''s bore, polish that bore for 30 seconds with 400-grit on an extension."}, {"t": "text", "b": "Turn the disc: it should spin smoothly, and you''ll hear it compress air. In service it builds oil pressure that''s regulated to about 100 bar."}], "chapter": "bench", "timeSink": true}, {"title": "Replace the piston seals", "blocks": [{"t": "text", "b": "One piston at a time: remove the cylinder cover, push the piston out, cut off the old Teflon rings and O-rings, and fit new O-ring first, then Teflon ring. Stretch the Teflon ring carefully, then leave the piston in its bore for a minute so the ring shrinks back."}, {"t": "torque", "label": "VANOS cylinder cover bolts", "nm": 10, "c": {"level": "medium", "n": 1, "note": "Beisan Systems S54 VANOS procedure, which lists torques for every fastener it touches."}}], "chapter": "bench"}, {"title": "Service the oil regulator and sealing plate", "blocks": [{"t": "text", "b": "Replace the two O-rings on the oil flow regulator and refit it with its overflow holes facing the sides. Cut the old rubber rings out of the sealing plate and press the new O-rings into its holes."}], "chapter": "bench"}, {"title": "Clean or replace the solenoid pack", "blocks": [{"t": "text", "b": "Remove the coil pack from the valve body, unscrew the pressure restrictor, and flush every valve with brake cleaner while holding each one open with a magnet. Fit new restrictor O-rings and filter, then the rebuilt or original coil pack."}, {"t": "torque", "label": "Coil pack bolts", "nm": 4, "c": {"level": "medium", "n": 1, "note": "Beisan Systems S54 VANOS procedure, which lists torques for every fastener it touches."}, "note": "by feel"}], "chapter": "bench"}, {"title": "Lock the crank and remove the hubs and splined shafts", "blocks": [{"t": "text", "b": "Fit the BMW crank locking pin at TDC. Loosen all six bolts on each sprocket hub about 2½ turns, pull out the splined shafts, then remove the hubs with their old diaphragm springs."}, {"t": "warn", "b": "Towels under the sprockets, two layers. A dropped bolt here means the timing cover comes off."}], "chapter": "rattle", "only": ["full"], "caution": true}, {"title": "Replace the sprocket bolts and chain guide", "blocks": [{"t": "text", "b": "One at a time, top down: remove each sprocket sleeve bolt, clean the hole, threadlock the new bolt and fit it. Then remove the chain tensioner (32 mm), pull the exhaust sprocket, replace the exhaust upper chain guide with a new washer, refit the sprocket with its slots left and right, and refit the tensioner with a new crush washer."}, {"t": "torque", "label": "Sprocket sleeve bolts (BMW Torx)", "nm": 12, "c": {"level": "medium", "n": 1, "note": "Beisan Systems S54 VANOS rattle procedure."}}, {"t": "torque", "label": "Exhaust upper chain guide bolt", "nm": 24, "c": {"level": "medium", "n": 1, "note": "Beisan Systems S54 VANOS rattle procedure."}}], "chapter": "rattle", "only": ["full"]}, {"title": "Rebuild the splined shaft bearings", "blocks": [{"t": "text", "b": "In the vise holder, break each splined shaft cover loose with the impact wrench on low (never a ratchet; the socket slips and snaps the stud). Replace the bearing ring and outer washers from the kit, tighten the cover, and check: the stud should turn with slight drag and no in-and-out play. Sand the washers or ring per Beisan to adjust, then threadlock the cover."}, {"t": "torque", "label": "Splined shaft cover", "nm": 55, "c": {"level": "medium", "n": 1, "note": "Beisan Systems S54 VANOS rattle procedure."}}], "chapter": "rattle", "only": ["full"], "timeSink": true}, {"title": "Retime and torque the hubs", "blocks": [{"t": "text", "b": "Fit the S62 diaphragm springs and pressure plates in the hubs. Set both cams with the Genuine BMW bridge between cylinders 2 and 3, refit the VANOS with splined shafts fully in, and follow Beisan''s sequence of snugging, turning the crank, and final-tightening the hub bolts."}, {"t": "torque", "label": "Sprocket hub bolts", "nm": 14, "c": {"level": "medium", "n": 1, "note": "Beisan Systems S54 VANOS rattle procedure."}, "note": "by feel"}, {"t": "warn", "b": "Check with the bridge after two full crank turns. If either end lifts more than 0.5 mm, the timing is wrong: repeat the adjustment before closing up."}], "chapter": "rattle", "only": ["full"], "caution": true}, {"title": "Refit the VANOS", "blocks": [{"t": "text", "b": "Turn the pump disc to roughly where it was. Fit a new gasket, hang the unit on the two long bolts, and thread each piston back onto its splined shaft stud (left-hand thread)."}, {"t": "text", "b": "Press the VANOS on until it stops, then look: rotate the pump disc until the hub tabs enter its holes. Only then push it fully onto the dowels."}, {"t": "warn", "b": "Never force the VANOS home. If it won''t seat, the tabs aren''t in the disc holes."}, {"t": "torque", "label": "VANOS mounting bolts", "nm": 10, "c": {"level": "medium", "n": 1, "note": "Beisan Systems S54 VANOS procedure, which lists torques for every fastener it touches."}}, {"t": "torque", "label": "VANOS bracket and chain guide bolts", "nm": 9, "c": {"level": "medium", "n": 1, "note": "Beisan Systems S54 VANOS procedure, which lists torques for every fastener it touches."}}, {"t": "torque", "label": "Oil accumulator pipe banjo (small)", "nm": 13, "c": {"level": "medium", "n": 1, "note": "Beisan Systems S54 VANOS procedure, which lists torques for every fastener it touches."}}], "chapter": "on", "caution": true, "only": ["core"]}, {"title": "Finish bolting up the VANOS", "blocks": [{"t": "text", "b": "With timing confirmed, refit the accumulator pipe with new crush washers, the VANOS bracket and the upper chain guide."}, {"t": "torque", "label": "VANOS mounting bolts", "nm": 10, "c": {"level": "medium", "n": 1, "note": "Beisan Systems S54 VANOS procedure, which lists torques for every fastener it touches."}}, {"t": "torque", "label": "VANOS bracket and chain guide bolts", "nm": 9, "c": {"level": "medium", "n": 1, "note": "Beisan Systems S54 VANOS procedure, which lists torques for every fastener it touches."}}, {"t": "torque", "label": "Oil accumulator pipe banjo (small)", "nm": 13, "c": {"level": "medium", "n": 1, "note": "Beisan Systems S54 VANOS procedure, which lists torques for every fastener it touches."}}], "chapter": "on", "only": ["full"]}, {"title": "Refit the solenoid pack", "blocks": [{"t": "text", "b": "Sealing plate on the valve body, notches aligned, restrictor facing right. Bolt it up and snug the restrictor moderately (it seals on an O-ring). Plug it in and zip-tie the connector."}, {"t": "torque", "label": "Solenoid mounting bolts", "nm": 10, "c": {"level": "medium", "n": 1, "note": "Beisan Systems S54 VANOS procedure, which lists torques for every fastener it touches."}}], "chapter": "on"}, {"title": "Refit the valve cover and coils", "blocks": [{"t": "text", "b": "A thin film of Three Bond at the VANOS-to-head joints at the top corners. Fit the gaskets with every locating pin seated, lay the cover down, refit the drain banjo and the 15 bolts with two new corner grommets, then the coils and harness."}, {"t": "torque", "label": "Valve cover oil drain banjo", "nm": 25, "c": {"level": "medium", "n": 1, "note": "Beisan Systems S54 VANOS procedure, which lists torques for every fastener it touches."}}, {"t": "torque", "label": "Valve cover bolts", "nm": 8, "c": {"level": "medium", "n": 1, "note": "Beisan Systems S54 VANOS procedure, which lists torques for every fastener it touches."}}, {"t": "note", "b": "Give the sealant an hour before driving."}], "chapter": "on"}], "alsoReplace": [{"name": "Valve adjustment", "why": "The valve cover is already off. Do it with the VANOS fully mounted, before removal or after refit."}, {"name": "VANOS high-pressure oil line", "why": "The accumulator line is already unbolted at the top, and it''s a known crack point."}, {"name": "Exhaust upper chain guide", "why": "If you''re not doing the full rattle job, at least inspect it: Beisan finds them breaking by about 80k.", "only": ["core"]}], "check": {"tab": "Read the hub & disc", "title": "What you find when it comes apart", "illId": "e46-vanos-tabs", "illCap": "Exhaust hub tabs and the pump disc holes they drive.", "rows": [{"see": "Tabs intact, light marks in the disc holes", "means": "Normal. You''re ahead of it.", "do": "Fit the machined disc and carry on."}, {"see": "Deep indentations on both sides of the disc holes", "means": "The disc has been rattling on the tabs, which is what breaks them.", "do": "Machined disc, and strongly consider the rattle repair."}, {"see": "A cracked or missing tab", "means": "The failure has happened.", "do": "New exhaust hub, find the broken piece, then the full overhaul."}], "c": {"level": "high", "n": 2, "note": "Beisan and Hack Engineering inspection notes."}}, "aftercare": ["Clear the codes, start it, and idle for several minutes watching for the check engine light.", "Recheck for leaks at the valve cover corners and the solenoid after the first drive.", "Send the cores back: Beisan refunds the core charge if they arrive undamaged within 90 days."], "disagreements": [{"topic": "Does every S54 need the machined disc?", "pos": "Beisan and Hack recommend it preventatively. Some owners only replace parts after a code.", "call": "If the VANOS is off for any reason, fit the disc."}, {"topic": "Replace the solenoid pack or clean it?", "pos": "Beisan sells rebuilt packs; cleaning with magnets and brake cleaner often restores a working one.", "call": "Clean it if you have no circuit codes; replace it if you do."}], "sources": ["Beisan Systems: S54 VANOS procedure (E46 M3)", "Beisan Systems: S54 VANOS rattle procedure", "Hack Engineering workshop journals (StevieM3 VANOS rebuild, M3 CS VANOS overhaul)", "Hack Engineering rebuilt VANOS unit listing", "Grassroots Motorsports S54 VANOS rebuild thread"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-bootlid', '{"id": "e46-bootlid", "title": "CSL-style bootlid & spoilers (coupe)", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Coupe only; the convertible decklid differs", "category": "Exterior", "kind": "upgrade", "heroId": "e46-body-hero", "heroCap": "The CSL bootlid has an integrated ducktail; inner tail lights, lock and wiring transfer from the old lid.", "glance": {"timeFirst": "2–3 hr + paint", "timeRepeat": "1.5 hr", "difficulty": 2, "cost": "$300–2,400", "risk": "Pinching wiring · gaps", "why": "The ducktail bootlid is the CSL''s signature rear detail.", "note": "Two people for removing and fitting the lid."}, "lifespan": {"headline": ["Cosmetic"], "factors": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "variants": {"question": "Which route?", "options": [{"id": "lip", "label": "Lip spoiler on the OE lid"}, {"id": "csl", "label": "CSL-style bootlid", "when": "Vorsteiner aero bootlid and others", "brand": true}]}, "should": {"yesIf": ["You want the CSL look"], "codes": [], "notes": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "parts": [{"name": "Lip spoiler", "price": "$150–400", "tier": "aftermarket", "only": ["lip"]}, {"name": "CSL-style bootlid", "price": "$800–2,395", "tier": "aftermarket", "note": "Vorsteiner aero bootlid $2,395", "only": ["csl"]}], "aftermarket": [], "tools": [{"name": "10 mm socket"}, {"name": "Masking tape for hinge marks"}], "before": ["Mark the hinge positions with tape."], "steps": [{"title": "Strip the old lid", "blocks": [{"t": "text", "b": "Remove the inner trim, unplug the lights and lock, and pull the wiring out."}], "only": ["csl"]}, {"title": "Swap the lid", "blocks": [{"t": "text", "b": "With a helper, unbolt the lid, fit the new one to the marks, transfer lock, lights and wiring."}], "only": ["csl"]}, {"title": "Fit the lip", "blocks": [{"t": "text", "b": "Clean, test-fit, then bond or bolt per the maker''s instructions."}], "only": ["