insert into guides (id, content) values ('e46-front-bumper', '{"id": "e46-front-bumper", "title": "Front bumper: OE, CSL-style or carbon", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "E46 M3 coupe and convertible", "category": "Exterior", "kind": "upgrade", "heroId": "e46-body-hero", "heroCap": "The bumper cover bolts to a carrier: aluminium on early cars (through 11/2001), carbon-Kevlar after.", "glance": {"timeFirst": "3–5 hr + paint", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$500–2,700 + paint", "risk": "Carrier mismatch · damaging fog or washer connections", "why": "The CSL front is the most popular E46 M3 styling upgrade; or just replace a damaged OE cover.", "note": "Most CSL-style covers arrive unpainted: plan on a body shop for paint and test fit."}, "lifespan": {"headline": ["Cosmetic"], "factors": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "variants": {"questions": [{"question": "Which bumper?", "options": [{"id": "oe", "label": "OE cover"}, {"id": "csl", "label": "CSL-style cover", "when": "BimmerWorld: unpainted, with grille and splitters", "brand": true}, {"id": "vor", "label": "Vorsteiner V-CSL / V20 carbon", "when": "Limited production pre-preg carbon", "brand": true}]}, {"question": "Which carrier?", "hint": "Check under the bumper or by build date.", "options": [{"id": "alu", "label": "Aluminium (to 11/2001)"}, {"id": "kev", "label": "Carbon-Kevlar (later)"}]}]}, "should": {"yesIf": ["Damaged bumper", "You want the CSL look"], "codes": [], "notes": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "parts": [{"name": "OE front bumper cover", "price": "$500–900", "tier": "oe", "only": ["oe"]}, {"name": "CSL-style cover (BimmerWorld)", "price": "$700–1,000", "tier": "aftermarket", "only": ["csl"]}, {"name": "Vorsteiner aero front bumper", "price": "$2,695", "tier": "aftermarket", "only": ["vor"]}, {"name": "Early aluminium carrier (option for later cars)", "pn": "51118195300", "price": "$150–300", "tier": "oe", "only": ["kev"]}, {"name": "Clips and fasteners", "price": "$20", "tier": "oe"}], "aftermarket": [], "tools": [{"name": "Trim tools, Torx, sockets"}, {"name": "A helper"}], "before": ["Battery disconnected if you have fogs or washers.", "Test-fit before paint."], "steps": [{"title": "Remove the old bumper", "blocks": [{"t": "text", "b": "Remove wheel-arch liner fasteners at the bumper ends, the undertray, and the bumper mounting bolts. Unplug fogs, washers and sensors, then slide it forward with a helper."}]}, {"title": "Check the carrier", "blocks": [{"t": "text", "b": "CSL-style covers are made for the aluminium carrier. On later carbon-Kevlar carriers BimmerWorld says slight modification or spoiler adhesive is usually needed, or fit the early/non-M carrier."}, {"t": "note", "b": "Most body shops handle the later-carrier fit.", "only": ["kev"]}], "only": ["csl", "vor"], "caution": true}, {"title": "Fit and align", "blocks": [{"t": "text", "b": "Transfer grilles, lights and washers, fit the cover and check panel gaps before final tightening."}]}], "alsoReplace": [{"name": "Radiator and condenser inspection", "why": "Clean the fins while the bumper''s off."}], "check": {"tab": "Check it", "title": "Fit check", "illId": "e46-body-hero", "illCap": "Bumper and carrier.", "rows": [{"see": "Even gaps to fenders and hood", "means": "Done.", "do": ""}, {"see": "Won''t line up on later cars", "means": "Carrier mismatch.", "do": "Modify or use the early carrier."}, {"see": "Fog or washer fault", "means": "Connector.", "do": "Reconnect."}], "c": {"level": "medium", "n": 1, "note": ""}}, "aftercare": ["Recheck fasteners after a week."], "disagreements": [], "sources": ["BimmerWorld CSL-style front bumper", "The Drive / Top Gear Vorsteiner V-CSL coverage"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-rear-diffuser', '{"id": "e46-rear-diffuser", "title": "Rear diffuser", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Fits the E46 M3 rear bumper", "category": "Exterior", "kind": "upgrade", "heroId": "e46-body-hero", "heroCap": "The diffuser bolts to the lower rear bumper around the quad exhausts.", "glance": {"timeFirst": "1–2 hr", "timeRepeat": "1 hr", "difficulty": 1, "cost": "$300–1,500", "risk": "Exhaust tip clearance", "why": "A CSL-style or carbon diffuser sharpens the rear.", "note": "Check clearance if you have an aftermarket exhaust."}, "lifespan": {"headline": ["Cosmetic"], "factors": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "should": {"yesIf": ["Cracked OE diffuser", "Styling"], "codes": [], "notes": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "parts": [{"name": "Rear diffuser (Vorsteiner V-CSL / V20 or similar)", "price": "$300–1,495", "tier": "aftermarket"}], "aftermarket": [], "tools": [{"name": "Trim tools, Torx"}], "before": ["Car raised for access."], "steps": [{"title": "Remove the OE diffuser", "blocks": [{"t": "text", "b": "Remove the fasteners under the bumper and unclip it."}]}, {"title": "Fit the new diffuser", "blocks": [{"t": "text", "b": "Test-fit, check exhaust tip clearance, then fasten."}]}], "alsoReplace": [], "check": {"tab": "Check it", "title": "Fit check", "illId": "e46-body-hero", "illCap": "Diffuser location.", "rows": [{"see": "Tips centred", "means": "Done.", "do": ""}, {"see": "Tips touching", "means": "Clearance.", "do": "Adjust exhaust hangers."}, {"see": "Rattle", "means": "Loose fastener.", "do": "Tighten."}], "c": {"level": "medium", "n": 1, "note": ""}}, "aftercare": [], "disagreements": [], "sources": ["Vorsteiner V-CSL / V20 coverage"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-supercharger', '{"id": "e46-supercharger", "title": "Supercharger kit (complete systems)", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Kits are specific to 6MT or SMG on some brands", "category": "Forced induction", "kind": "upgrade", "heroId": "e46-sc-hero", "heroCap": "A centrifugal blower (Rotrex or Vortech) on a belt drive, a front-mount intercooler on intercooled kits, a new intake manifold with bypass valve, bigger injectors and dedicated software.", "glance": {"timeFirst": "2–3 days", "timeRepeat": "—", "difficulty": 5, "cost": "$7,500–12,000", "risk": "Supercharging a tired engine · fuel and cooling left stock", "why": "The biggest jump an S54 can make on stock internals: from about 285 whp to roughly 390–460 whp measured on real cars, with drivability close to stock until you open it up.", "note": "Do the rod bearings, VANOS and cooling first. Boost finds weak parts fast."}, "lifespan": {"headline": ["Permanent; plan engine health first"], "factors": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "variants": {"questions": [{"question": "Which kit?", "options": [{"id": "prima", "label": "Active Autowerke PRIMA", "when": "Rotrex, non-intercooled, 5.8 psi; upgradeable", "brand": true}, {"id": "aa95", "label": "Active Autowerke Gen 9.5 Level 1", "when": "Rotrex, front-mount intercooler, 7–8 psi", "brand": true}, {"id": "vf", "label": "VF Engineering VFK73", "when": "Vortech, 570 hp claimed", "brand": true}, {"id": "ess", "label": "ESS VT2", "when": "Vortech V3; check availability, some versions discontinued", "brand": true}]}, {"question": "Transmission?", "options": [{"id": "mt", "label": "6-speed manual"}, {"id": "smg", "label": "SMG", "when": "AA lists SMG-specific kits"}]}]}, "should": {"yesIf": ["Healthy engine (compression/leakdown checked)", "Rod bearings and VANOS done", "You want ~100+ whp more"], "codes": [], "notes": ["Active Autowerke requires a signed off-road-use waiver before shipping.", "Most kits are sold for off-road or competition use; check your local emissions rules."], "confidence": {"level": "medium", "n": 2, "note": ""}}, "parts": [{"name": "Active Autowerke PRIMA kit", "pn": "12-021S", "price": "$9,375", "tier": "aftermarket", "note": "AA store; ''only 10 left''", "only": ["prima"]}, {"name": "Active Autowerke Gen 9.5 Level 1", "pn": "12-023", "price": "$10,700–11,250", "tier": "aftermarket", "note": "SMG version listed", "only": ["aa95"]}, {"name": "VF Engineering VFK73-01", "pn": "VFK73-01", "price": "$9,495", "tier": "aftermarket", "only": ["vf"]}, {"name": "ESS VT2-525 / 550 / 575", "price": "$7,500–9,300", "tier": "aftermarket", "note": "Dealers list some versions as discontinued: confirm with ESS", "only": ["ess"]}, {"name": "Colder spark plugs", "price": "$90–130", "tier": "aftermarket", "note": "Included in AA kits"}, {"name": "Rod bearings (if not done)", "price": "see guide", "tier": "oem"}, {"name": "Fresh coolant, belt, and plugs", "price": "$150", "tier": "oem"}], "aftermarket": [{"name": "AA PRIMA Plus 600 hp upgrade", "note": "Upgrade path for PRIMA owners", "price": "$8,360"}], "tools": [{"name": "Full metric set, torque wrenches"}, {"name": "Bumper removal tools (intercooled kits)"}, {"name": "Flash cable (supplied)"}], "before": ["Compression and leak-down test.", "Rod bearings, VANOS and cooling sorted.", "Read the kit instructions fully: they supersede this guide."], "chapters": [{"id": "gain", "title": "What you get"}, {"id": "ready", "title": "Make the engine ready"}, {"id": "fit", "title": "Install"}, {"id": "tune", "title": "Software & shakedown"}], "steps": [{"title": "What you get", "blocks": [{"t": "chart", "title": "Measured at the wheels", "unit": "whp", "baseline": "Stock (AA test car)", "bars": [{"label": "Stock (AA test car)", "v": 285, "note": "Dynojet, 232 wtq"}, {"label": "AA PRIMA, 5.8 psi", "v": 395, "note": "298 wtq; AA''s own dyno"}, {"label": "ESS VT2-500, ESS tune", "v": 388, "note": "280 wtq; 91 octane, owner Dynojet SAE"}, {"label": "ESS VT2-500, Evolve tune", "v": 464, "note": "314 wtq; same comparison"}, {"label": "ESS VT2-575, UK owner", "v": 428, "note": "decat; dyno type not stated"}], "source": "Wheel-hp figures from AA''s product page, an e46fanatics comparison and an m3cutters owner. Different dynos and fuels: compare within a row, not across.", "c": {"level": "medium", "n": 3, "note": "Real-car numbers from three sources."}}, {"t": "chart", "title": "Maker claims (crank hp)", "unit": "hp", "baseline": "Stock S54", "bars": [{"label": "Stock S54", "v": 333}, {"label": "AA PRIMA", "v": 480, "note": "AA store; ECS lists 425"}, {"label": "AA Gen 9.5 Level 1", "v": 525, "note": "7–8 psi"}, {"label": "ESS VT2-525", "v": 525, "note": "8 psi"}, {"label": "ESS VT2-550", "v": 550, "note": "9 psi"}, {"label": "VF VFK73", "v": 570}, {"label": "ESS VT2-575", "v": 575, "note": "10 psi"}], "source": "Manufacturer figures at the crank; expect wheel numbers ~15% lower.", "c": {"level": "single", "n": 4, "note": "Maker claims."}}, {"t": "note", "b": "Rotrex (Active Autowerke) vs Vortech (VF, ESS): owners report Rotrex kits give more low and midrange torque, Vortech kits build more at the top. Peak numbers end up similar."}], "chapter": "gain"}, {"title": "Check the engine", "blocks": [{"t": "text", "b": "Compression and leak-down test. Fix anything marginal before boost."}, {"t": "warn", "b": "A worn S54 doesn''t get healthier with boost. Rod bearings and VANOS first."}, {"t": "ill", "id": "e46-sc-layout", "cap": "Readiness list: the parts boost finds first."}], "chapter": "ready", "caution": true}, {"title": "Refresh the basics", "blocks": [{"t": "text", "b": "Coolant, belt, plugs (the kit''s colder heat range), and a fresh oil change."}], "chapter": "ready"}, {"title": "Remove the front end", "blocks": [{"t": "text", "b": "Remove the bumper, airbox and intake parts as the kit instructions direct. Intercooled kits mount a front-mount intercooler behind the bumper."}], "chapter": "fit"}, {"title": "Fit the blower and drive", "blocks": [{"t": "text", "b": "Fit the bracket, blower and belt drive, then the manifold with its bypass valve, and the charge pipes."}, {"t": "note", "b": "Follow each kit''s torque table: they differ by brand."}], "chapter": "fit", "timeSink": true}, {"title": "Fuel and sensors", "blocks": [{"t": "text", "b": "Fit the larger injectors and any fuel pump the kit supplies."}], "chapter": "fit"}, {"title": "Flash and shake down", "blocks": [{"t": "text", "b": "Flash the kit software, check for boost leaks, data-log a few pulls and re-check every clamp after the first drive."}, {"t": "note", "b": "Active Autowerke requires a signed off-road-use waiver before shipping.", "only": ["prima", "aa95"]}], "chapter": "tune", "caution": true}], "alsoReplace": [{"name": "Rod bearings", "why": "Insurance before adding 100+ hp."}, {"name": "Clutch (6MT)", "why": "A stock clutch may slip at supercharged torque; Sachs HD is rated around 350 lb-ft."}, {"name": "Brakes", "why": "Match the stopping to the speed."}], "check": {"tab": "Check the result", "title": "After the install", "illId": "e46-sc-hero", "illCap": "Supercharger kit layout.", "rows": [{"see": "Boost to spec, clean AFRs", "means": "Healthy.", "do": "Enjoy it."}, {"see": "Boost low", "means": "Leak or belt slip.", "do": "Smoke-test charge pipes; check belt tension."}, {"see": "Knock or lean on log", "means": "Fuel or tune.", "do": "Stop and contact the kit maker."}], "c": {"level": "medium", "n": 2, "note": ""}}, "aftercare": ["Shorter oil changes.", "Check belt and charge-pipe clamps regularly."], "disagreements": [{"topic": "Rotrex or Vortech", "pos": "Rotrex owners cite more usable midrange; Vortech owners cite top-end rush.", "call": "Rotrex for a road car; either for track."}, {"topic": "Tune quality", "pos": "Two VT2-500 cars on 91 octane: 388 whp on the ESS tune vs 464 whp with an Evolve tune.", "call": "The tuner matters as much as the kit."}], "sources": ["Active Autowerke PRIMA and Gen 9.5 product pages", "ECS Tuning and Turner supercharger listings", "Vortech: ESS E46 M3 VT2 listing", "ModBargains ESS listings (discontinued versions)", "e46fanatics EAS ESS VT2-500 build thread", "m3cutters ESS 575 dyno thread", "m3post Rotrex vs Vortech overlay", "Drifted E46 M3 supercharger guide"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-door-panel', '{"id": "e46-door-panel", "title": "Door panel removal & clips", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Coupe/convertible door panels", "category": "Interior", "kind": "repair", "heroId": "e46-door-hero", "heroCap": "Screws behind the handle trim, then clips around the edge; the panel lifts off the window ledge.", "glance": {"timeFirst": "30–45 min", "timeRepeat": "15 min", "difficulty": 1, "cost": "$10–30", "risk": "Snapping clips · side-airbag connector", "why": "The gateway to regulators, speakers and lock work.", "note": "Disconnect the battery before unplugging anything in the door."}, "lifespan": {"headline": ["Clips break with age"], "factors": [], "confidence": {"level": "community", "n": 1, "note": ""}}, "should": {"yesIf": ["Any work inside the door", "Rattling panel"], "codes": [], "notes": [], "confidence": {"level": "community", "n": 1, "note": ""}}, "parts": [{"name": "Door panel clips (set)", "price": "$10–20", "tier": "oe"}], "aftermarket": [], "tools": [{"name": "Trim removal tools"}, {"name": "Torx set"}], "before": ["Battery disconnected."], "steps": [{"title": "Remove the fasteners", "blocks": [{"t": "text", "b": "Pry off the trim around the handle and remove the screws behind it."}]}, {"title": "Release the clips", "blocks": [{"t": "text", "b": "Work a trim tool around the edge to pop the clips, then lift the panel up off the window ledge."}], "caution": true}, {"title": "Disconnect", "blocks": [{"t": "text", "b": "Unplug switches and the door handle cable; set the panel aside."}]}], "alsoReplace": [{"name": "Vapour barrier", "why": "Reseal it if torn, or water gets in."}], "check": {"tab": "Check it", "title": "On refit", "illId": "e46-door-hero", "illCap": "Door panel.", "rows": [{"see": "Panel sits flush", "means": "All clips home.", "do": ""}, {"see": "Rattle", "means": "Broken clip.", "do": "Replace it."}, {"see": "Airbag light", "means": "Connector.", "do": "Recon