insert into guides (id, content) values ('e46-control-arms', '{"id": "e46-control-arms", "title": "Front control arms & ball joints", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "M3-specific arms (31122229453 / 454)", "category": "Steering", "kind": "repair", "heroId": "e46-arm-hero", "heroCap": "Each front control arm has an inner ball joint into the subframe, an outer ball joint into the knuckle, and the rear bushing (FCAB) in a bracket on the frame rail.", "glance": {"timeFirst": "3–5 hr", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$300–1,000", "risk": "Torquing the bushing bracket with the suspension hanging · stuck ball joint tapers", "why": "The ball joints are pressed into the arm and aren''t serviceable, so a worn joint means a new arm. Most owners do the FCABs at the same time.", "note": "Get a four-wheel alignment afterwards."}, "lifespan": {"headline": ["~80,000–100,000 miles"], "factors": ["Track use"], "confidence": {"level": "community", "n": 1, "note": ""}}, "should": {"yesIf": ["Clunk on braking or turn-in", "Torn ball joint boot", "Play at the outer joint"], "codes": [], "notes": [], "confidence": {"level": "community", "n": 1, "note": ""}}, "parts": [{"name": "Front control arm, left / right", "pn": "31122229453 / 31122229454", "price": "$180–350 ea", "tier": "oem", "note": "Lemförder"}, {"name": "FCAB brackets with bushings, left / right", "pn": "31122229623 / 31122229624", "price": "$60–90 ea", "tier": "oem", "note": "Optional but recommended"}, {"name": "Self-locking nuts", "price": "$10", "tier": "oe"}], "aftermarket": [{"name": "Powerflex or Delrin FCABs", "note": "See the FCAB guide", "price": "$100–250"}], "tools": [{"name": "Ball joint separator / pickle fork"}, {"name": "Torque wrench 60–100 Nm"}, {"name": "Jack to set ride height"}], "before": ["Car on stands, wheel off."], "steps": [{"title": "Disconnect the outer joint", "blocks": [{"t": "text", "b": "Remove the outer ball joint nut and separate it from the knuckle."}]}, {"title": "Remove the arm", "blocks": [{"t": "text", "b": "Unbolt the FCAB bracket from the frame rail, then remove the inner ball joint nut and drive the joint out of the subframe."}], "timeSink": true}, {"title": "Fit the new arm", "blocks": [{"t": "text", "b": "Fit the inner joint and outer joint with new self-locking nuts."}, {"t": "torque", "label": "Inner ball joint to subframe", "nm": 90, "c": {"level": "medium", "n": 2, "note": "e46fanatics ''Yet Another Torque Guide'' (Bentley values), matched by a second Bentley transcription."}}, {"t": "torque", "label": "Outer ball joint to knuckle", "nm": 65, "c": {"level": "medium", "n": 2, "note": "e46fanatics ''Yet Another Torque Guide'' (Bentley values), matched by a second Bentley transcription."}}]}, {"title": "Tighten the bracket at ride height", "blocks": [{"t": "text", "b": "Jack the suspension to ride height, then tighten the FCAB bracket."}, {"t": "torque", "label": "FCAB bracket to frame rail", "nm": 60, "c": {"level": "medium", "n": 2, "note": "e46fanatics ''Yet Another Torque Guide'' (Bentley values), matched by a second Bentley transcription."}}, {"t": "text", "b": "Get a four-wheel alignment afterwards."}], "caution": true}], "alsoReplace": [{"name": "FCABs", "why": "The bracket is already off."}, {"name": "Tie rods", "why": "Same corner, same alignment."}], "check": {"tab": "Check it", "title": "Old arm check", "illId": "e46-arm-hero", "illCap": "Arm, joints and bushing.", "rows": [{"see": "Ball joint loose by hand", "means": "Worn.", "do": "New arm."}, {"see": "Bushing cracked", "means": "Worn FCAB.", "do": "Replace bushing."}, {"see": "Both fine", "means": "Look at tie rods or end links.", "do": ""}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": ["Alignment."], "disagreements": [], "sources": ["e46fanatics ''Yet Another Torque Guide''", "Turner and BimmerWorld Lemförder E46 M3 control arm listings"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-steering-rack', '{"id": "e46-steering-rack", "title": "Steering rack: replacement or quicker ratio", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Standard M3 rack fits 2001–2006 cars without ZCP", "category": "Steering", "kind": "upgrade", "heroId": "e46-steer-hero", "heroCap": "The rack bolts to the front subframe; the steering shaft joins it at the pinion.", "glance": {"timeFirst": "4–6 hr", "timeRepeat": "3 hr", "difficulty": 3, "cost": "$480–1,100", "risk": "Wrong fluid · an off-centre wheel after fitting a different ratio", "why": "A leaking or notchy rack is replaced like-for-like; or you can fit a quicker rack. The standard M3 rack is 15.4:1, the CS/CSL/ZCP rack 14.5:1, and BimmerWorld measures the new AAE E46 rack at about 50 mm per turn, close to the ZCP rack.", "note": "Use CHF power steering fluid only, never ATF, and flush the system."}, "lifespan": {"headline": ["Replace on leaks or play"], "factors": ["Age"], "confidence": {"level": "medium", "n": 1, "note": ""}}, "variants": {"question": "Which rack?", "options": [{"id": "std", "label": "Like-for-like (rebuilt)", "when": "AAE rebuilt, non-ZCP M3"}, {"id": "quick", "label": "Quicker ratio", "when": "New AAE E46 rack (~ZCP rate) or a genuine ZCP/CSL rack", "brand": true}]}, "should": {"yesIf": ["Fluid leaking from the rack", "Notchy or heavy steering", "You want ZCP-style response"], "codes": [], "notes": ["ZCP cars already have the quick rack."], "confidence": {"level": "medium", "n": 2, "note": "BimmerWorld, z4-forum ratio list."}}, "parts": [{"name": "Rebuilt rack (AAE)", "pn": "replaces 32136753438 / 32132229397", "price": "$484", "tier": "aftermarket", "only": ["std"]}, {"name": "New AAE E46 rack (~50 mm/turn)", "price": "$700–900", "tier": "aftermarket", "only": ["quick"]}, {"name": "CHF power steering fluid", "price": "$30", "tier": "oe"}, {"name": "CHF cap label", "pn": "71212122171", "price": "$3", "tier": "oe"}], "aftermarket": [{"name": "Turner rack stop kit", "note": "Limits travel so wide tyres don''t rub at full lock", "price": "$40"}], "tools": [{"name": "Fluid catch pan"}, {"name": "Torque wrench"}, {"name": "Line wrenches"}], "before": ["Centre and lock the steering wheel.", "Note the old rack''s tie rod lengths."], "steps": [{"title": "Drain and disconnect", "blocks": [{"t": "text", "b": "Drain the reservoir, disconnect the steering shaft at the pinion (mark its position), the pressure and return lines, and the tie rods at the knuckles."}]}, {"title": "Remove the rack", "blocks": [{"t": "text", "b": "Unbolt the rack from the front subframe and remove it."}, {"t": "note", "b": "Turner''s front subframe instructions note the rack mounts with two nuts and bolts."}]}, {"title": "Fit the new rack", "blocks": [{"t": "text", "b": "Bolt it in, reconnect lines with new washers, the shaft at your mark, and the tie rods."}, {"t": "torque", "label": "Rack to subframe", "nm": 42, "c": {"level": "single", "n": 1, "note": "One E46 torque reference; confirm in Bentley."}}, {"t": "torque", "label": "Tie rod end nut at the knuckle", "nm": 65, "c": {"level": "high", "n": 1, "note": "BMW TIS 32 21 steering arms table (E46 row)."}}]}, {"title": "Fill, bleed and align", "blocks": [{"t": "text", "b": "Fill with CHF, turn lock to lock engine off several times, then run and recheck. Get an alignment."}, {"t": "note", "b": "With a different ratio the wheel won''t be centred until the alignment shop sets the toe.", "only": ["quick"]}]}], "alsoReplace": [{"name": "Tie rods", "why": "Many new racks need them, and it''s one alignment."}], "check": {"tab": "Check it", "title": "After fitting", "illId": "e46-steer-hero", "illCap": "Rack and tie rods.", "rows": [{"see": "Whine", "means": "Air in the system.", "do": "Bleed again."}, {"see": "Wheel off-centre", "means": "Toe not set.", "do": "Alignment."}, {"see": "Weep at a line", "means": "Washer.", "do": "New crush washers."}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": ["Recheck fluid after a drive."], "disagreements": [{"topic": "Genuine ZCP rack or AAE?", "pos": "Genuine ZCP racks are scarce; BimmerWorld says the new AAE rack is very similar in rate.", "call": "AAE unless you find a good ZCP rack."}], "sources": ["BimmerWorld AAE E46 rack listings", "z4-forum steering rack ratio threads", "Turner Motorsport rack stop kit", "Turner E46 front subframe reinforcement instructions"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-tie-rods', '{"id": "e46-tie-rods", "title": "Tie rods (inner & outer)", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "M3-specific assemblies (32112228785 / 786); non-M E46 rods differ", "category": "Steering", "kind": "repair", "heroId": "e46-steer-hero", "heroCap": "Inner tie rod threads into the rack inside the boot; outer end bolts to the knuckle. They''re sold as complete M3 assemblies or as outer ends.", "glance": {"timeFirst": "1.5–3 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$100–300", "risk": "Changing toe by miscounting threads · over-torquing the inner joint into the rack", "why": "Worn tie rods make the steering vague and can clunk. On the M3, BimmerWorld''s experience is that the inner joint wears as much as the outer, so they replace the whole assembly.", "note": "Get a four-wheel alignment afterwards."}, "lifespan": {"headline": ["Inspect yearly; replace on any play"], "factors": ["Track use", "Potholes"], "confidence": {"level": "medium", "n": 1, "note": "BimmerWorld."}}, "variants": {"question": "Which parts?", "options": [{"id": "full", "label": "Complete assemblies", "when": "Inner + outer, BimmerWorld''s recommendation"}, {"id": "outer", "label": "Outer ends only", "when": "Inner joint is tight"}]}, "should": {"yesIf": ["Play when you rock the wheel at 3 and 9 o''clock", "Torn rack boot", "Uneven inner tyre wear"], "codes": [], "notes": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "parts": [{"name": "Tie rod assembly, left / right", "pn": "32112228785 / 32112228786", "price": "$70–110 ea", "tier": "oem", "note": "Lemförder", "only": ["full"]}, {"name": "Outer tie rod end, left / right", "pn": "32212229367 / 32212229368", "price": "$50–130 ea", "tier": "oem", "only": ["outer"]}, {"name": "Rack boots + clamps", "price": "$30", "tier": "oem", "only": ["full"]}], "aftermarket": [], "tools": [{"name": "Inner tie rod tool or large crowfoot", "only": ["full"]}, {"name": "Ball joint separator"}, {"name": "Torque wrench 45–110 Nm"}, {"name": "Tape measure / thread counter"}], "before": ["Steering wheel centred and locked.", "Measure the old rod''s length end to end, or count threads at the locknut."], "steps": [{"title": "Separate the outer joint", "blocks": [{"t": "text", "b": "Remove the nut at the knuckle and pop the ball joint out with a separator."}]}, {"title": "Remove the outer end", "blocks": [{"t": "text", "b": "Loosen the locknut, count the turns as you unscrew the outer end, and fit the new one the same number of turns."}], "only": ["outer"]}, {"title": "Remove the inner rod", "blocks": [{"t": "text", "b": "Cut the boot clamps, slide the boot back, and unscrew the inner rod from the rack with the tie rod tool."}], "only": ["full"]}, {"title": "Fit the new assembly", "blocks": [{"t": "text", "b": "Set the new assembly to the old one''s length, thread the inner joint into the rack, and torque it."}, {"t": "torque", "label": "Inner tie rod to rack", "nm": 100, "c": {"level": "high", "n": 1, "note": "BMW TIS 32 21 steering arms table (E46 row)."}, "note": "+10"}, {"t": "text", "b": "New boot and clamps."}], "only": ["full"], "caution": true}, {"title": "Reconnect and lock", "blocks": [{"t": "torque", "label": "Tie rod end nut at the knuckle", "nm": 65, "c": {"level": "high", "n": 1, "note": "BMW TIS 32 21 steering arms table (E46 row)."}}, {"t": "torque", "label": "Tie rod locknut", "nm": 45, "c": {"level": "high", "n": 1, "note": "BMW TIS 32 21 steering arms table (E46 row)."}}, {"t": "text", "b": "Get a four-wheel alignment afterwards."}]}], "alsoReplace": [{"name": "Rack boots", "why": "A torn boot lets grit into the rack."}], "check": {"tab": "Check it", "title": "Old rod check", "illId": "e46-steer-hero", "illCap": "Tie rod layout.", "rows": [{"see": "Inner joint flops under its own weight", "means": "Worn.", "do": "Replace assemblies."}, {"see": "Outer joint notchy", "means": "Worn.", "do": "Replace."}, {"see": "Both tight", "means": "Look elsewhere.", "do": "Check control arm ball joints."}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": ["Alignment the same day."], "disagreements": [{"topic": "Outer only?", "pos": "BimmerWorld says the inner wears as much as the outer.", "call": "Whole assemblies on a high-mileage car."}], "sources": ["BMW TIS 32 21 steering arms torque table", "BimmerWorld E46 M3 tie rod listings", "Turner Motorsport E46 M3 tie rod kit"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-coilovers', '{"id": "e46-coilovers", "title": "Coilovers, springs & dampers", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "E46 M3 coupe and convertible; non-M E46 kits are different", "category": "Suspension", "kind": "upgrade", "heroId": "e46-co-hero", "heroCap": "Front: a strut that drops into the M3''s knuckle and bolts to the tower with three nuts. Rear: separate spring and shock, the spring sitting on the lower control arm.", "glance": {"timeFirst": "5–7 hr", "timeRepeat": "3–4 hr", "difficulty": 3, "cost": "$800–3,500", "risk": "Torquing rear shocks with the suspension hanging · reusing torn top mounts", "why": "Factory Sachs dampers on most E46 M3s are long past their best. Whether you refresh them, drop in sport shocks and springs, or go to coilovers, the job and the hardware to replace with it are the same.", "note": "Alignment is required afterwards, and sway bars are best chosen after the ride height is settled."}, "lifespan": {"headline": ["Dampers: 60,000–80,000 miles"], "factors": ["Track use", "Rough roads"], "inspect": ["Bounce test, leaks on the shock body, clunks over bumps"], "confidence": {"level": "community", "n": 2, "note": "Common practice."}}, "variants": {"questions": [{"question": "Which route?", "options": [{"id": "oe", "label": "Factory refresh", "when": "New OE-spec dampers and springs, stock height", "oeOnly": true}, {"id": "sport", "label": "Sport shocks + lowering springs", "when": "Bilstein-type dampers with H&R or Eibach springs"}, {"id": "coil", "label": "Coilovers", "when": "KW, Bilstein PSS10, Öhlins, Fortune Auto, Eibach"}]}, {"question": "Camber plates?", "options": [{"id": "noplates", "label": "No, factory top mounts", "when": "Street use; Öhlins and Bilstein use OE mounts"}, {"id": "plates", "label": "Yes, camber plates", "when": "Track alignment; some kits include them"}]}]}, "should": {"yesIf": ["Floaty or bouncy ride, or leaking shocks", "Original dampers past 80k", "You want a lower stance or track alignment"], "codes": [], "notes": ["Turner notes the Bilstein PSS10 won''t fit cars with factory electronically adjustable (EDC) dampers. Check yours before ordering any kit."], "confidence": {"level": "medium", "n": 2, "note": "Turner, BimmerWorld."}}, "parts": [{"name": "Front struts and rear shocks (OE spec)", "price": "$500–900", "tier": "oem", "note": "Sachs/Boge OE type", "only": ["oe"]}, {"name": "OE-spec springs", "price": "$200–350", "tier": "oe", "note": "Cars from 12/04 use the ZCP rates", "only": ["oe"]}, {"name": "Sport dampers + lowering springs", "price": "$900–1,400", "tier": "aftermarket", "only": ["sport"]}, {"name": "Coilover kit", "price": "$1,200–3,500", "tier": "aftermarket", "only": ["coil"]}, {"name": "Camber plates (if not in kit)", "price": "$350–600", "tier": "aftermarket", "only": ["plates"]}, {"name": "Front strut top mounts + bearings", "price": "$80–150", "tier": "oe", "only": ["noplates"]}, {"name": "Rear shock mounts", "price": "$60–120", "tier": "oe", "note": "Inspect for tearing; see the shock mount guide"}, {"name": "Self-locking nuts (top mounts, shocks)", "price": "$15", "tier": "oe", "note": "Single-use: new nuts"}], "aftermarket": [{"name": "KW V1 / V2 / V3 / Clubsport", "note": "Full range for the E46 M3 coupe and convertible; V3 adds separate rebound and compression", "price": "$1,800–3,500", "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E46-M3-Parts/c-554-bmw-coilovers/m-649-kw-suspension"}], "only": ["coil"]}, {"name": "Bilstein B16 PSS10", "note": "10 damping settings; keeps the stock sway bar tab location, so stock links fit. Not for EDC cars", "price": "$2,000", "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/p-1588-e46-m3-bilstein-pss10-coil-over-suspension/"}], "only": ["coil"]}, {"name": "Öhlins Road & Track", "note": "DFV dampers, 70 N/mm front / 110 N/mm rear, uses OE top mounts, roughly 15–35 mm lower front", "price": "£2,320", "only": ["coil"]}, {"name": "Fortune Auto 500 Series", "note": "24-way adjustable; E46 M3 kit includes front camber plates", "price": "$1,400–1,700", "only": ["coil"]}, {"name": "Eibach Pro-Street S", "note": "Height-adjustable kit with its own end links", "price": "$1,300", "only": ["coil"]}], "tools": [{"name": "Spring compressor (OE route only)", "only": ["oe", "sport"]}, {"name": "Torque wrench 14–110 Nm"}, {"name": "Thin 16 mm open-end wrench", "note": "Front end link"}, {"name": "Deep 13 mm socket", "note": "Top mount nuts"}, {"name": "Pry bar", "note": "Rear spring"}], "before": ["Release the parking brake so the rear lower arm drops far enough for the spring to come out.", "Wheels off, car on stands at all four corners.", "Measure and note current ride height if you want to match it."], "chapters": [{"id": "front", "title": "Front struts"}, {"id": "rear", "title": "Rear shocks & springs"}, {"id": "finish", "title": "Set up"}], "steps": [{"title": "Free the front strut", "blocks": [{"t": "text", "b": "Push the brake line, ABS and pad-wear wires out of their clips on the strut. Disconnect the end link at the strut, holding the ball stud on its flats with a thin 16 mm wrench. Support the knuckle, then crack the three top-mount nuts under the hood."}], "chapter": "front"}, {"title": "Remove and swap", "blocks": [{"t": "text", "b": "Release the strut from the knuckle and lower it out. On the OE or sport route, compress the spring and transfer the top mount; for coilovers, fit the kit''s mount or camber plate."}, {"t": "torque", "label": "Front strut shaft nut (M14)", "nm": 64, "c": {"level": "high", "n": 3, "note": "Bentley via e46fanatics; Autodoc E46 procedure."}}, {"t": "warn", "b": "Never undo the shaft nut on a strut with the spring uncompressed.", "only": ["oe", "sport"]}], "chapter": "front", "caution": true}, {"title": "Refit the front", "blocks": [{"t": "text", "b": "Seat the strut fully in the knuckle, with any index pin in its slot, and fit the top nuts. M3s with the factory strut brace have reinforcement plates under the tower: keep them, or add them with camber plates."}, {"t": "torque", "label": "Strut top-mount nuts (3), 18 mm flange", "nm": 24, "c": {"level": "medium", "n": 2, "note": "e46fanatics ''Yet Another Torque Guide'' (Bentley values), matched by another Bentley transcription."}}, {"t": "torque", "label": "Strut top-mount nuts (3), 21 mm flange", "nm": 34, "c": {"level": "medium", "n": 2, "note": "e46fanatics ''Yet Another Torque Guide'' (Bentley values), matched by another Bentley transcription."}}, {"t": "torque", "label": "Strut to knuckle (M3 three-bolt knuckle)", "nm": 107, "c": {"level": "varies", "n": 2, "note": "A Bentley-sourced E46 table lists 107 Nm for the M3/M-style three-bolt knuckle; non-M pinch bolts are 81 Nm. Confirm your knuckle type."}, "alt": [81]}, {"t": "torque", "label": "Front end link to strut", "nm": 65, "c": {"level": "varies", "n": 3, "note": "Bentley transcriptions give 59–65 Nm; one Bentley quote is 44 ft-lb (60 Nm)."}, "alt": [59]}], "chapter": "front"}, {"title": "Remove the rear shock", "blocks": [{"t": "text", "b": "Pull the trunk side trim inward and cut away the soft sound-deadening to reach the two top nuts. Undo the lower 16 mm shock bolt underneath, then the top nuts, and remove the shock."}], "chapter": "rear"}, {"title": "Swap the rear spring", "blocks": [{"t": "text", "b": "With the parking brake off, lever the lower arm down and pry the spring out. Fit the new spring with its pads. Coilover kits put a height adjuster on the lower arm: nut and washer underneath."}, {"t": "note", "b": "Cut access holes in the trunk liners if your dampers adjust from the top.", "only": ["coil"]}], "chapter": "rear", "timeSink": true}, {"title": "Fit the rear shock", "blocks": [{"t": "text", "b": "Fit the shock to its top mount, then into the car. Snug the lower bolt but don''t torque it yet."}, {"t": "torque", "label": "Rear shock shaft to top mount", "nm": 14, "c": {"level": "medium", "n": 2, "note": "e46fanatics ''Yet Another Torque Guide'' (Bentley values), matched by another Bentley transcription."}}, {"t": "torque", "label": "Rear top mount to body (M8 self-locking)", "nm": 28, "c": {"level": "medium", "n": 2, "note": "e46fanatics ''Yet Another Torque Guide'' (Bentley values), matched by another Bentley transcription."}}], "chapter": "rear"}, {"title": "Torque the rear at ride height", "blocks": [{"t": "text", "b": "Raise the rear arm with a jack until the car is at ride height, then torque the lower bolt."}, {"t": "torque", "label": "Rear shock to trailing arm, at ride height", "nm": 100, "c": {"level": "varies", "n": 3, "note": "Most Bentley transcriptions give 74 ft-lb (100 Nm); one quotes 44 ft-lb. Torque it loaded."}, "alt": [60]}, {"t": "warn", "b": "Torquing rubber-bushed joints with the suspension hanging pre-loads the bushings and wears them out."}], "chapter": "finish", "caution": true}, {"title": "Set height and damping, then align", "blocks": [{"t": "text", "b": "Set ride height evenly side to side, start damping at the maker''s street setting, and get a four-wheel alignment."}, {"t": "note", "b": "Speed Academy found 8k/10k springs comfortable on the street up to about click 15 of 24 on their kit.", "only": ["coil"]}], "chapter": "finish"}], "alsoReplace": [{"name": "Rear shock mounts", "why": "They''re in your hand. Torn mounts clunk and can damage the tower."}, {"name": "Front sway bar end links", "why": "Already disconnected, and lowered cars often need adjustable ones."}], "check": {"tab": "Read the old parts", "title": "What the old parts tell you", "illId": "e46-co-hero", "illCap": "Front strut and separate rear spring and shock.", "rows": [{"see": "Shock compresses and doesn''t push back", "means": "Gas charge gone.", "do": "You were overdue."}, {"see": "Oil down the body", "means": "Seal failed.", "do": "Replace in pairs."}, {"see": "Top mount rubber split", "means": "Mount failing.", "do": "Replace it now."}], "c": {"level": "community", "n": 2, "note": "Common practice."}}, "aftercare": ["Re-torque wheel nuts after 50 miles.", "Recheck ride height after a week as springs settle.", "Alignment before any spirited driving."], "disagreements": [{"topic": "Front end link torque", "pos": "Bentley transcriptions vary from 59 to 65 Nm.", "call": "65 Nm on the ball-stud nut, holding the stud."}, {"topic": "Rear lower shock bolt", "pos": "Most sources say 100 Nm; one Bentley quote says 44 ft-lb.", "call": "100 Nm, at ride height."}], "sources": ["Speed Academy: E46 M3 coilover installation guide", "e46fanatics ''Yet Another Torque Guide'' and Bentley torque threads", "E46 torque table (mirum.org)", "Turner Motorsport KW and Bilstein PSS10 E46 M3 listings", "Suspension Secrets: Öhlins Road & Track E46 M3", "Eibach Pro-Street S E46 M3 instructions"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-endlinks', '{"id": "e46-endlinks", "title": "Sway bar end links", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "M3-specific front links; Turner bars use the stock M3 front link", "category": "Suspension", "kind": "repair", "heroId": "e46-sway-hero", "heroCap": "Front links run from the strut to the bar; rear links from the bar to the rear arms.", "glance": {"timeFirst": "45–90 min", "timeRepeat": "30 min", "difficulty": 1, "cost": "$40–200", "risk": "Spinning ball studs · snapping a plastic link''s joint", "why": "The commonest clunk on an E46. Cheap, quick, and the first thing to check before blaming struts or bushings.", "note": "Lowered cars often need adjustable links to avoid preloading the bar."}, "lifespan": {"headline": ["~60,000–80,000 miles"], "factors": ["Lowering", "Rough roads"], "confidence": {"level": "community", "n": 2, "note": "Common practice."}}, "variants": {"question": "Which end?", "options": [{"id": "f", "label": "Front"}, {"id": "r", "label": "Rear"}, {"id": "fr", "label": "Both"}]}, "should": {"yesIf": ["Clunk over small bumps", "Torn boot or play in the ball joint"], "codes": [], "notes": [], "confidence": {"level": "community", "n": 2, "note": ""}}, "parts": [{"name": "Front end links (M3), pair", "price": "$60–120", "tier": "oem", "note": "Lemförder OE", "only": ["f", "fr"]}, {"name": "Rear end links, pair", "price": "$40–80", "tier": "oem", "only": ["r", "fr"]}, {"name": "Adjustable links (optional)", "price": "$120–200", "tier": "aftermarket"}], "aftermarket": [{"name": "Adjustable end links", "note": "Recommended with coilovers or bigger bars (H&R, BimmerWorld)", "price": "$120–200"}], "tools": [{"name": "Thin 16 mm open-end wrench", "note": "For the stud flats"}, {"name": "10 mm wrench", "note": "Some ball studs have an inner hex"}, {"name": "Torque wrench"}], "before": ["Wheels off or turned for access."], "steps": [{"title": "Remove the old link", "blocks": [{"t": "text", "b": "Hold the ball stud on its flats (or inner hex) and undo the nut at each end. Owners on Z4 M and M3 suspension jobs say holding the stud avoids breaking plastic joints."}]}, {"title": "Fit the new link", "blocks": [{"t": "text", "b": "Fit it, nuts on by hand, then torque while holding the stud."}, {"t": "torque", "label": "Front end link nut", "nm": 65, "c": {"level": "varies", "n": 3, "note": "Bentley transcriptions vary 59–65 Nm."}, "alt": [59]}], "only": ["f", "fr"]}, {"title": "Fit the rear link", "blocks": [{"t": "torque", "label": "Rear end link mounts", "nm": 34, "c": {"level": "medium", "n": 2, "note": "e46fanatics ''Yet Another Torque Guide'' (Bentley)."}}], "only": ["r", "fr"]}], "alsoReplace": [], "check": {"tab": "Check it", "title": "Old link check", "illId": "e46-sway-hero", "illCap": "Link locations.", "rows": [{"see": "Ball joint moves by hand", "means": "Worn out.", "do": "Replace."}, {"see": "Torn boot", "means": "Grit got in.", "do": "Replace."}, {"see": "Tight and smooth", "means": "Fine.", "do": "Look elsewhere for the clunk."}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": [], "disagreements": [], "sources": ["e46fanatics torque threads", "Bill''s Z4 M KW V3 install (link removal tip)", "BimmerWorld H&R sway bar listing"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-rsm', '{"id": "e46-rsm", "title": "Rear shock mounts & shock tower reinforcement", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Turner''s shock tower kit fits E36/E46 coupes, not convertibles", "category": "Suspension", "kind": "repair", "heroId": "e46-rsm-hero", "heroCap": "The rear shock mounts bolt to the body inside the trunk with two nuts each. Reinforcement plates spread the load on the sheet metal.", "glance": {"timeFirst": "2–3 hr", "timeRepeat": "1.5 hr", "difficulty": 2, "cost": "$60–250", "risk": "Reusing self-locking nuts · torn sheet metal under an old mount", "why": "A torn mount clunks over bumps and lets the shock hammer the tower. Replacing it is a trunk-and-underneath job.", "note": "Usually done with dampers or coilovers."}, "lifespan": {"headline": ["Inspect at every shock change"], "factors": ["Stiff springs", "Track use"], "confidence": {"level": "community", "n": 1, "note": ""}}, "variants": {"question": "Reinforce the towers too?", "options": [{"id": "mount", "label": "Mounts only"}, {"id": "reinf", "label": "Mounts + Turner reinforcement (coupe)", "when": "Not for convertibles", "brand": true}]}, "should": {"yesIf": ["Clunk from the rear over bumps", "Cracked rubber in the mount", "Stiffer springs or track use"], "codes": [], "notes": [], "confidence": {"level": "community", "n": 1, "note": ""}}, "parts": [{"name": "Rear shock mounts, pair", "price": "$60–120", "tier": "oe"}, {"name": "Self-locking nuts", "price": "$8", "tier": "oe"}, {"name": "Turner E36/E46 rear shock tower reinforcement kit", "price": "$100–150", "tier": "aftermarket", "only": ["reinf"]}], "aftermarket": [], "tools": [{"name": "Deep 13 mm socket"}, {"name": "16 mm socket"}, {"name": "Utility knife", "note": "Sound deadening"}, {"name": "Torque wrench"}], "before": ["Car on stands, rear wheels off, parking brake released."], "steps": [{"title": "Open up the trunk", "blocks": [{"t": "text", "b": "Pull the trunk side trim inward (it doesn''t need to come out) and cut through the soft sound-deadening over the shock tops."}]}, {"title": "Remove the shock", "blocks": [{"t": "text", "b": "Support the rear arm, remove the lower 16 mm bolt, then the two top nuts, and lower the shock out."}]}, {"title": "Inspect the tower", "blocks": [{"t": "text", "b": "Look at the sheet metal around the mount holes for cracks or a dished shape."}, {"t": "warn", "b": "Cracked metal needs welding before new mounts go in."}], "caution": true}, {"title": "Fit the reinforcement and mount", "blocks": [{"t": "text", "b": "Fit the reinforcement plate per Turner''s instructions, then the new mount on the shock."}, {"t": "text", "b": "Refit the shock with new nuts."}, {"t": "torque", "label": "Rear shock shaft to top mount", "nm": 14, "c": {"level": "medium", "n": 2, "note": "Bentley via e46fanatics."}}, {"t": "torque", "label": "Rear top mount to body", "nm": 28, "c": {"level": "medium", "n": 2, "note": "Bentley via e46fanatics."}}], "only": ["reinf"]}, {"title": "Fit the new mount", "blocks": [{"t": "text", "b": "Fit the new mount to the shock and refit with new nuts."}, {"t": "torque", "label": "Rear shock shaft to top mount", "nm": 14, "c": {"level": "medium", "n": 2, "note": "Bentley via e46fanatics."}}, {"t": "torque", "label": "Rear top mount to body", "nm": 28, "c": {"level": "medium", "n": 2, "note": "Bentley via e46fanatics."}}], "only": ["mount"]}, {"title": "Torque the lower bolt at ride height", "blocks": [{"t": "torque", "label": "Rear shock to trailing arm", "nm": 100, "c": {"level": "varies", "n": 3, "note": "Most Bentley transcriptions: 100 Nm; one quote 44 ft-lb."}, "alt": [60]}], "caution": true}], "alsoReplace": [{"name": "Rear dampers", "why": "They''re out."}], "check": {"tab": "Read the mount", "title": "What the old mount tells you", "illId": "e46-rsm-hero", "illCap": "Mount and tower inside the trunk.", "rows": [{"see": "Rubber split", "means": "Mount failed.", "do": "Replace both sides."}, {"see": "Tower dished or cracked", "means": "Sheet metal fatigued.", "do": "Weld repair, then reinforcement."}, {"see": "Intact", "means": "Fine.", "do": "Reinforce if tracking."}], "c": {"level": "community", "n": 1, "note": ""}}, "aftercare": ["Recheck nuts after a week."], "disagreements": [], "sources": ["Speed Academy E46 M3 coilover guide (trunk access)", "Turner Motorsport E36/E46 shock tower reinforcement listing", "e46fanatics torque threads"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-sway-bars', '{"id": "e46-sway-bars", "title": "Sway bars (front & rear)", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "E46 M3 coupe and convertible (H&R lists the cabrio)", "category": "Suspension", "kind": "upgrade", "heroId": "e46-sway-hero", "heroCap": "Stock bars are about 26 mm front and 21.5 mm rear. Front bar clamps to the frame rails and links to the struts; rear bar clamps to the subframe and links to the arms.", "glance": {"timeFirst": "2–4 hr", "timeRepeat": "1.5 hr", "difficulty": 2, "cost": "$360–800", "risk": "Bar binding from preloaded links · uneven adjustment holes side to side", "why": "A bigger, adjustable set reduces body roll and lets you tune the balance: stiffer front for stability, stiffer rear to fight understeer.", "note": "Fit them after springs or coilovers; lowering changes the link geometry."}, "lifespan": {"headline": ["Bars last; bushings and links wear"], "factors": ["Track use"], "confidence": {"level": "medium", "n": 1, "note": "Common practice."}}, "variants": {"questions": [{"question": "Which bars?", "options": [{"id": "front", "label": "Front only"}, {"id": "rear", "label": "Rear only"}, {"id": "both", "label": "Front and rear", "when": "BimmerWorld and Turner recommend a matched set"}]}, {"question": "Brand?", "options": [{"id": "hr", "label": "H&R 30 mm / 25 mm", "when": "Adjustable, Teflon-lined bushings", "brand": true}, {"id": "turner", "label": "Turner 30 mm / 25 mm", "when": "Adjustable, uses stock M3 links", "brand": true}, {"id": "otherbar", "label": "Other"}]}]}, "should": {"yesIf": ["You''ve fitted springs or coilovers", "Too much body roll", "You want to tune understeer"], "codes": [], "notes": [], "confidence": {"level": "medium", "n": 2, "note": "BimmerWorld, Turner."}}, "parts": [{"name": "H&R front 30 mm", "price": "$360", "tier": "aftermarket", "only": ["hr+front", "hr+both"]}, {"name": "H&R rear 25 mm", "price": "$330–380", "tier": "aftermarket", "only": ["hr+rear"]}, {"name": "H&R front/rear set 30/25 mm (72414)", "pn": "72414", "price": "$730–800", "tier": "aftermarket", "only": ["hr+both"]}, {"name": "Turner E46 M3 sway bar kit 30/25 mm", "price": "$650–800", "tier": "aftermarket", "only": ["turner"]}, {"name": "Front and rear bar bushings", "price": "$20–40", "tier": "oe", "note": "Usually included"}, {"name": "Adjustable end links (optional)", "price": "$120–200", "tier": "aftermarket", "note": "Recommended with coilovers"}], "aftermarket": [{"name": "H&R sway bars", "note": "30/25 mm, three settings, fit stock links", "price": "$360–800", "links": [{"store": "BimmerWorld", "url": "https://www.bimmerworld.com/Suspension-Steering/SwayBars/HR-Front-Rear-Sway-Bar-Set-E46-M3.html"}]}, {"name": "Turner Motorsport sway bars", "note": "30/25 mm (+4/+3.5 mm), designed around the stock M3 front links", "price": "$650–800", "links": [{"store": "Turner", "url": "https://www.turnermotorsport.com/BMW-E46-M3-Parts/c-1168-bmw-front-rear-sway-bar-kits/m-1016-turner-motorsport"}]}], "tools": [{"name": "13 mm and 16 mm sockets and wrenches"}, {"name": "Torque wrench 20–70 Nm"}], "before": ["Car level on stands, wheels on the ground or the suspension supported at ride height for final tightening."], "steps": [{"title": "Remove the front bar", "blocks": [{"t": "text", "b": "Disconnect both front end links at the bar, then remove the two bushing brackets from the frame rails and work the bar out."}, {"t": "note", "b": "Older front links often seize: plan on new links."}], "only": ["front", "both"]}, {"title": "Fit the front bar", "blocks": [{"t": "text", "b": "Fit the new bushings and brackets, start the bolts, connect the links in the chosen holes (same on both sides), then tighten."}, {"t": "torque", "label": "Front bar bushing brackets", "nm": 22, "c": {"level": "medium", "n": 2, "note": "e46fanatics ''Yet Another Torque Guide'' (Bentley)."}}, {"t": "torque", "label": "Front end link nut", "nm": 65, "c": {"level": "varies", "n": 3, "note": "Bentley transcriptions vary 59–65 Nm."}, "alt": [59]}], "only": ["front", "both"]}, {"title": "Remove the rear bar", "blocks": [{"t": "text", "b": "Disconnect the rear links and the two subframe brackets, and drop the bar out."}], "only": ["rear", "both"]}, {"title": "Fit the rear bar", "blocks": [{"t": "text", "b": "Fit bushings and brackets, connect the links in matching holes, tighten."}, {"t": "torque", "label": "Rear bar mounts", "nm": 22, "c": {"level": "medium", "n": 2, "note": "e46fanatics ''Yet Another Torque Guide'' (Bentley)."}}, {"t": "torque", "label": "Rear end link mounts", "nm": 34, "c": {"level": "medium", "n": 2, "note": "e46fanatics ''Yet Another Torque Guide'' (Bentley)."}}], "only": ["rear", "both"]}, {"title": "Set the balance", "blocks": [{"t": "text", "b": "Turner suggests starting with the front bar stiff and the rear soft, then stiffening the rear if the car understeers. A bar is stiffer in the holes farthest from its end."}]}], "alsoReplace": [{"name": "End links", "why": "Worn ball joints clunk and blunt the new bar."}], "check": {"tab": "Check it", "title": "After fitting", "illId": "e46-sway-hero", "illCap": "Front and rear bar mounting.", "rows": [{"see": "Link won''t line up without force", "means": "Preload.", "do": "Adjustable links or set at ride height."}, {"see": "Clunk over bumps", "means": "Loose bracket or worn link.", "do": "Re-torque, check links."}, {"see": "Car pushes wide", "means": "Too much front bar.", "do": "Soften front or stiffen rear."}], "c": {"level": "community", "n": 2, "note": "Common practice."}}, "aftercare": ["Re-check bracket torque after 100 miles."], "disagreements": [{"topic": "Bars before or after springs", "pos": "BimmerWorld recommends after springs/coilovers but says stock springs still benefit.", "call": "After, if you''re planning both."}], "sources": ["BimmerWorld H&R E46 M3 sway bar listings", "Turner Motorsport E46 M3 sway bar kits", "e46fanatics ''Yet Another Torque Guide''"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-roll-bar-cage', '{"id": "e46-roll-bar-cage", "title": "Roll bar & roll cage", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Prefab bars and cages here are coupe-only", "category": "Track & safety", "kind": "upgrade", "heroId": "e46-cage-hero", "heroCap": "A 4-point bar behind the front seats, or a 6-point cage that adds front legs to the A-pillars.", "glance": {"timeFirst": "6–12 hr", "timeRepeat": "—", "difficulty": 4, "cost": "$500–2,500", "risk": "Drilling into wiring or fuel lines · head clearance", "why": "A bar gives a solid harness mount and rollover protection for track days; a cage adds stiffness and is required in many race classes.", "note": "Autopower''s 6-point cage bolts in, but its diagonal and horizontal braces weld in permanently."}, "lifespan": {"headline": ["Permanent"], "factors": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "variants": {"questions": [{"question": "Which?", "options": [{"id": "bar", "label": "4-point bolt-in bar", "when": "Autopower Street-Sport, removable harness bar keeps the rear seat"}, {"id": "cage", "label": "6-point bolt-in cage", "when": "Autopower; braces weld in; SCCA/NASA"}, {"id": "weld", "label": "Full weld-in cage", "when": "Fabricator"}]}, {"question": "Sunroof?", "options": [{"id": "roof", "label": "Yes"}, {"id": "noroof", "label": "No"}]}]}, "should": {"yesIf": ["Track days with harnesses", "Racing"], "codes": [], "notes": ["Fit helmet-height padding wherever a head could reach the tubes."], "confidence": {"level": "medium", "n": 1, "note": ""}}, "parts": [{"name": "Autopower Street-Sport roll bar", "price": "$600–900", "tier": "aftermarket", "note": "Sunroof-specific version exists", "only": ["bar"]}, {"name": "Autopower 6-point bolt-in cage", "price": "$1,000–2,000", "tier": "aftermarket", "note": "Ships freight, built to order", "only": ["cage"]}, {"name": "SFI roll bar padding", "price": "$50", "tier": "aftermarket"}], "aftermarket": [], "tools": [{"name": "Drill and step bits"}, {"name": "Interior trim tools"}, {"name": "Welder (cage braces / weld-in)", "only": ["cage", "weld"]}], "before": ["Remove rear seat, side trim and carpet in the mounting areas.", "Check under every hole location for lines and wiring before drilling."], "steps": [{"title": "Strip the interior", "blocks": [{"t": "text", "b": "Remove seats, rear seat, trim and carpet where the bar lands."}]}, {"title": "Place and drill", "blocks": [{"t": "text", "b": "Set the bar in place, mark through the base plates, check underneath, then drill. Fit the backing plates."}], "caution": true, "only": ["bar", "cage"]}, {"title": "Bolt in and brace", "blocks": [{"t": "text", "b": "Bolt the bar to the floor through the backing plates. On the 6-point cage, weld the diagonal and horizontal braces."}], "only": ["bar", "cage"]}, {"title": "Brief the fabricator", "blocks": [{"t": "text", "b": "Ask for a cage built to your race body''s rules, tied into the rockers and pillars, with door bars and padding."}], "only": ["weld"]}, {"title": "Pad and refit", "blocks": [{"t": "text", "b": "Pad any tubes within reach of a helmet and refit the trim you can."}]}], "alsoReplace": [{"name": "Seats and harnesses", "why": "The harness bar is now there."}], "check": {"tab": "Check it", "title": "After fitting", "illId": "e46-cage-hero", "illCap": "Bar and cage layout.", "rows": [{"see": "Helmet clears the main hoop", "means": "Good fit.", "do": ""}, {"see": "Bar shifts when pushed", "means": "Loose mount.", "do": "Re-torque, check plates."}, {"see": "Tech inspection fails", "means": "Rules differ.", "do": "Check your sanctioning body."}], "c": {"level": "medium", "n": 1, "note": ""}}, "aftercare": ["Re-check mount bolts after the first track day."], "disagreements": [{"topic": "Bolt-in vs weld-in", "pos": "Bolt-in suits street/track day cars; weld-in is stiffer and required for many race classes.", "call": "Bolt-in bar for track days; weld-in for racing."}], "sources": ["Autopower via BMP Tuning and Vivid Racing", "Pro-Touring and NICOclub roll cage discussions"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-seats-harnesses', '{"id": "e46-seats-harnesses", "title": "Fixed-back seats, brackets & harnesses", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Coupe brackets listed (Planted)", "category": "Track & safety", "kind": "upgrade", "heroId": "e46-cage-hero", "heroCap": "Seats mount to coupe-specific brackets; harnesses anchor to the floor and a harness bar.", "glance": {"timeFirst": "3–5 hr", "timeRepeat": "1 hr", "difficulty": 3, "cost": "$800–3,000", "risk": "Airbag light from missing seat sensors · harness geometry", "why": "A fixed-back seat and harness hold you in place on track, so your hands steer instead of bracing.", "note": "Removing the factory seats disconnects belt pretensioners and the passenger occupancy sensor; that sets the airbag light."}, "lifespan": {"headline": ["Harnesses expire (check the SFI/FIA date)"], "factors": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "variants": {"question": "What are you fitting?", "options": [{"id": "hb", "label": "Harness bar + harnesses only"}, {"id": "seat", "label": "Seats + brackets + harnesses"}, {"id": "bk", "label": "Seat on OE sliders (Brey Krause)", "when": "Keeps factory sliders and belt", "brand": true}]}, "should": {"yesIf": ["Regular track days", "Roll bar fitted"], "codes": [], "notes": ["Harnesses without a bar or cage are unsafe in a rollover; don''t fit harnesses alone."], "confidence": {"level": "medium", "n": 1, "note": ""}}, "parts": [{"name": "Planted seat brackets (E46 coupe, side-specific)", "price": "$200–300 ea", "tier": "aftermarket", "only": ["seat"]}, {"name": "Brey Krause R-9224 seat mount kit", "price": "$300–400", "tier": "aftermarket", "only": ["bk"]}, {"name": "Fixed-back seat", "price": "$500–2,000", "tier": "aftermarket", "only": ["seat", "bk"]}, {"name": "Harness (6-point recommended)", "price": "$200–500", "tier": "aftermarket"}, {"name": "Airbag/occupancy emulator or resistor", "price": "$20–80", "tier": "aftermarket", "only": ["seat", "bk"]}], "aftermarket": [], "tools": [{"name": "Torx sockets for seat bolts"}, {"name": "Torque wrench"}], "before": ["Battery disconnected for 15+ minutes before unplugging seat connectors."], "steps": [{"title": "Remove the factory seat", "blocks": [{"t": "text", "b": "Slide forward, remove rear bolts; slide back, remove front bolts; unplug connectors with the battery off."}], "caution": true, "only": ["seat", "bk"]}, {"title": "Fit brackets and seat", "blocks": [{"t": "text", "b": "Bolt the seat to its brackets or sliders, then into the car at the factory points."}], "only": ["seat", "bk"]}, {"title": "Deal with the airbag light", "blocks": [{"t": "text", "b": "Turner/Planted note the warning comes from missing pretensioner and occupancy sensors. Use the correct emulator or resistor for each, and clear the codes with a scan tool."}, {"t": "warn", "b": "An emulator that keeps the light off can also disable the passenger airbag. Know what yours does."}], "only": ["seat", "bk"]}, {"title": "Fit the harnesses", "blocks": [{"t": "text", "b": "Anchor laps and subs to the floor points and shoulders to the harness bar at the angle the harness maker specifies."}]}], "alsoReplace": [], "check": {"tab": "Check it", "title": "After fitting", "illId": "e46-cage-hero", "illCap": "Seat and harness.", "rows": [{"see": "Airbag light off after clearing", "means": "Sensors emulated.", "do": ""}, {"see": "Light returns", "means": "A sensor still open.", "do": "Read the code (e.g. occupancy)."}, {"see": "Shoulder belts slope down steeply", "means": "Harness bar too low.", "do": "Re-mount."}], "c": {"level": "medium", "n": 2, "note": ""}}, "aftercare": [], "disagreements": [], "sources": ["Turner Motorsport Planted E46 coupe brackets", "Brey Krause R-9224 kit", "z4-forum airbag light threads"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e46-track-prep', '{"id": "e46-track-prep", "title": "Track day prep", "fits": "2001–2006 BMW M3 (E46) · 3.2 S54", "alsoFits": "Checklist guide", "category": "Track & safety", "kind": "repair", "heroId": "e46-track-hero", "heroCap": "Fluids, brakes, wheels and loose items: the things tech inspection checks.", "glance": {"timeFirst": "2–3 hr", "timeRepeat": "1 hr", "difficulty": 1, "cost": "$50–300", "risk": "Old brake fluid · loose wheels", "why": "Most track-day failures are preventable: boiled fluid, worn pads, low oil, loose wheels.", "note": "Bring a torque wrench to the track."}, "lifespan": {"headline": ["Before every event"], "factors": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "should": {"yesIf": ["Any track day"], "codes": [], "notes": [], "confidence": {"level": "medium", "n": 1, "note": ""}}, "parts": [{"name": "High-temp DOT 4 brake fluid", "price": "1 L", "tier": "aftermarket"}, {"name": "Track pads", "price": "$200–400", "tier": "aftermarket"}, {"name": "10W-60 for top-ups", "price": "1–2 L", "tier": "oe"}], "aftermarket": [], "tools": [{"name": "Torque wrench"}, {"name": "Tyre pressure gauge"}, {"name": "Pressure bleeder"}], "before": [], "steps": [{"title": "Brakes", "blocks": [{"t": "text", "b": "Fresh high-temp fluid, pads with plenty of life, rotors free of cracks."}]}, {"title": "Fluids", "blocks": [{"t": "text", "b": "Oil to the top of the dipstick range (with 10W-60), coolant full, no leaks."}]}, {"title": "Wheels and tyres", "blocks": [{"t": "text", "b": "Torque every wheel bolt, set pressures cold, check tyre condition."}, {"t": "torque", "label": "Wheel bolts", "nm": 120, "c": {"level": "medium", "n": 2, "note": "BMW''s current spec for 12 mm wheel bolts is 120 ±10 Nm (z4-forum, citing BMW; the older 100 Nm figure is obsolete)."}}]}, {"title": "Interior", "blocks": [{"t": "text", "b": "Remove floor mats and loose items, check seat and harness bolts."}]}], "alsoReplace": [], "check": 