-- ============================================================
-- TDC update-040  ·  SQL migration 041
-- BMW M3 (E46 · S54): full catalog roll-up
-- Turns the E46 generation live, adds powertrain s54, and 54 tasks + guides.
-- Uses the new 'Track & safety' category (needs the update-040 data.js + App.jsx push).
-- 100% safe to re-run: delete-then-insert in one transaction.
-- ============================================================

begin;

delete from guides where id like 'e46-%';
delete from tasks where id like 'e46-%';
delete from powertrains where id = 's54';

update brands set live = true where id = 'bmw';
update models set live = true where id = 'm3';
update generations set live = true, year_from = 2001, year_to = 2006 where id = 'm3-e46';




commit;
